window.kbParts["paper-9cef7c744bb98482"] = {"qs":{"政治理论必刷100题#1":{"stem":"下列语句与蕴含的哲理对应正确的是（      ）。","options":["槁竹有火，弗钻不然；土中有水，弗掘无泉——矛盾双方在一定条件下可以相互转化","蛩吟腐草中，雁落平沙地——事物的存在和发展受客观条件制约","伐木不自其本，必复生；塞水不自其源，必复流——办事情要抓住主要矛盾，把握问\n\n题的关键","蜗牛角上争何事，石火光中寄此身——透过现象看本质，把握事物的内在规律"],"answer":"C","analysis":"1.【答案】C\n\n  【解析】\n\n  本题考查马克思主义。\n\n  A 项错误，“槁竹有火，弗钻不然；土中有水，弗掘无泉”出自《淮南子·说林训》，\n\n意思是干枯的竹子能生火，但不去钻它就无法燃烧；地下藏有泉源，但不去挖掘就流不出泉\n\n水来。从哲理上看，“有火”与“不然”、“有水”与“无泉”是矛盾的双方（潜在状态与\n\n现实状态），而“钻”“掘”是促成矛盾转化的“条件”，根本上强调的是发挥主观能动性、\n\n创造必要条件才能实现目标。矛盾转化需体现对立双方的身份转变，诗句并未体现“矛盾双\n\n方在一定条件下可以相互转化”的哲理。\n\n  B 项错误，“蛩吟腐草中，雁落平沙地”出自《水浒传》，意思是蟋蟀在腐草中低吟，\n\n大雁落在平沙地上，通过秋虫鸣叫和候鸟栖息的意象，渲染出深秋萧瑟、凄凉的氛围。“制\n\n约”强调“客观条件对事物发展的限制”，而诗句仅客观描述生物的生存环境，并未体现\n\n“事物的存在和发展受客观条件制约”的哲理。\n\n  C 项正确，“伐木不自其本，必复生；塞水不自其源，必复流”出自《国语·晋语一》，\n\n意思是砍伐树木不把树根砍掉，必能重新生长；堵塞水不把源头堵住，必会重新流出。这里\n\n的“本”（树根）“源”（水源）是问题的“根本”，是决定事物发展的“主要矛盾”，不\n\n解决“根本”（主要矛盾）\n           ，问题就会反复出现，体现了“办事情要抓住主要矛盾，把握问\n\n题的关键”的哲理。\n\n  D 项错误，“蜗牛角上争何事，石火光中寄此身”出自唐代白居易的《对酒五首·其二》，\n\n意思是人活在世界上，就好像局促在那小小的蜗牛角上，空间是那样的狭窄，还有什么好争\n\n的呢？人生短暂，就像石头相撞的那一瞬间所发出的一点火光，人生就这样过去了。诗句以\n\n“蜗牛角”（比喻纷争渺小）“石火”（比喻人生短暂）为喻，劝人不必为琐事较真，核心\n\n是对“世俗纷争”与“人生价值”的本质性认知（即琐事的表象之下，其意义微不足道）。\n\n“透过现象看本质”强调对事物内在规律的把握，而诗句侧重的是对事物意义的主观评判，\n\n并未体现“透过现象看本质，把握事物的内在规律”的哲理。\n\n  故正确答案为 C。","figs":[],"state":"已标记","notes":[],"domains":["哲学"],"nature":"综合题","current":false,"links":[{"id":"k-2ea1431b5ab948ff","label":"唯物辩证法 · 主要矛盾对事物发展起决定作用","catalog_id":null,"type":"原理与机制","role":"直接考查","field":"answer","quote":"决定事物发展的“主要矛盾”","why":"树根和水源分别决定树木能否再生、水能否复流，说明解决问题要抓住主要矛盾。","origin":"逐题标记"},{"id":"s-9a37ff0e043151f2","label":"从古语的因果或条件关系辨析哲理","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"伐木不自其本，必复生；塞水不自其源，必复流","why":"需要从古语中识别使同一结果反复出现的关键条件，再核对对应的哲理。","origin":"逐题标记"}]},"政治理论必刷100题#2":{"stem":"习近平生态文明思想开辟了马克思主义人与自然关系理论新境界，指明了实现发展和\n\n保护协同共生的新路径。下列关于生态文明的重要论述与马克思主义哲学对应错误的是\n\n（      ）。","options":["保护生态环境就是保护生产力——矛盾双方相互转化","人与自然是生命共同体——物质世界普遍联系","生态兴则文明兴——认识与实践的具体的历史的统一","统筹山水林田湖草沙系统治理——整体与部分的辩证关系"],"answer":"C","analysis":"2.【答案】C\n\n  【解析】\n\n  本题考查马克思主义。\n\n  A 项正确，“保护生态环境就是保护生产力”这一科学论断揭示了生态环境保护与经济\n\n发展在特定条件下可以相互转化、相互促进的辩证关系，深刻体现了马克思主义唯物辩证法\n\n中矛盾双方相互转化的原理。\n\n  B 项正确，“人与自然是生命共同体”这一重要论断揭示了人与自然不是彼此割裂的孤\n\n立存在，而是处于相互依存、相互影响的有机整体之中，深刻体现了马克思主义哲学中物质\n\n世界普遍联系的原理。\n\n  C 项错误，“生态兴则文明兴”这一论断反映了马克思主义唯物史观中社会存在决定社\n\n会意识的原理，文明的兴衰（社会意识层面）从根本上取决于生态环境状况（社会存在层面），\n\n并未体现认识与实践的具体的历史的统一原理。\n\n  D 项正确，“统筹山水林田湖草沙系统治理”这一治理理念将生态系统视为一个有机统\n\n一的整体，而山水林田湖草沙等要素则是其相互关联的组成部分，体现了马克思主义哲学中\n\n整体与部分的辩证关系原理。\n\n  本题为选非题，故正确答案为 C。","figs":[],"state":"已标记","notes":[],"domains":["哲学","生态环境"],"nature":"综合题","current":false,"links":[{"id":"k-0059fcef164b4b83","label":"历史唯物主义 · 社会存在和社会意识的辩证关系","catalog_id":"626c91234ca39205","type":"原理与机制","role":"直接考查","field":"answer","quote":"“生态兴则文明兴”这一论断","why":"解析从生态环境状况影响文明兴衰入手，将这条论述归入社会存在决定社会意识。","origin":"逐题标记"},{"id":"k-b2837c1766d1a5a7","label":"认识论 · 实践和认识的辩证关系","catalog_id":"f2ae00df7a78f44c","type":"原理与机制","role":"解题依据","field":"question","quote":"认识与实践的具体的历史的统一","why":"这一原理要求认识与具体历史条件下的实践相统一，用这一判准可以检验题中的对应关系。","origin":"逐题标记"},{"id":"k-92430393b020ac6e","label":"唯物辩证法 · 联系的普遍性","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"question","quote":"人与自然是生命共同体——物质世界普遍联系","why":"人与自然相互依存、相互影响，据此可核实该组对应。","origin":"逐题标记"},{"id":"k-53c67f5e5cf3e97a","label":"唯物辩证法 · 整体与部分的辩证关系","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"question","quote":"统筹山水林田湖草沙系统治理——整体与部分的辩证关系","why":"把生态系统视为整体，把山水林田湖草沙视为相互关联的组成部分，可以解释系统治理的要求。","origin":"逐题标记"},{"id":"k-624d3a41b56365b8","label":"唯物辩证法 · 矛盾双方在一定条件下相互转化","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"answer","quote":"发展在特定条件下可以相互转化、相互促进的辩证关系","why":"按解析口径，核对这一组对应时要把握生态环境保护与经济发展相互转化的条件性。","origin":"逐题标记"},{"id":"s-d45531f0ca63ae30","label":"比对概念或对象之间的关系","catalog_id":"L05","type":null,"role":"直接考查","field":"question","quote":"生态兴则文明兴——认识与实践的具体的历史的统一","why":"需要先辨认论述中两个对象的关系，再核对它们能否分别对应所列原理中的概念。","origin":"逐题标记"}]},"政治理论必刷100题#3":{"stem":"习近平总书记强调，要发扬自我革命精神，落实管党治党责任，坚持党性党风党纪一\n\n起抓、正风肃纪反腐相贯通，把严的基调、严的措施、严的氛围长期坚持下去，努力营造风\n\n清气正的政治生态。下列说法与这段话蕴涵的马克思主义哲学原理相同的是（         ）。","options":["新事物是社会上先进的、富有创造力的人们创造性活动的产物","矛盾的特殊性寓于普遍性之中，并通过普遍性表现出来","任何事物的变化都有一个量变的积累过程，没有量变的积累，质变就不会发生","现象表现本质，本质总是通过一定的现象表现自己的存在"],"answer":"C","analysis":"3.【答案】C\n\n  【解析】\n\n  本题考查马克思主义。\n\n  A 项错误，在社会历史领域，新事物是社会上先进的、富有创造力的人们创造性活动的\n\n产物，它从根本上符合人民群众的利益和要求，能够得到人民群众的拥护，新事物必然战胜\n\n旧事物。选项说法正确，但与题干无关。\n\n  B 项错误，矛盾的普遍性即矛盾的共性，矛盾的特殊性即矛盾的个性。任何现实存在的\n\n事物的矛盾都是共性和个性的有机统一，共性寓于个性之中，没有离开个性的共性，也没有\n\n离开共性的个性。选项说法错误，应为“矛盾的普遍性寓于特殊性之中，并通过特殊性表现\n\n出来”。\n\n  C 项正确，量变是质变的必要准备。任何事物的变化都有一个量变的积累过程，没有量\n\n变的积累，质变就不会发生。题干中“把严的基调、严的措施、严的氛围长期坚持下去”体\n\n现了量变的积累，“风清气正的政治生态”即质变的结果。\n\n  D 项错误，本质决定现象，现象的存在和变化归根到底依赖于本质；现象表现本质，本\n\n质总是通过一定的现象表现自己的存在。本质与现象的相互依存表明：不表现现象的本质和\n\n不表现本质的现象都是不存在的。选项说法正确，但与题干无关。\n\n  故正确答案为 C。","figs":[],"state":"已标记","notes":[],"domains":["哲学"],"nature":"知识题","current":false,"links":[{"id":"k-839eda00ecccb4ba","label":"唯物辩证法 · 量变是质变的必要准备","catalog_id":null,"type":"原理与机制","role":"直接考查","field":"answer","quote":"量变是质变的必要准备。","why":"解析把长期坚持从严措施对应为量的积累，把形成风清气正的政治生态对应为质的变化。","origin":"逐题标记"}]},"政治理论必刷100题#4":{"stem":"中国特色社会主义进入新时代，处于新的历史方位，发展中不平衡、不协调、不可持\n\n续问题依然突出。解决这些问题，需要不断提高宏观调控的科学性和预见性，把握好宏观调\n\n控的方向、时机、节奏、重点和力度，通过科学的宏观调控为转型升级和改革创新提供重要\n\n环境保障。从马克思主义哲学角度看，以下理解不正确的是（         ）。","options":["物质决定意识，要求我们一切从实际出发，我国当前发展中的诸多问题是进行科学宏\n\n观调控的依据","意识对物质具有促进作用，科学的宏观调控政策可以促进问题的解决和经济社会发展","联系具有普遍性和客观性，科学宏观调控要综合考虑各方面因素","矛盾具有特殊性，新时代的问题需要采取与之相适应的宏观调控措施"],"answer":"B","analysis":"4.【答案】B\n\n  【解析】\n\n  本题考查马克思主义。\n\n  A 项正确，中国特色社会主义进入新时代，发展中存在着不平衡、不协调、不可持续等\n\n诸多实际问题，这些问题是客观存在的物质现象。物质决定意识，这是马克思主义哲学的基\n\n本原理之一。它要求我们在认识世界和改造世界的过程中，必须坚持一切从实际出发。正是\n\n基于这些实际问题，才需要进行科学的宏观调控，以制定出符合国情的政策和措施。\n\n  B 项错误，意识对物质具有能动作用，这种能动作用体现在意识能够正确地反映物质，\n\n并且反作用于物质。但意识的反作用具有双重性，正确的意识能够促进事物的发展，而错误\n\n的意识则会阻碍事物的发展。科学的宏观调控政策是基于对客观实际的正确认识和把握而制\n\n定的，属于正确的意识范畴，它能够推动问题的解决，对经济社会发展起到促进作用。而该\n\n项中“意识对物质具有促进作用”表述错误。\n\n  C 项正确，联系具有普遍性和客观性，世界上的一切事物都处在普遍联系之中，没有任\n\n何一个事物是孤立存在的。在我国的发展过程中，发展方式粗放、城乡区域发展差距和居民\n\n收入分配差距较大等各种问题相互关联、相互影响。因此，科学的宏观调控必须要综合考虑\n\n各方面因素，把握好各种问题之间的联系，统筹兼顾，才能实现经济社会的协调发展。\n\n  D 项正确，矛盾具有特殊性，即矛盾着的事物及其每一个侧面各有其特点。不同的事物\n\n有不同的矛盾，同一事物在发展的不同过程中和不同阶段上有不同的矛盾。中国特色社会主\n\n义进入了新时代，这是一个新的历史方位，与以往的发展阶段相比，面临着不同的问题和矛\n\n盾。这就要求我们在进行宏观调控时，必须根据新时代的特点和问题，采取与之相适应的措\n\n施，具体问题具体分析，才能有效地解决问题，推动经济社会的发展。\n\n  本题为选非题，故正确答案为 B。","figs":[],"state":"已标记","notes":[],"domains":["哲学"],"nature":"知识题","current":false,"links":[{"id":"k-584226db832d2835","label":"唯物论 · 物质和意识的辩证关系和方法论要求","catalog_id":"8c16fff9f9ff2785","type":"原理与机制","role":"直接考查","field":"answer","quote":"正确的意识能够促进事物的发展","why":"意识的能动作用具有双重性，正确的意识促进事物发展，错误的意识会阻碍事物发展。","origin":"逐题标记"}]},"政治理论必刷100题#5":{"stem":"“从机器人到脑机接口，我国新质生产力正在加速培育，当下前瞻布局的未来产业，\n\n在不远的将来，将切实改变你我的生活。”这一表述体现的马克思主义哲学原理是（     ）。","options":["人工智能的发展水平决定了社会存在的发展方向","生产力是人类社会发展和进步的最终决定力量","科学技术是推动社会发展的根本动力","新质生产力的培育中，量变的积累必然导致质变"],"answer":"B","analysis":"5.【答案】B\n\n  【解析】\n\n  本题考查马克思主义。\n\n  A 项错误，马克思主义哲学认为，社会存在决定社会意识，社会存在的发展方向是由生\n\n产力与生产关系的基本矛盾运动决定的。“人工智能”属于生产力发展的具体体现，是社会\n\n存在的一部分，它能影响社会存在的发展，但不能决定其发展方向。该项夸大了人工智能的\n\n作用，违背了社会发展的客观规律，故表述错误。\n\n  B 项正确，马克思主义哲学指出，生产力是社会基本矛盾运动中最基本的动力因素，是\n\n人类社会发展和进步的最终决定力量。生产力是社会进步的根本内容，是衡量社会进步的根\n\n本尺度。题干中“新质生产力正在加速培育”是生产力发展的具体体现，“未来产业，在不\n\n远的将来，将切实改变你我的生活”表明生产力的发展会推动社会生活等方面发生变化。\n\n  C 项错误，马克思主义哲学认为，社会发展的根本动力是社会基本矛盾，即生产力与生\n\n产关系的矛盾、经济基础与上层建筑的矛盾。科学技术是生产力的重要组成部分，能够推动\n\n生产力的发展，进而影响社会发展，但它并非推动社会发展的根本动力，故表述错误。\n\n  D 项错误，量变质变的辩证关系原理指出，量变是质变的必要准备，质变是量变的必然\n\n结果，但“量变的积累必然导致质变”表述不准确，量变只有达到一定程度才能引发质变。\n\n在新质生产力的培育中，技术的每一次质变，都需要持续的量变积累，故表述错误。\n\n  故正确答案为 B。","figs":[],"state":"已标记","notes":[],"domains":["哲学"],"nature":"知识题","current":false,"links":[{"id":"k-693b5a8af5c9c5cc","label":"历史唯物主义 · 生产力是社会发展的最终决定力量","catalog_id":null,"type":"原理与机制","role":"直接考查","field":"question","quote":"生产力是人类社会发展和进步的最终决定力量","why":"未来产业发展体现生产力的进步，生活变化体现生产力发展对社会的推动作用。","origin":"逐题标记"}]},"政治理论必刷100题#6":{"stem":"“天下之势，常系民心。民心顺，一顺百顺，一顺百兴。”历史和现实反复证明，人\n\n民是历史的创造者，是决定党和国家前途命运的根本力量。面对复杂形势和艰巨任务，我们\n\n要始终与人民想在一起、干在一起，汇聚起攻坚克难的强大力量。这段文字所蕴含的哲理是\n\n（     ）。","options":["量变是质变的必要准备，质变是量变的必然结果","人民群众是历史的主体，是社会变革的决定力量","矛盾的主要方面决定事物的性质，要抓主流","事物的发展是自我否定的辩证过程，其实质是“扬弃”"],"answer":"B","analysis":"6.【答案】B\n\n  【解析】\n\n  本题考查马克思主义。\n\n  A 项错误，量变与质变的辩证关系揭示了事物发展的形式和状态，强调事物的发展是量\n\n的积累到质的飞跃的过程。题干中未涉及“量的积累”“质的飞跃”等相关内容。\n\n  B 项正确，群众史观认为，人民群众是历史的主体，是社会物质财富和精神财富的创造\n\n者，是社会变革的决定力量。题干中“人民是历史的创造者，是决定党和国家前途命运的根\n\n本力量”直接体现了这一原理，强调“与人民想在一起、干在一起”是基于人民群众在历史\n\n发展中的主体地位，体现了历史唯物主义的根本观点。\n\n  C 项错误，矛盾主次方面的原理强调事物的性质主要由主要矛盾的主要方面决定，要求\n\n在认识事物时抓住主流、把握本质。题干未涉及“矛盾双方的主次地位”“主流与支流”等\n\n相关内容。\n\n  D 项错误，否定之否定规律揭示了事物发展是“肯定—否定—否定之否定”的辩证过程，\n\n其实质是“扬弃”（既克服又保留）。题干未体现“自我否定”“扬弃”等相关内容。\n\n  故正确答案为 B。","figs":[],"state":"已标记","notes":[],"domains":["哲学"],"nature":"知识题","current":false,"links":[{"id":"k-253af8e175729959","label":"历史唯物主义 · 人民群众是历史的主体和创造者","catalog_id":"d684a6870c190aec","type":"原理与机制","role":"直接考查","field":"question","quote":"人民群众是历史的主体，是社会变革的决定力量","why":"题干把事业发展和攻坚克难的力量归于人民，体现人民群众创造历史和推动社会变革的主体地位。","origin":"逐题标记"}]},"政治理论必刷100题#7":{"stem":"习近平总书记强调，建设全国统一大市场是构建新发展格局、推动高质量发展的需要，\n\n要认真落实党中央部署，加强协调配合，形成推进合力。对此，下列说法正确的是（     ）。\n\n    ①党中央关于建设全国统一大市场的部署能直接转化为现实成果\n\n    ②认识对实践具有反作用，科学理论能指导实践取得成功\n\n    ③对构建新发展格局的规律性认识由人类认知能力高低决定\n\n    ④“落实党中央部署，加强协调配合”可以检验我们对经济层面的规律性认识","options":["①②","①③","②④","③④"],"answer":"C","analysis":"7.【答案】C\n\n  【解析】\n\n  本题考查马克思主义。\n\n  ①错误，实践能够引起客观世界的某种变化，可以把人脑中观念的存在变为现实的存在，\n\n给人们提供现实的成果。“建设全国统一大市场的部署”需通过实践转化为现实成果，不能\n\n直接转化为现实成果。\n\n  ②正确，认识对实践具有反作用。在马克思主义看来，理论作为从感性认识到理性认识\n\n飞跃的产物，对行动起到重要的指导作用，科学理论能为实践提供科学指导。党中央关于“建\n\n设全国统一大市场”的部署是基于经济规律的科学理论，“要认真落实党中央部署，加强协\n\n调配合，形成推进合力”正是运用这一理论指导实践、推动工作的体现。\n\n  ③错误，实践是认识的来源，实践对认识起决定作用。对构建新发展格局的规律性认识\n\n是由我国的经济实践决定的，故“由人类认知能力高低决定”说法错误。\n\n  ④正确，认识的真理性只有在实践中才能得到检验和发展。只有将已经获得的理论运用\n\n到实践中去，通过实践的检验，正确的理论才能得到证实，错误的理论才能被发现、纠正或\n\n推翻，并在指导实践、实现自身的过程中得到完善和发展。现阶段我们“对经济层面的规律\n\n性认识”可以通过“落实党中央部署，加强协调配合”的实践进行检验。\n\n  故②④表述正确。\n\n  故正确答案为 C。","figs":[],"state":"已标记","notes":[],"domains":["哲学"],"nature":"知识题","current":false,"links":[{"id":"k-b2837c1766d1a5a7","label":"认识论 · 实践和认识的辩证关系","catalog_id":"f2ae00df7a78f44c","type":"原理与机制","role":"直接考查","field":"answer","quote":"认识的真理性只有在实践中才能得到检验和发展。","why":"经济实践是规律性认识的来源和检验途径，科学认识对实践有指导作用，部署需经实践才能转化为现实成果。","origin":"逐题标记"}]},"政治理论必刷100题#8":{"stem":"下列语句与哲学原理对应错误的是（       ）。","options":["坐地日行八万里，巡天遥看一千河——绝对运动和相对静止的辩证统一","心病终须心药治，解铃还须系铃人——具体问题具体分析","画饼充饥，望梅止渴——意识对物质具有决定作用","沉舟侧畔千帆过，病树前头万木春——新事物必然战胜旧事物"],"answer":"C","analysis":"8.【答案】C\n\n  【解析】\n\n  本题考查马克思主义。\n\n  A 项正确，“坐地日行八万里”说的是地球自转，体现了绝对运动，“巡天遥看一千河”\n\n是指以相对静止的视角观察宇宙，该语句体现了绝对运动和相对静止的辩证统一。\n\n  B 项正确，“心病终须心药治，解铃还须系铃人”强调针对具体问题需要找到特定解决\n\n方法，体现了矛盾的特殊性，即具体问题具体分析。\n\n  C 项错误，“画饼充饥”“望梅止渴”是通过心理暗示影响行为，体现了意识对物质的\n\n反作用。“意识对物质具有决定作用”说法错误。\n\n  D 项正确，“沉舟”“病树”象征旧事物，“千帆过”“万木春”象征新事物的兴起，\n\n体现了发展的实质是新事物的产生和旧事物的灭亡，即新事物必然战胜旧事物。\n\n  本题为选非题，故正确答案为 C。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","哲学"],"nature":"综合题","current":false,"links":[{"id":"k-584226db832d2835","label":"唯物论 · 物质和意识的辩证关系和方法论要求","catalog_id":"8c16fff9f9ff2785","type":"原理与机制","role":"直接考查","field":"answer","quote":"反作用。“意识对物质具有决定作用”说法错误。","why":"典故中的心理暗示体现意识的反作用，物质决定意识。","origin":"逐题标记"},{"id":"k-593504b9413772dc","label":"绝对运动和相对静止的辩证统一","catalog_id":null,"type":"原理与机制","role":"直接考查","field":"question","quote":"坐地日行八万里，巡天遥看一千河——绝对运动和相对静止的辩证统一","why":"人在地面相对静止，同时随地球运动。","origin":"逐题标记"},{"id":"k-c04caeb6f9018c9b","label":"矛盾的特殊性要求具体问题具体分析","catalog_id":null,"type":"原理与机制","role":"直接考查","field":"answer","quote":"体现了矛盾的特殊性，即具体问题具体分析。","why":"俗语强调依据问题的具体成因选择解决方法。","origin":"逐题标记"},{"id":"k-50188c15ba49f33f","label":"发展的实质与新事物必然战胜旧事物","catalog_id":null,"type":"原理与机制","role":"直接考查","field":"answer","quote":"发展的实质是新事物的产生和旧事物的灭亡，即新事物必然战胜旧事物。","why":"诗句以新旧交替表现发展的实质。","origin":"逐题标记"},{"id":"s-d45531f0ca63ae30","label":"比对概念或对象之间的关系","catalog_id":"L05","type":null,"role":"直接考查","field":"question","quote":"下列语句与哲学原理对应错误的是","why":"须根据语句所表达的关系核对对应原理。","origin":"逐题标记"}]},"政治理论必刷100题#9":{"stem":"农业农村是一个完整的自然生态系统，生态资源与产业发展有着千丝万缕的联系。例\n\n如，在温泉资源丰富的地区，可以发掘当地温泉资源，打造休闲度假区，通过旅游、养生、\n\n康体等产业增加当地农民收入，这启示我们（         ）。","options":["自然生态系统中任何两个事物之间都存在必然的联系","可以根据事物固有的联系，改变事物的状态，建立新的联系","打造休闲度假区属于人为事物的联系，这种联系具有主观性","自然生态系统中事物联系的多样性取决于人类实践活动的多样性"],"answer":"B","analysis":"9.【答案】B\n\n  【解析】\n\n  本题考查马克思主义。\n\n  A 项错误，事物之间的联系具有普遍性，但并不意味着任何两个事物之间都存在必然的\n\n联系，联系同样具有条件性，事物间的联系依赖于特定条件，条件的改变会影响联系的性质\n\n和结果。\n\n  B 项正确，联系是客观的，但并不意味着人对事物的联系是无能为力的，人们可以根据\n\n事物固有的联系，改变事物的状态，调整原有的联系，建立新的联系。利用温泉资源打造休\n\n闲度假区，满足人们旅游、养生等方面的需求，再以此增加农民收入，就是建立了新的联系。\n\n  C 项错误，联系是事物本身所固有的，不以人的意志为转移，具有客观性。事物的联系\n\n可以分为自在事物的联系和人为事物的联系。自在事物中的种种联系在人类产生以前就存在，\n\n不以人的意志为转移；人为事物的联系是人类实践的产物，尽管它们呈现出“人化”的特点，\n\n但仍然是客观的，不以人的意志为转移。\n\n  D 项错误，联系的多样性是指世界上的事物是多种多样的，事物之间的联系也是多种多\n\n样的。联系的主要方式有直接联系和间接联系、内部联系和外部联系、必然联系和偶然联系、\n\n本质联系和非本质联系等。联系是客观的，是事物本身所固有的，不以人的意志为转移，所\n\n以事物联系的多样性不是由人类实践活动的多样性决定的。\n\n  故正确答案为 B。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","哲学"],"nature":"综合题","current":false,"links":[{"id":"k-f9f9ac95a0ab3307","label":"联系的客观性与依据固有联系建立新联系","catalog_id":null,"type":"原理与机制","role":"直接考查","field":"question","quote":"可以根据事物固有的联系，改变事物的状态，建立新的联系","why":"温泉开发以既有资源条件为基础，通过实践形成新的产业联系，人为事物的联系仍具客观性。","origin":"逐题标记"},{"id":"k-95a458e4448b2cb6","label":"联系的普遍性与具体联系的条件性","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"answer","quote":"联系同样具有条件性，事物间的联系依赖于特定条件","why":"具体事物能否形成联系取决于相应条件。","origin":"逐题标记"},{"id":"s-9a37ff0e043151f2","label":"从案例关键事实匹配哲学原理","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"可以发掘当地温泉资源，打造休闲度假区","why":"须从资源条件和开发行为中识别所体现的联系原理。","origin":"逐题标记","originalId":"s-2041d480b4cfef0c"}]},"政治理论必刷100题#10":{"stem":"在人工智能飞速发展的当下，智能写作软件能够根据给定的主题和要求，快速生成\n\n逻辑连贯、语句通顺的文章。但也有人指出，智能写作软件虽能生成文字，却缺乏人类作家\n\n基于生活体验、情感感悟所赋予文章的独特灵魂与深度内涵。从马克思主义哲学角度看，这\n\n一现象体现了（       ）。\n\n     ①意识是人脑特有的机能，人工智能不具备人类意识所特有的能动性和创造性\n\n     ②矛盾具有特殊性，人类创作与人工智能写作有着本质区别，不可相互替代\n\n     ③实践是认识的来源，人类作家的生活实践是其创作灵感的来源，而人工智能没有实践\n\n活动\n\n     ④智能写作软件的逐渐成熟体现了人类的认识具有无限性和上升性","options":["仅①②③","仅②③④","仅①③④","①②③④"],"answer":"D","analysis":"10.【答案】D\n\n  【解析】\n\n  本题考查马克思主义。\n\n  ①正确，马克思主义哲学认为，意识是人脑的机能和属性，是客观世界的主观映象。人\n\n工智能是基于程序和算法运行的，没有像人类大脑那样的生理基础和意识产生机制，所以无\n\n法具备人类意识所特有的能动性和创造性，如主动思考、独特的思想和情感等。\n\n  ②正确，矛盾的特殊性是指不同事物的矛盾各有其特点。人类作家的创作融合了个人的\n\n生活经历、情感体验、价值观等多种因素，每一部作品都具有独特性；智能写作软件只是按\n\n照预设的程序和模式对数据进行处理和生成，缺乏真正的创造性和个性。二者有着本质的区\n\n别，不可相互替代。\n\n  ③正确，实践是认识的来源。人类作家通过亲身参与生活实践，获得丰富的素材和深刻\n\n的感悟，这些都是创作灵感的来源；智能写作软件只是对已有的数据和信息进行学习和模仿，\n\n没有进行实践活动，无法像人类作家那样从实践中获得直接的经验和灵感。\n\n  ④正确，人类对人工智能技术的研究和应用不断深入，使得智能写作软件不断发展和完\n\n善，这体现了人类的认识是无限发展的，并且是不断上升的。\n\n  故①②③④表述正确。\n\n  故正确答案为 D。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","哲学"],"nature":"综合题","current":false,"links":[{"id":"k-0d4ccc6ba461f479","label":"唯物论 · 意识的本质","catalog_id":"177ce0d26f22cba6","type":"原理与机制","role":"直接考查","field":"answer","quote":"意识是人脑的机能和属性，是客观世界的主观映象。","why":"用意识的产生基础和本质判断人工智能生成文本与人类意识的关系。","origin":"逐题标记"},{"id":"k-4ef68bf8fdda12c1","label":"矛盾的特殊性","catalog_id":null,"type":"原理与机制","role":"直接考查","field":"answer","quote":"矛盾的特殊性是指不同事物的矛盾各有其特点。","why":"人类创作与智能写作各有自身特点和生成机制。","origin":"逐题标记"},{"id":"k-693e1fbe51d7f57f","label":"实践是认识的来源","catalog_id":null,"type":"原理与机制","role":"直接考查","field":"answer","quote":"实践是认识的来源。","why":"作家的生活实践提供创作所需的直接经验和感悟。","origin":"逐题标记"},{"id":"k-da78bd0a5c965382","label":"认识发展的无限性和上升性","catalog_id":null,"type":"原理与机制","role":"直接考查","field":"answer","quote":"人类的认识是无限发展的，并且是不断上升的。","why":"题目用智能写作技术的研究和应用不断深入体现认识的发展。","origin":"逐题标记"},{"id":"s-9a37ff0e043151f2","label":"从案例关键事实匹配哲学原理","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"智能写作软件虽能生成文字，却缺乏人类作家","why":"须把人机创作差异和软件发展分别对应到相关原理。","origin":"逐题标记","originalId":"s-2041d480b4cfef0c"}]},"政治理论必刷100题#11":{"stem":"农业强国是社会主义现代化强国的根基，推进农业现代化是实现高质量发展的必然\n\n要求。关于农业强国，下列表述错误的是（         ）。","options":["健全耕地数量、质量、生态“三位一体”保护制度体系","建设农业强国，利器在科技，关键靠改革","产业振兴是乡村振兴的重中之重，要做好“土特产”文章","要把巩固拓展脱贫攻坚成果作为现代农业建设的首要任务"],"answer":"D","analysis":"11.【答案】D\n\n  【解析】\n\n  本题考查理论与政策。\n\n  A 项正确，2025 年 4 月 7 日，中共中央、国务院印发的《加快建设农业强国规划\n\n（2024—2035 年）》在“二、全方位夯实粮食安全根基，把中国人的饭碗端得更牢更稳”部\n\n分指出：“（一）全面加强耕地保护和建设。健全耕地数量、质量、生态‘三位一体’保护\n\n制度体系，改革完善耕地占补平衡制度，各类耕地占用纳入统一管理，完善补充耕地质量验\n\n收机制，确保达到平衡标准。”\n\n  B 项正确，2023 年 3 月 16 日，\n                       《求是》杂志发表的习近平总书记重要文章《加快建设农\n\n业强国   推进农业农村现代化》指出：“依靠科技和改革双轮驱动加快建设农业强国。建设\n\n农业强国，利器在科技，关键靠改革。必须协同推进科技创新和制度创新，开辟新领域新赛\n\n道，塑造新动能新优势，加快实现量的突破和质的跃升。”\n\n  C 项正确，2022 年 12 月 23 日至 24 日，习近平总书记在中央农村工作会议上的讲话指\n\n出：“全面推进乡村振兴是新时代建设农业强国的重要任务······产业振兴是乡村振\n\n兴的重中之重，要落实产业帮扶政策，做好‘土特产’文章，依托农业农村特色资源，向开\n\n发农业多种功能、挖掘乡村多元价值要效益，向一二三产业融合发展要效益，强龙头、补链\n\n条、兴业态、树品牌，推动乡村产业全链条升级，增强市场竞争力和可持续发展能力。”\n\n  D 项错误，2025 年 1 月 22 日，中共中央、国务院印发的《乡村全面振兴规划（2024—2027\n\n年）》在“三、加快现代农业建设，全方位夯实粮食安全根基”部分指出：“（五）提高粮\n\n食和重要农产品供给保障水平。把确保国家粮食安全作为现代农业建设的首要任务，全面落\n\n实粮食安全党政同责，坚持稳面积、增单产两手发力······”故“巩固拓展脱贫攻坚\n\n成果”表述有误，应为“确保国家粮食安全”。\n\n  本题为选非题，故正确答案为 D。","figs":[],"state":"已标记","notes":[],"domains":["政治理论"],"nature":"知识题","current":true,"links":[{"id":"k-caedc47bc4c7745b","label":"耕地数量、质量、生态三位一体保护制度","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"健全耕地数量、质量、生态“三位一体”保护制度体系","why":"耕地保护制度同时覆盖数量、质量和生态。","origin":"逐题标记"},{"id":"k-51cdd4a5233b6c21","label":"科技和改革双轮驱动建设农业强国","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"建设农业强国，利器在科技，关键靠改革。","why":"建设农业强国要求协同推进科技创新和制度创新。","origin":"逐题标记"},{"id":"k-fbc703040a1d4d3a","label":"产业振兴是乡村振兴的重中之重","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"产业振兴是乡村振兴的重中之重，要做好“土特产”文章","why":"产业振兴居于突出位置，依托农业农村特色资源发展乡村产业。","origin":"逐题标记"},{"id":"k-88abcb53c6b6b413","label":"确保国家粮食安全是现代农业建设的首要任务","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"把确保国家粮食安全作为现代农业建设的首要任务","why":"规划明确规定了现代农业建设的首要任务。","origin":"逐题标记"}]},"政治理论必刷100题#12":{"stem":"民营经济在中国经济中扮演着重要角色，推动了高质量发展，并受到政府的政策支\n\n持和重视。下列关于民营经济说法正确的有（        ）。\n\n     ①扎扎实实落实促进民营经济发展的政策措施是当前促进民营经济发展的工作重点\n\n     ②持续推进基础设施竞争性领域向各类经营主体公平开放\n\n     ③企业是经营主体，党和政府有责任创造良好发展环境，从根本上说，政府扶持是第一\n\n位的\n\n     ④坚决破除依法平等使用生产要素、公平参与市场竞争的各种障碍，主要涉及市场准入\n\n     ⑤着力解决拖欠民营企业账款问题要从地方支柱企业带头做起","options":["①②③","①④⑤","①②④","②③④"],"answer":"C","analysis":"12.【答案】C\n\n  【解析】\n\n  本题考查理论与政策。\n\n  2025 年 8 月 16 日出版的第 16 期《求是》杂志发表习近平总书记的重要文章《促进民\n\n营经济健康发展、高质量发展》（以下简称文章）\n                     。\n\n  ①正确，文章指出：“二、扎扎实实落实促进民营经济发展的政策措施。这是当前促进\n\n民营经济发展的工作重点。凡是党中央定了的就要坚决执行，不能含含糊糊、拖拖拉拉，不\n\n能打折扣。”\n\n  ②④正确，文章指出：“二、扎扎实实落实促进民营经济发展的政策措施······一\n\n是坚决破除依法平等使用生产要素、公平参与市场竞争的各种障碍。这主要涉及市场准入，\n\n就是要给予民营企业公平的发展机会。重点要加紧修订出台新版市场准入负面清单，让‘非\n\n禁即入’落地生根。持续推进基础设施竞争性领域向各类经营主体公平开放，支持有能力的\n\n民营企业牵头承担国家科技攻关任务。”\n\n  ③错误，文章指出：“三、广大民营企业和民营企业家要勇担时代重任，敢作敢为、善\n\n作善成。企业是经营主体。党和政府有责任创造良好发展环境，但从根本上说，企业发展内\n\n生动力是第一位的。广大民营企业和民营企业家要务实创新、克难奋进、加倍努力。”故“政\n\n府扶持是第一位的”表述有误，应为“企业发展内生动力是第一位的”。\n\n  ⑤错误，文章指出：“二、扎扎实实落实促进民营经济发展的政策措施······二\n\n是着力解决拖欠民营企业账款问题。解开这个疙瘩，要从政府、从国有企业特别是中央企业\n\n带头做起，落实责任，用好新增地方政府专项债等政策，切实加快清欠进度。”故“从地方\n\n支柱企业带头做起”表述有误，应为“从政府、从国有企业特别是中央企业带头做起”。\n\n  故①②④表述正确。\n\n  故正确答案为 C。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","经济"],"nature":"知识题","current":true,"links":[{"id":"k-f3e0db413c649131","label":"落实促进民营经济发展的政策措施是当前工作重点","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"扎扎实实落实促进民营经济发展的政策措施是当前促进民营经济发展的工作重点","why":"该部署明确了当前促进民营经济发展的工作重点。","origin":"逐题标记"},{"id":"k-450f6c8e0d8e6d14","label":"民营企业公平市场准入与基础设施竞争性领域公平开放","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"持续推进基础设施竞争性领域向各类经营主体公平开放","why":"破除妨碍平等使用生产要素和公平竞争的障碍主要涉及市场准入，基础设施竞争性领域开放是具体要求。","origin":"逐题标记"},{"id":"k-2508a8c3d2b8ffe2","label":"民营企业发展以内生动力为首要因素","catalog_id":null,"type":"观点与论证","role":"解题依据","field":"answer","quote":"企业发展内生动力是第一位的","why":"企业是经营主体，政府承担营造良好发展环境的责任。","origin":"逐题标记"},{"id":"k-512468f9d40a3d90","label":"政府和国有企业特别是中央企业带头清偿拖欠民营企业账款","catalog_id":null,"type":"制度与规则","role":"解题依据","field":"answer","quote":"从政府、从国有企业特别是中央企业带头做起","why":"政策明确了清欠工作的带头主体。","origin":"逐题标记"}]},"政治理论必刷100题#13":{"stem":"习近平总书记指出，开放带来进步，封闭必然落后。中国的发展离不开世界，世界\n\n的繁荣也需要中国。关于坚定不移推进高水平对外开放，下列说法正确的有（           ）。\n\n     ①作为一个超大规模经济体，中国将坚定推进高水平开放，扩大市场准入，缩减外资准\n\n入负面清单，提升现代服务业开放水平\n\n     ②要以“一带一路”建设为重点，坚持引进来和走出去并重，遵循共商共建共享原则，\n\n加强创新能力开放合作\n\n     ③我们要共同维护多边贸易体制，以联合国为核心的单边贸易体制是国际贸易的基石\n\n     ④对外开放是中国的基本国策，中国正在推进高水平对外开放，稳步扩大规则、规制、\n\n管理、标准等制度型开放\n\n     ⑤坚持党的全面领导，坚持以高水平开放为引领、以技术创新为核心，统筹发展和安全，\n\n高标准对接国际经贸规则","options":["①②④","①②③","③④⑤","①③⑤"],"answer":"A","analysis":"13.【答案】A\n\n  【解析】\n\n  本题考查理论与政策。\n\n  ①正确，2023 年 8 月 22 日，习近平总书记在 2023 年金砖国家工商论坛闭幕式上指出，\n\n中国将始终是世界发展的重要机遇。我们敞开大门，谁来同我们合作都欢迎。作为一个超大\n\n规模经济体，中国将坚定推进高水平开放，扩大市场准入，缩减外资准入负面清单，提升现\n\n代服务业开放水平。\n\n  ②正确，党的十九大报告指出，开放带来进步，封闭必然落后。中国开放的大门不会关\n\n闭，只会越开越大。要以“一带一路”建设为重点，坚持引进来和走出去并重，遵循共商共\n\n建共享原则，加强创新能力开放合作，形成陆海内外联动、东西双向互济的开放格局。\n\n  ③错误，2025 年 3 月 28 日，习近平总书记在会见国际工商界代表时指出，我们要共同\n\n维护多边贸易体制。以世贸组织为核心的多边贸易体制是国际贸易的基石。当前，世界开放\n\n指数不断下滑，单边主义、保护主义加剧，多边主义、自由贸易受到严峻挑战。故“以联合\n\n国为核心的单边贸易体制是国际贸易的基石”说法错误，应为“以世贸组织为核心的多边贸\n\n易体制是国际贸易的基石”。\n\n  ④正确，2025 年 3 月 28 日，习近平总书记在会见国际工商界代表时强调，对外开放是\n\n中国的基本国策，中国正在推进高水平对外开放，稳步扩大规则、规制、管理、标准等制度\n\n型开放，中国推进改革开放坚定不移，开放的大门只会越开越大，利用外资的政策没有变也\n\n不会变。\n\n  ⑤错误，2023 年 9 月 24 日，习近平总书记在关于深入推进自由贸易试验区建设的指示\n\n中强调，新征程上，要在全面总结十年建设经验基础上，深入实施自贸试验区提升战略，勇\n\n做开拓进取、攻坚克难的先锋，在更广领域、更深层次开展探索，努力建设更高水平自贸试\n\n验区。要坚持党的全面领导，坚持以高水平开放为引领、以制度创新为核心，统筹发展和安\n\n全，高标准对接国际经贸规则，深入推进制度型开放，加强改革整体谋划和系统集成，推动\n\n全产业链创新发展，让自贸试验区更好发挥示范作用。故“技术创新”说法错误，应为“制\n\n度创新”。\n\n  综上，①②④说法正确。\n\n  故正确答案为 A。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","经济"],"nature":"知识题","current":false,"links":[{"id":"k-ee8d3b24189131b4","label":"高水平对外开放的外资市场准入和现代服务业开放要求","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"中国将坚定推进高水平开放，扩大市场准入","why":"扩大市场准入包括缩减外资准入负面清单和提升现代服务业开放水平。","origin":"逐题标记"},{"id":"k-016883d61217faea","label":"“一带一路”","catalog_id":"10bee87fb2da039b","type":"制度与规则","role":"直接考查","field":"question","quote":"要以“一带一路”建设为重点，坚持引进来和走出去并重","why":"考查以共商共建共享为原则，把引进来、走出去和创新开放合作结合起来。","origin":"逐题标记"},{"id":"k-489d2240ea12e4b2","label":"以世界贸易组织为核心的多边贸易体制是国际贸易的基石","catalog_id":null,"type":"制度与规则","role":"解题依据","field":"answer","quote":"以世贸组织为核心的多边贸易体制是国际贸易的基石。","why":"明确核心组织和贸易体制性质即可判定相关陈述。","origin":"逐题标记"},{"id":"k-76f3ab01b88b79f9","label":"制度型开放","catalog_id":"31699340f47012e7","type":"概念与词义","role":"直接考查","field":"question","quote":"稳步扩大规则、规制、","why":"题目要求辨认规则、规制、管理、标准等制度层面的开放。","origin":"逐题标记"},{"id":"k-9a00bd0185c0ac82","label":"自由贸易试验区提升战略","catalog_id":"8e5b8d0370bf2daa","type":"制度与规则","role":"解题依据","field":"answer","quote":"坚持以高水平开放为引领、以制度创新为核心","why":"自贸试验区建设要求以制度创新为核心，并高标准对接国际经贸规则。","origin":"逐题标记"}]},"政治理论必刷100题#14":{"stem":"习近平总书记强调，要完善国家创新体系，激发各类创新主体活力，瞄准世界科技\n\n前沿，在加强基础研究、提高原始创新能力上持续用力。下列与我国科技创新相关的说法错\n\n误的是（         ）。","options":["构建企业主导的产学研用协同创新体系，助力传统产业改造升级","科技创新和产业创新，是发展新质生产力的基本路径","全面推进人工智能科技创新、产业发展和赋能应用，完善人工智能监管体制机制","推动科技创新和产业创新深度融合的关键是强化国有科研机构科技创新主体地位"],"answer":"D","analysis":"14.【答案】D\n\n  【解析】\n\n  本题考查理论与政策。\n\n  A 项正确，2025 年 4 月 25 日，习近平总书记在二十届中共中央政治局第二十次集体学\n\n习时的讲话中指出：“要推动人工智能科技创新与产业创新深度融合，构建企业主导的产学\n\n研用协同创新体系，助力传统产业改造升级，开辟战略性新兴产业和未来产业发展新赛道。”\n\n  B 项正确，2025 年 3 月 5 日，习近平总书记在参加十四届全国人大三次会议江苏代表团\n\n审议时的讲话中指出：“科技创新和产业创新，是发展新质生产力的基本路径。抓科技创新，\n\n要着眼建设现代化产业体系，坚持教育、科技、人才一起抓，既多出科技成果，又把科技成\n\n果转化为实实在在的生产力。”\n\n  C 项正确，2025 年 4 月 25 日，习近平总书记在二十届中共中央政治局第二十次集体学\n\n习时的讲话中指出：“党中央高度重视人工智能发展，近年来完善顶层设计、加强工作部署，\n\n推动我国人工智能综合实力整体性、系统性跃升。同时，在基础理论、关键核心技术等方面\n\n还存在短板弱项。要正视差距、加倍努力，全面推进人工智能科技创新、产业发展和赋能应\n\n用，完善人工智能监管体制机制，牢牢掌握人工智能发展和治理主动权。”\n\n  D 项错误，2024 年 6 月 24 日，习近平总书记在全国科技大会、国家科学技术奖励大会、\n\n两院院士大会上的讲话中指出：“扎实推动科技创新和产业创新深度融合，助力发展新质生\n\n产力······融合的关键是强化企业科技创新主体地位。要充分发挥科技领军企业龙头\n\n作用，鼓励中小企业和民营企业科技创新，支持企业牵头或参与国家重大科技项目。”故“强\n\n化国有科研机构科技创新主体地位”表述错误，应为“强化企业科技创新主体地位”。\n\n  本题为选非题，故正确答案为 D。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","科技"],"nature":"知识题","current":true,"links":[{"id":"k-1d1a7fe7dc6b2aa7","label":"企业主导的产学研用协同创新体系","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"构建企业主导的产学研用协同创新体系，助力传统产业改造升级","why":"政策明确企业在产学研用协同中的主导作用及其产业升级目标。","origin":"逐题标记"},{"id":"k-7918765de46b9f7d","label":"科技创新和产业创新是发展新质生产力的基本路径","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"科技创新和产业创新，是发展新质生产力的基本路径","why":"发展新质生产力既要形成科技成果，也要将成果转化为现实生产力。","origin":"逐题标记"},{"id":"k-82e38cce5dffdb53","label":"人工智能科技创新、产业发展、赋能应用与监管机制协同推进","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"全面推进人工智能科技创新、产业发展和赋能应用，完善人工智能监管体制机制","why":"部署同时明确了人工智能的发展任务和治理要求。","origin":"逐题标记"},{"id":"k-890ab1c528d1f9b1","label":"强化企业科技创新主体地位是科技创新与产业创新深度融合的关键","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"融合的关键是强化企业科技创新主体地位。","why":"融合部署明确要求强化企业的科技创新主体地位。","origin":"逐题标记"}]},"政治理论必刷100题#15":{"stem":"习近平总书记指出，农业农村农民问题是关系国计民生的根本性问题，必须始终把\n\n解决好“三农”问题作为全党工作重中之重。下列与乡村振兴相关的说法正确的有（   ）。\n\n  ①要把产业振兴作为乡村振兴的重中之重\n\n  ②要强化农村基层党组织建设，充分发挥基层党组织战斗堡垒作用\n\n  ③要一步到位把永久基本农田全部建成高标准农田\n\n  ④构建以小城镇为枢纽、以县城为节点的县域经济体系","options":["①④","②③","③④","①②"],"answer":"D","analysis":"15.【答案】D\n\n  【解析】\n\n  本题考查理论与政策。\n\n  ①正确，2023 年 3 月 5 日，习近平总书记参加十四届全国人大一次会议江苏代表团审\n\n议时强调，农业强国是社会主义现代化强国的根基，推进农业现代化是实现高质量发展的必\n\n然要求······要把产业振兴作为乡村振兴的重中之重，积极延伸和拓展农业产业链，\n\n培育发展农村新产业新业态，不断拓宽农民增收致富渠道。\n\n  ②正确，2022 年 4 月 11 日，习近平总书记在海南考察调研时强调，推动乡村全面振兴，\n\n关键靠人。要建设一支政治过硬、本领过硬、作风过硬的乡村振兴干部队伍，吸引包括致富\n\n带头人、返乡创业大学生、退役军人等在内的各类人才在乡村振兴中建功立业。要强化农村\n\n基层党组织建设，充分发挥基层党组织战斗堡垒作用。\n\n  ③错误，党的二十大报告在“四、加快构建新发展格局，着力推动高质量发展”部分指\n\n出：“（三）全面推进乡村振兴。全面建设社会主义现代化国家，最艰巨最繁重的任务仍然\n\n在农村······全方位夯实粮食安全根基，全面落实粮食安全党政同责，牢牢守住十八\n\n亿亩耕地红线，逐步把永久基本农田全部建成高标准农田，深入实施种业振兴行动。”故“一\n\n步到位”说法错误，应是“逐步”。\n\n  ④错误，2025 年 1 月，中共中央、国务院印发的《乡村全面振兴规划（2024—2027 年）》\n\n在“二、优化城乡发展格局，分类有序推进乡村全面振兴”部分指出：“（二）推进城乡融\n\n合发展。实施新一轮农业转移人口市民化行动，推行由常住地登记户口提供基本公共服务制\n\n度······构建以县城为枢纽、以小城镇为节点的县域经济体系。发挥各类产业园区带\n\n动作用，引导县域产业集聚发展。”故“以小城镇为枢纽、以县城为节点”说法错误，应是\n\n“以县城为枢纽、以小城镇为节点”。\n\n  故①②表述正确。\n\n  故正确答案为 D。","figs":[],"state":"已标记","notes":[],"domains":["政治理论"],"nature":"知识题","current":true,"links":[{"id":"k-fbc703040a1d4d3a","label":"产业振兴是乡村振兴的重中之重","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"要把产业振兴作为乡村振兴的重中之重","why":"乡村振兴把产业振兴放在突出位置，以拓展农业产业链和农民增收渠道。","origin":"逐题标记"},{"id":"k-0cb47e4f2df8e2ec","label":"强化农村基层党组织建设并发挥战斗堡垒作用","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"要强化农村基层党组织建设，充分发挥基层党组织战斗堡垒作用","why":"考查乡村全面振兴中的农村基层组织建设要求。","origin":"逐题标记"},{"id":"k-334f362cbe22e29b","label":"逐步把永久基本农田全部建成高标准农田","catalog_id":null,"type":"制度与规则","role":"解题依据","field":"answer","quote":"逐步把永久基本农田全部建成高标准农田","why":"政策明确了建设范围和逐步实施的节奏。","origin":"逐题标记"},{"id":"k-8b44047717058f13","label":"以县城为枢纽、以小城镇为节点的县域经济体系","catalog_id":null,"type":"制度与规则","role":"解题依据","field":"answer","quote":"构建以县城为枢纽、以小城镇为节点的县域经济体系。","why":"规划分别明确了县城和小城镇在县域经济体系中的功能定位。","origin":"逐题标记"}]},"政治理论必刷100题#16":{"stem":"习近平总书记强调，建设全国统一大市场是构建新发展格局、推动高质量发展的需\n\n要，要认真落实党中央部署，加强协调配合，形成推进合力。下列关于纵深推进全国统一大\n\n市场建设的说法不正确的是（   ）。","options":["依法依规治理企业低价无序竞争，技术改造落后产能，避免淘汰","规范政府采购和招标投标，加强对中标结果的公平性审查","规范地方招商引资，加强招商引资信息披露","持续开展规范涉企执法专项行动"],"answer":"A","analysis":"16.【答案】A\n\n  【解析】\n\n  本题考查理论与政策。\n\n  A 项错误，B、C、D 三项正确，2025 年 7 月 1 日，习近平总书记主持召开中央财经委员\n\n会第六次会议强调：“纵深推进全国统一大市场建设，要聚焦重点难点，依法依规治理企业\n\n低价无序竞争，引导企业提升产品品质，推动落后产能有序退出；规范政府采购和招标投标，\n\n加强对中标结果的公平性审查；规范地方招商引资，加强招商引资信息披露；着力推动内外\n\n贸一体化发展，畅通出口转内销路径，培育一批内外贸优质企业；持续开展规范涉企执法专\n\n项行动，健全有利于市场统一的财税体制、统计核算制度和信用体系；引导干部树立和践行\n\n正确政绩观，完善高质量发展考核体系和干部政绩考核评价体系。”故 A 项“技术改造落后\n\n产能，避免淘汰”表述错误，应为“引导企业提升产品品质，推动落后产能有序退出”。\n\n  本题为选非题，故正确答案为 A。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","经济"],"nature":"知识题","current":true,"links":[{"id":"k-89c1d03096d04b0b","label":"推进全国统一大市场建设","catalog_id":"a8fb7fb9427e00cc","type":"制度与规则","role":"直接考查","field":"answer","quote":"引导企业提升产品品质，推动落后产能有序退出","why":"会议将依法治理低价无序竞争、提升产品品质和推动落后产能有序退出一并列为重点举措。","origin":"逐题标记"}]},"政治理论必刷100题#17":{"stem":"作为一个超大规模经济体，中国将坚定推进高水平开放，扩大市场准入，缩减外资\n\n准入负面清单，提升现代服务业开放水平。下列与改革开放相关的表述正确的是（    ）。","options":["建设自由贸易试验区是党中央在新时代推进改革开放的重要战略举措，要坚持党的全\n\n面领导，坚持以高水平开放为引领、以理论创新为核心","改革开放是我国经济社会发展的动力，我们要不断扩大对外开放、提高对外开放水平，\n\n以改革促开放、促发展","开放是世界繁荣发展的必由之路，进博会已经成为中国构建新发展格局的窗口、推动\n\n高水平开放的平台、全球共享的国际公共产品","对外开放是中国的基本国策，中国正在推进高水平对外开放，稳步扩大规则、规制、\n\n管理、标准等要素型开放"],"answer":"C","analysis":"17.【答案】C\n\n  【解析】\n\n  本题考查理论与政策。\n\n  2025 年 7 月 16 日出版的第 14 期《求是》杂志上发表了习近平总书记的文章《坚定不\n\n移推进高水平对外开放》。这是习近平总书记 2012 年 12 月至 2025 年 4 月期间有关重要论述\n\n的节录。\n\n  A 项错误，2023 年 9 月 24 日习近平总书记在关于深入推进自由贸易试验区建设的指示\n\n中指出：“建设自由贸易试验区是党中央在新时代推进改革开放的重要战略举\n\n措······要坚持党的全面领导，坚持以高水平开放为引领、以制度创新为核心，统筹\n\n发展和安全，高标准对接国际经贸规则，深入推进制度型开放，加强改革整体谋划和系统集\n\n成，推动全产业链创新发展，让自贸试验区更好发挥示范作用。”故“以理论创新为核心”\n\n表述错误，应为“以制度创新为核心”。\n\n  B 项错误，2014 年 12 月 5 日习近平总书记在主持十八届中央政治局第十九次集体学习\n\n时的讲话中指出：“改革开放是我国经济社会发展的动力。不断扩大对外开放、提高对外开\n\n放水平，以开放促改革、促发展，是我国发展不断取得新成就的重要法宝。”故“以改革促\n\n开放”表述错误，应为“以开放促改革”。\n\n  C 项正确，2022 年 11 月 4 日习近平总书记以视频方式在第五届中国国际进口博览会开\n\n幕式上的致辞中指出：“5 年前，我宣布举办进博会，就是要扩大开放，让中国大市场成为\n\n世界大机遇。现在，进博会已经成为中国构建新发展格局的窗口、推动高水平开放的平台、\n\n全球共享的国际公共产品。开放是人类文明进步的重要动力，是世界繁荣发展的必由之路。”\n\n  D 项错误，2025 年 3 月 28 日习近平总书记在会见国际工商界代表时的讲话中指出：“对\n\n外开放是中国的基本国策，中国正在推进高水平对外开放，稳步扩大规则、规制、管理、标\n\n准等制度型开放。”故“要素型开放”表述错误，应为“制度型开放”。\n\n  故正确答案为 C。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","经济"],"nature":"知识题","current":false,"links":[{"id":"k-26ccecdf8d085d78","label":"中国国际进口博览会的三重定位","catalog_id":null,"type":"事实与事件","role":"直接考查","field":"answer","quote":"窗口、推动高水平开放的平台、","why":"进博会是中国构建新发展格局的窗口、推动高水平开放的平台和全球共享的国际公共产品。","origin":"逐题标记"},{"id":"k-0b56b67d9fed06b6","label":"自贸试验区以高水平开放为引领、以制度创新为核心","catalog_id":null,"type":"制度与规则","role":"解题依据","field":"answer","quote":"坚持以高水平开放为引领、以制度创新为核心","why":"自贸试验区建设的政策要求明确了制度创新的核心地位。","origin":"逐题标记"},{"id":"k-78ef3a7d043c5233","label":"以开放促改革、促发展","catalog_id":null,"type":"观点与论证","role":"解题依据","field":"answer","quote":"以开放促改革、促发展","why":"这一论述明确了扩大和提高对外开放带动改革与发展的作用方向。","origin":"逐题标记"},{"id":"k-76f3ab01b88b79f9","label":"制度型开放","catalog_id":"31699340f47012e7","type":"概念与词义","role":"解题依据","field":"answer","quote":"准等制度型开放","why":"规则、规制、管理、标准等方面的开放属于制度型开放。","origin":"逐题标记"}]},"政治理论必刷100题#18":{"stem":"习近平总书记十分重视对海洋资源的开发利用，对海洋经济有着高瞻远瞩的战略眼\n\n光，下列相关表述与海洋战略思想不符的是（       ）。","options":["海洋是高质量发展战略要地，发达的海洋经济是建设海洋强国的重要支撑","坚持陆海统筹、山海联动、资源融通，抓好海洋开发，向海洋要生产力、求新增长点","要把海洋生态文明建设纳入海洋开发总布局之中，科学合理开发利用海洋资源","建设强大的现代化海军是建设世界一流军队的重要标志，是建设海洋强国的唯一支撑"],"answer":"D","analysis":"18.【答案】D\n\n  【解析】\n\n  本题考查理论与政策。\n\n  A 项正确，2018 年 3 月 8 日，习近平总书记在参加十三届全国人大一次会议山东代表团\n\n审议时的讲话强调：“海洋是高质量发展战略要地。”2013 年 7 月 30 日，习近平总书记在\n\n主持就建设海洋强国研究进行的第八次集体学习时强调：“发达的海洋经济是建设海洋强国\n\n的重要支撑。要提高海洋开发能力，扩大海洋开发领域，让海洋经济成为新的增长点。”\n\n  B 项正确，2024 年 12 月 17 日，习近平总书记在听取海南省委和省政府工作汇报后强调：\n\n“坚持陆海统筹、山海联动、资源融通，抓好海洋开发，向海洋要生产力、求新增长点，建\n\n设海洋强省。”\n\n  C 项正确，2013 年 7 月 30 日，习近平在主持就建设海洋强国研究进行的第八次集体学\n\n习时强调：“要把海洋生态文明建设纳入海洋开发总布局之中，坚持开发和保护并重、污染\n\n防治和生态修复并举，科学合理开发利用海洋资源，维护海洋自然再生产能力。”\n\n  D 项错误，2017 年 5 月 24 日，习近平总书记在视察海军机关时强调：“建设强大的现\n\n代化海军是建设世界一流军队的重要标志，是建设海洋强国的战略支撑，是实现中华民族伟\n\n大复兴中国梦的重要组成部分。”故“是建设海洋强国的唯一支撑”表述有误，应为“是建\n\n设海洋强国的战略支撑”。\n\n  本题为选非题，故正确答案为 D。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","经济","生态环境","军事"],"nature":"知识题","current":false,"links":[{"id":"k-3f3ffa4c93024fcd","label":"现代化海军是建设海洋强国的战略支撑","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"是建设海洋强国的战略支撑","why":"现代化海军是建设世界一流军队的重要标志，其对海洋强国建设的定位是战略支撑。","origin":"逐题标记"},{"id":"k-8f6d28a0bb449b34","label":"发达的海洋经济是建设海洋强国的重要支撑","catalog_id":null,"type":"观点与论证","role":"解题依据","field":"question","quote":"发达的海洋经济是建设海洋强国的重要支撑","why":"海洋经济的支撑作用也表明建设海洋强国有多方面支撑。","origin":"逐题标记"},{"id":"k-212f4f35ce3e909e","label":"海洋开发坚持陆海统筹、山海联动和资源融通","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"坚持陆海统筹、山海联动、资源融通","why":"上述要求明确了统筹空间与资源、培育海洋经济增长点的开发思路。","origin":"逐题标记"},{"id":"k-8fa1518453a1a10a","label":"海洋生态文明建设纳入海洋开发总布局","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"防治和生态修复并举，科学合理开发利用海洋资源","why":"海洋开发应兼顾开发利用、生态保护、污染防治和生态修复，以维护海洋自然再生产能力。","origin":"逐题标记"}]},"政治理论必刷100题#19":{"stem":"下列与建成科技强国相关的表述错误的是（     ）。","options":["必须充分认识科技的战略先导地位和根本支撑作用","深入践行国际科技合作倡议，积极融入全球创新网络","充分发挥传统举国体制优势，加快推进高水平科技自立自强","坚持以科技创新需求为牵引，突出加强青年科技人才培养"],"answer":"C","analysis":"19.【答案】C\n\n  【解析】\n\n  本题考查理论与政策。\n\n  2025 年 4 月 1 日出版的第 7 期《求是》杂志发表了习近平总书记的重要文章《朝着建\n\n成科技强国的宏伟目标奋勇前进》（以下简称文章）。\n\n  A 项正确，文章指出：“中国式现代化要靠科技现代化作支撑，实现高质量发展要靠科\n\n技创新培育新动能。必须充分认识科技的战略先导地位和根本支撑作用，锚定 2035 年建成\n\n科技强国的战略目标，加强顶层设计和统筹谋划，加快实现高水平科技自立自强。”\n\n   B 项正确，文章指出：“第五······深入践行国际科技合作倡议······要\n\n积极融入全球创新网络······”\n\n   C 项错误，文章指出：“要以‘十年磨一剑’的坚定决心和顽强意志，只争朝夕、埋头\n\n苦干，一步一个脚印把这一战略目标变为现实。第一，充分发挥新型举国体制优势，加快推\n\n进高水平科技自立自强·······”故选项中“充分发挥传统举国体制优势”表述错\n\n误，应为“充分发挥新型举国体制优势”。\n\n   D 项正确，文章指出：“第四······坚持以科技创新需求为牵引······把\n\n加 快 建 设 国 家 战 略 人 才 力 量 作 为 重 中 之 重 ······ 突 出 加 强 青 年 科 技 人 才 培\n\n养······”\n\n   本题为选非题，故正确答案为 C。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","科技"],"nature":"知识题","current":true,"links":[{"id":"k-ce4897cd351e7073","label":"新型举国体制","catalog_id":"af1bf95a1262a21a","type":"制度与规则","role":"直接考查","field":"answer","quote":"充分发挥新型举国体制优势","why":"建成科技强国的部署要求发挥新型举国体制优势，加快推进高水平科技自立自强。","origin":"逐题标记"},{"id":"k-3dc1d8fb7e0b8bf8","label":"科技在中国式现代化中的战略先导地位和根本支撑作用","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"必须充分认识科技的战略先导地位和根本支撑作用","why":"中国式现代化需要科技现代化支撑，高质量发展需要科技创新培育新动能。","origin":"逐题标记"},{"id":"k-34526f421cea6390","label":"践行国际科技合作倡议并融入全球创新网络","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"深入践行国际科技合作倡议，积极融入全球创新网络","why":"该要求明确了建设科技强国中的国际科技合作方向。","origin":"逐题标记"},{"id":"k-360180bb9549ef86","label":"以科技创新需求牵引青年科技人才培养","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"坚持以科技创新需求为牵引，突出加强青年科技人才培养","why":"该要求明确了科技人才培养的需求导向及青年人才的优先地位。","origin":"逐题标记"}]},"政治理论必刷100题#20":{"stem":"金融是国民经济的血脉，是国家核心竞争力的重要组成部分。中央金融工作会议提\n\n出，要做好科技金融、绿色金融、普惠金融、养老金融、数字金融“五篇大文章”。关于做\n\n好金融“五篇大文章”，下列举措不恰当的是（        ）。","options":["坚持“先立后破”，完善绿色金融体系，统筹对绿色发展和低碳转型的支持","统筹运用股权、债权、保险等手段，为科技型企业提供全链条、全生命周期金融服务","发挥多层次资本市场支持科技创新关键枢纽作用，着力投广、投大、投长期、投硬科\n\n技","加大对残疾人、退役军人、新市民、高校家庭经济困难学生等群体就业就学的金融支\n\n持力度"],"answer":"C","analysis":"20.【答案】C\n\n   【解析】\n\n   本题考查理论与政策。\n\n   2025 年 3 月，\n             《国务院办公厅关于做好金融“五篇大文章”的指导意见》\n                                      （以下简称《意\n\n见》）印发。\n\n   A 项正确，《意见》在“二、金融‘五篇大文章’重点领域和主要着力点”部分指出：\n\n“（二）为经济社会发展全面绿色转型和美丽中国建设提供高质量金融供给。坚持‘先立后\n\n破’，完善绿色金融体系，统筹对绿色发展和低碳转型的支持，为确保国家能源安全、助力\n\n碳达峰碳中和形成有力支撑。”\n\n   B 项正确，C 项错误，\n              《意见》在“二、金融‘五篇大文章’重点领域和主要着力点”部\n\n分指出：“（一）加强对实现高水平科技自立自强和建设科技强国的金融支持。推进金融服\n\n务科技创新能力建设，统筹运用股权、债权、保险等手段，为科技型企业提供全链条、全生\n\n命周期金融服务，加强对国家重大科技任务和科技型中小企业的金融支持。发挥多层次资本\n\n市场支持科技创新关键枢纽作用，着力投早、投小、投长期、投硬科技。”故 C 项中“投广、\n\n投大”表述有误，应为“投早、投小”。\n\n   D 项正确，《意见》在“二、金融‘五篇大文章’重点领域和主要着力点”部分指出：\n\n“（三）完善多层次、广覆盖、可持续的普惠金融体系······提升乡村振兴金融服务\n\n水平，支持保障国家粮食安全和巩固拓展脱贫攻坚成果。加大对残疾人、退役军人、新市民、\n\n高校家庭经济困难学生等群体就业就学的金融支持力度。积极参与普惠金融全球治理。”\n\n   本题为选非题，故正确答案为 C。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","经济"],"nature":"知识题","current":true,"links":[{"id":"k-29516fdd1fe89293","label":"科技金融投资坚持投早、投小、投长期、投硬科技","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"着力投早、投小、投长期、投硬科技","why":"指导意见将这四项明确为多层次资本市场支持科技创新的投资导向。","origin":"逐题标记"},{"id":"k-b415207c512d47c6","label":"科技型企业全链条全生命周期金融服务","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"统筹运用股权、债权、保险等手段","why":"科技金融应结合多种金融工具，为科技型企业提供覆盖全链条和全生命周期的服务。","origin":"逐题标记"},{"id":"k-63a8452feac25c79","label":"绿色金融坚持先立后破并统筹支持绿色发展和低碳转型","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"坚持“先立后破”，完善绿色金融体系，统筹对绿色发展和低碳转型的支持","why":"指导意见把先立后破及统筹支持绿色发展和低碳转型列为绿色金融的政策要求。","origin":"逐题标记"},{"id":"k-06e2f20717ba1846","label":"普惠金融支持重点群体就业就学","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"高校家庭经济困难学生等群体就业就学的金融支持力度","why":"普惠金融的就业就学支持覆盖残疾人、退役军人、新市民和高校家庭经济困难学生等群体。","origin":"逐题标记"}]},"政治理论必刷100题#21":{"stem":"习近平总书记指出，不断扩大对外开放、提高对外开放水平，以开放促改革、促发\n\n展，是我国发展不断取得新成就的重要法宝。关于坚定不移推进高水平对外开放，下列表述\n\n正确的有（      ）。\n\n    ①建设自由贸易试验区，要坚持以高水平开放为引领、以制度创新为核心\n\n    ②改革和开放相辅相成、相互促进，改革必然要求开放，开放也必然要求改革\n\n    ③改革开放是最好的营商环境，要营造市场化、法治化、国际化一流营商环境\n\n    ④要以国际大循环吸引全球资源要素，增强国内国际两个市场两种资源联动效应","options":["②③","①②","③④","①④"],"answer":"B","analysis":"21.【答案】B\n\n   【解析】\n\n   本题考查理论与政策。\n\n   ①正确，2023 年 9 月 26 日，习近平总书记就深入推进自由贸易试验区建设作出重要指\n\n示强调：“新征程上，要在全面总结十年建设经验基础上，深入实施自贸试验区提升战\n\n略 ······ 要 坚 持 党 的 全 面 领 导 ， 坚 持 以 高 水 平 开 放 为 引 领 、 以 制 度 创 新 为 核\n\n心······”\n\n   ②正确，2015 年 9 月 15 日，习近平总书记主持召开中央全面深化改革领导小组第十六\n\n次会议时强调：“以开放促改革、促发展，是我国改革发展的成功实践。改革和开放相辅相\n\n成、相互促进，改革必然要求开放，开放也必然要求改革······”\n\n   ③错误，2023 年 11 月 27 日，习近平总书记在二十届中央政治局第十次集体学习时发\n\n表讲话指出：“法治同开放相伴而行，对外开放向前推进一步，涉外法治建设就要跟进一\n\n步······法治是最好的营商环境，要完善公开透明的涉外法律体系，加强知识产权保\n\n护，维护外资企业合法权益，用好国内国际两类规则，营造市场化、法治化、国际化一流营\n\n商环境······”故“改革开放”表述有误，应为“法治”。\n\n   ④错误，2022 年 10 月 16 日，习近平总书记在中国共产党第二十次全国代表大会上的\n\n报告中“四、加快构建新发展格局，着力推动高质量发展”部分指出：“（五）推进高水平\n\n对外开放。依托我国超大规模市场优势，以国内大循环吸引全球资源要素，增强国内国际两\n\n个市场两种资源联动效应，提升贸易投资合作质量和水平······”故“国际大循环”\n\n表述有误，应为“国内大循环”。\n\n   故①②表述正确。\n\n   故正确答案为 B。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","经济","法律"],"nature":"知识题","current":true,"links":[{"id":"k-0b56b67d9fed06b6","label":"自贸试验区以高水平开放为引领、以制度创新为核心","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"建设自由贸易试验区，要坚持以高水平开放为引领、以制度创新为核心","why":"深入推进自贸试验区建设的部署明确了开放引领和制度创新的核心地位。","origin":"逐题标记"},{"id":"k-e914c8dec1bd977f","label":"改革与开放相辅相成、相互促进","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"改革和开放相辅相成、相互促进，改革必然要求开放，开放也必然要求改革","why":"相互促进体现为改革和开放彼此提出要求，以开放促改革是其中的实践经验。","origin":"逐题标记"},{"id":"k-2ea2771de8e2be27","label":"法治是最好的营商环境","catalog_id":null,"type":"观点与论证","role":"解题依据","field":"answer","quote":"法治是最好的营商环境","why":"涉外法治通过透明规则、知识产权保护和外资权益保障支持一流营商环境建设。","origin":"逐题标记"},{"id":"k-6e663bb030341b18","label":"国内大循环","catalog_id":"b524569d860543e7","type":"观点与论证","role":"解题依据","field":"answer","quote":"依托我国超大规模市场优势，以国内大循环吸引全球资源要素","why":"国内大循环依托超大规模市场吸引全球资源要素，并增强国内国际市场和资源联动。","origin":"逐题标记"}]},"政治理论必刷100题#22":{"stem":"2024 年中央经济工作会议将“加大保障和改善民生力度，增强人民群众获得感幸福\n\n感安全感”列为 2025 年重点任务之一。下列与之相关的举措，正确的有（      ）\n                                          。\n\n    ①加强灵活就业和新就业形态劳动者权益保障\n\n    ②推动义务教育优质均衡发展，扎实推进优质本科扩容\n\n    ③实施医疗卫生强基工程，制定促进生育政策\n\n    ④营造绿色低碳产业健康发展生态，培育绿色建筑等新增长点\n\n    ⑤积极发展服务贸易、绿色贸易、数字贸易","options":["2 项","3 项","4 项","5 项"],"answer":"B","analysis":"22.【答案】B\n\n   【解析】\n\n   本题考查理论与政策。\n\n   2024 年 12 月 11 日至 12 日，中央经济工作会议在北京举行，习近平总书记出席会议并\n\n发表重要讲话。\n\n   ①②③正确，会议指出，九是加大保障和改善民生力度，增强人民群众获得感幸福感安\n\n全感。实施重点领域、重点行业、城乡基层和中小微企业就业支持计划，促进重点群体就业。\n\n加强灵活就业和新就业形态劳动者权益保障。落实好产业、就业等帮扶政策，确保不发生规\n\n模性返贫致贫，保障困难群众基本生活。推动义务教育优质均衡发展，扎实推进优质本科扩\n\n容。实施医疗卫生强基工程，制定促进生育政策。发展社区支持的居家养老，扩大普惠养老\n\n服务。坚持和发展新时代“枫桥经验”，加强公共安全系统施治。\n\n  ④错误，会议指出，八是协同推进降碳减污扩绿增长，加紧经济社会发展全面绿色转型。\n\n进一步深化生态文明体制改革。营造绿色低碳产业健康发展生态，培育绿色建筑等新增长\n\n点······故“营造绿色低碳产业健康发展生态，培育绿色建筑等新增长点”不属于\n\n“加大保障和改善民生力度，增强人民群众获得感幸福感安全感”的相关举措，而属于“协\n\n同推进降碳减污扩绿增长，加紧经济社会发展全面绿色转型”的相关举措。\n\n  ⑤错误，会议指出，四是扩大高水平对外开放，稳外贸、稳外资。有序扩大自主开放和\n\n单边开放，稳步扩大制度型开放，推动自由贸易试验区提质增效和扩大改革任务授权，加快\n\n推进海南自由贸易港核心政策落地。积极发展服务贸易、绿色贸易、数字贸易······故\n\n“积极发展服务贸易、绿色贸易、数字贸易”不属于“加大保障和改善民生力度，增强人民\n\n群众获得感幸福感安全感”的相关举措，而属于“扩大高水平对外开放，稳外贸、稳外资”\n\n的相关举措。\n\n  故①②③表述正确，共 3 项。\n\n  故正确答案为 B。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","公共管理","社会治理"],"nature":"知识题","current":true,"links":[{"id":"k-18c82678850d3bcc","label":"灵活就业和新就业形态劳动者权益保障","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"加强灵活就业和新就业形态劳动者权益保障。","why":"会议将这两类劳动者的权益保障纳入保障和改善民生重点任务。","origin":"逐题标记","originalId":"k-d6e6bf47f93ebf1c"},{"id":"k-b498e5e8efb08688","label":"义务教育优质均衡发展与优质本科扩容","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"推动义务教育优质均衡发展，扎实推进优质本科扩容","why":"这两项教育供给要求同属会议部署的保障和改善民生任务。","origin":"逐题标记"},{"id":"k-a8a2fb78a556548e","label":"医疗卫生强基工程","catalog_id":"6a7f675fdb5d48b7","type":"制度与规则","role":"直接考查","field":"answer","quote":"实施医疗卫生强基工程，制定促进生育政策。","why":"医疗卫生强基工程与促进生育政策均列入保障和改善民生任务。","origin":"逐题标记"},{"id":"k-5a20fdd9355d7fe3","label":"培育绿色建筑等增长点属于全面绿色转型部署","catalog_id":null,"type":"制度与规则","role":"解题依据","field":"answer","quote":"协同推进降碳减污扩绿增长，加紧经济社会发展全面绿色转型","why":"会议把绿色低碳产业发展和绿色建筑增长点列入全面绿色转型任务。","origin":"逐题标记"},{"id":"k-9d12deeca9714e70","label":"发展服务贸易、绿色贸易和数字贸易属于高水平对外开放部署","catalog_id":null,"type":"制度与规则","role":"解题依据","field":"answer","quote":"扩大高水平对外开放，稳外贸、稳外资","why":"会议把发展这三类贸易列入扩大高水平对外开放任务。","origin":"逐题标记"}]},"政治理论必刷100题#23":{"stem":"2025 年 7 月，中央城市工作会议在北京举行，习近平总书记出席会议并发表重要讲\n\n话，总结了新时代以来我国城市发展成就，分析了城市工作面临的形势，明确了做好城市工\n\n作的总体要求、重要原则、重点任务。下列关于该会议的相关表述正确的是（              ）。","options":["城市工作要转变城市发展理念，更加注重以经济发展为本","我国城市发展正从缓慢起步阶段转向大规模增量扩张为主的阶\n\n    段","城市工作的目标是建设美丽、低碳、便捷、包容的现代化人民城市","要分类推进以县城为重要载体的城镇化建设，继续推进农业转移人口市民化"],"answer":"D","analysis":"23.【答案】D\n\n  【解析】\n\n  本题考查理论与政策。\n\n  A 项错误，中央城市工作会议指出，城市工作要深刻把握、主动适应形势变化，转变城\n\n市发展理念，更加注重以人为本；转变城市发展方式，更加注重集约高效；转变城市发展动\n\n力，更加注重特色发展；转变城市工作重心，更加注重治理投入；转变城市工作方法，更加\n\n注重统筹协调。故“更加注重以经济发展为本”表述有误，应为“更加注重以人为本”。\n\n  B 项错误，中央城市工作会议指出，我国城镇化正从快速增长期转向稳定发展期，城市\n\n发展正从大规模增量扩张阶段转向存量提质增效为主的阶段。故“我国城市发展正从缓慢起\n\n步阶段转向大规模增量扩张为主的阶段”表述有误，应为“我国城市发展正从大规模增量扩\n\n张阶段转向存量提质增效为主的阶段”。\n\n  C 项错误，中央城市工作会议强调，当前和今后一个时期城市工作的总体要求是：坚持\n\n以习近平新时代中国特色社会主义思想为指导······以建设创新、宜居、美丽、韧性、\n\n文明、智慧的现代化人民城市为目标，以推动城市高质量发展为主题，以坚持城市内涵式发\n\n展为主线······走出一条中国特色城市现代化新路子。故“城市工作的目标是建设美\n\n丽、低碳、便捷、包容的现代化人民城市”表述有误，应为“城市工作的目标是建设创新、\n\n宜居、美丽、韧性、文明、智慧的现代化人民城市”。\n\n  D 项正确，中央城市工作会议部署了城市工作 7 个方面的重点任务。一是着力优化现代\n\n化城市体系。着眼于提高城市对人口和经济社会发展的综合承载能力，发展组团式、网络化\n\n的现代化城市群和都市圈，分类推进以县城为重要载体的城镇化建设，继续推进农业转移人\n\n口市民化，促进大中小城市和小城镇协调发展，促进城乡融合发展。\n\n  故正确答案为 D。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","公共管理","社会治理"],"nature":"知识题","current":true,"links":[{"id":"k-44a98cfad08a2caf","label":"以县城为重要载体推进城镇化与农业转移人口市民化","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"分类推进以县城为重要载体的城镇化建设，继续推进农业转移人口市民化","why":"会议将这两项举措纳入优化现代化城市体系的重点任务。","origin":"逐题标记"},{"id":"k-636882250cd85d31","label":"转变城市发展理念要更加注重以人为本","catalog_id":null,"type":"制度与规则","role":"解题依据","field":"answer","quote":"更加注重以人为本","why":"以人为本是会议对转变城市发展理念提出的明确要求。","origin":"逐题标记"},{"id":"k-5a52c06a53e893e2","label":"城市发展由大规模增量扩张转向存量提质增效","catalog_id":null,"type":"事实与事件","role":"解题依据","field":"answer","quote":"发展正从大规模增量扩张阶段转向存量提质增效为主的阶段","why":"会议把存量提质增效确定为我国城市发展新阶段的主要特征。","origin":"逐题标记"},{"id":"k-037f61aed9e69a4c","label":"现代化人民城市的创新、宜居、美丽、韧性、文明、智慧目标","catalog_id":null,"type":"制度与规则","role":"解题依据","field":"answer","quote":"文明、智慧的现代化人民城市为目标","why":"会议以创新、宜居、美丽、韧性、文明、智慧六项特征明确现代化人民城市的建设目标。","origin":"逐题标记","originalId":"k-81f451061ba6cbd8"}]},"政治理论必刷100题#24":{"stem":"2025 年 4 月 30 日，习近平总书记主持召开部分省区市“十五五”时期经济社会发\n\n展座谈会时强调，要适应形势变化，把握战略重点，科学谋划好“十五五”时期经济社会发\n\n展。以下相关举措不恰当的是（        ）。","options":["要逐步淘汰传统产业、积极发展新兴产业、超前布局未来产业","要不忘初心，把造福人民作为根本价值取向","多措并举稳就业、稳企业、稳市场、稳预期","要深入调查研究，坚持目标导向和问题导向相统一"],"answer":"A","analysis":"24.【答案】A\n\n  【解析】\n\n  本题考查理论与政策。\n\n  2025 年 4 月 30 日，习近平总书记主持召开部分省区市“十五五”时期经济社会发展座\n\n谈会并发表重要讲话。\n\n  A 项错误，习近平总书记强调：“‘十五五’时期，必须把因地制宜发展新质生产力摆\n\n在更加突出的战略位置，以科技创新为引领、以实体经济为根基，坚持全面推进传统产业转\n\n型升级、积极发展新兴产业、超前布局未来产业并举，加快建设现代化产业体系······”\n\n故“逐步淘汰传统产业”表述有误，应为“坚持全面推进传统产业转型升级”。\n\n  B 项正确，习近平总书记指出：“中国式现代化是全体人民共同富裕的社会主义现代化。\n\n谋划‘十五五’时期经济社会发展，要不忘初心，把造福人民作为根本价值取向，坚持在发\n\n展中保障和改善民生，稳步推动共同富裕。”\n\n  C 项正确，习近平总书记指出：“谋划‘十五五’时期经济社会发展，要前瞻性把握国\n\n际形势发展变化对我国的影响，因势利导对经济布局进行调整优化。要坚定不移办好自己的\n\n事，坚定不移扩大高水平对外开放，多措并举稳就业、稳企业、稳市场、稳预期，有效稳住\n\n经济基本盘，加快构建新发展格局，全面推动高质量发展······”\n\n  D 项正确，习近平总书记强调：“各地区谋划‘十五五’时期经济社会发展，要在全国\n\n大局中精准定位，加强规划衔接。要深入调查研究，坚持目标导向和问题导向相统一，在确\n\n定发展思路和战略举措时注重体现自身特色、发挥比较优势。”\n\n  本题为选非题，故正确答案为 A。","figs":[],"state":"已标记","notes":[],"domains":["政治理论"],"nature":"知识题","current":true,"links":[{"id":"k-4858add14304446a","label":"传统产业转型升级、新兴产业发展与未来产业布局并举","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"坚持全面推进传统产业转型升级","why":"产业部署要求全面推进传统产业转型升级，同时积极发展新兴产业、超前布局未来产业。","origin":"逐题标记"},{"id":"k-c10e89a5ead1add5","label":"把造福人民作为“十五五”发展谋划的根本价值取向","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"把造福人民作为根本价值取向","why":"发展谋划以造福人民为价值取向，在发展中保障和改善民生，稳步推动共同富裕。","origin":"逐题标记"},{"id":"k-916614127a8e1826","label":"稳就业、稳企业、稳市场、稳预期","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"多措并举稳就业、稳企业、稳市场、稳预期","why":"四项稳定工作共同服务于稳住经济基本盘。","origin":"逐题标记"},{"id":"k-535061fccc514e91","label":"地方“十五五”规划坚持目标导向和问题导向相统一","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"要深入调查研究，坚持目标导向和问题导向相统一","why":"各地应通过调查研究明确发展目标和现实问题，结合自身特色与比较优势确定举措。","origin":"逐题标记"}]},"政治理论必刷100题#25":{"stem":"党的十八大以来，习近平总书记多次就新发展理念作出重要论述。下列关于习近平\n\n总书记对新发展理念的论述，正确的有（         ）。\n\n    ①新质生产力具有高科技、高效能、高质量特征，符合新发展理念的先进生产力质态\n\n    ②要坚定不移贯彻新发展理念，更加自觉地把经济高速增长作为经济社会发展的优先目\n\n标\n\n    ③要完整准确全面贯彻新发展理念，统筹国内国际，抓好城乡融合、区域联动，优化生\n\n产力布局\n\n     ④要加强党对经济工作的领导，深化对社会主义经济建设规律的认识，完整准确全面贯\n\n彻新发展理念","options":["1 项","2 项","3 项","4 项"],"answer":"C","analysis":"25.【答案】C\n\n  【解析】\n\n  本题考查理论与政策。\n\n  ①正确，2024 年 1 月 31 日，习近平总书记在二十届中央政治局第十一次集体学习中发\n\n表讲话指出，新质生产力是创新起主导作用，摆脱传统经济增长方式、生产力发展路径，具\n\n有高科技、高效能、高质量特征，符合新发展理念的先进生产力质态。\n\n  ②错误，2024 年 5 月 27 日，习近平总书记在二十届中央政治局第十四次集体学习中发\n\n表讲话指出，要坚定不移贯彻新发展理念，更加自觉地把高质量充分就业作为经济社会发展\n\n的优先目标，使高质量发展的过程成为就业提质扩容的过程，提高发展的就业带动力。故“经\n\n济高速增长”表述有误，应为“高质量充分就业”。\n\n  ③正确，2025 年 3 月 5 日，习近平总书记参加十四届全国人大三次会议江苏代表团审\n\n议时讲话指出，要完整准确全面贯彻新发展理念，统筹国内国际，抓好城乡融合、区域联动，\n\n优化生产力布局，着力推动高质量发展。\n\n  ④正确，2025 年 6 月 13 日，习近平总书记在纪念陈云同志诞辰 120 周年座谈会中发表\n\n讲话指出，要加强党对经济工作的领导，深化对社会主义经济建设规律的认识，完整准确全\n\n面贯彻新发展理念，坚持有效市场和有为政府相结合，加快构建新发展格局，扎实推动高质\n\n量发展。\n\n  故①③④表述正确，共 3 项。\n\n  故正确答案为 C。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","经济"],"nature":"知识题","current":false,"links":[{"id":"k-07ef47dc10f156ad","label":"新质生产力","catalog_id":"cd67a12c3d0c8d5b","type":"概念与词义","role":"直接考查","field":"question","quote":"新质生产力具有高科技、高效能、高质量特征，符合新发展理念的先进生产力质态","why":"判定该表述需要识别新质生产力由创新主导、具有高科技高效能高质量特征的概念内涵。","origin":"逐题标记"},{"id":"k-1abeb450374ef8bd","label":"把高质量充分就业作为经济社会发展的优先目标","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"应为“高质量充分就业”","why":"优先目标是高质量充分就业，高质量发展的过程应带动就业提质扩容。","origin":"逐题标记"},{"id":"k-94be4678f0fc6ea8","label":"统筹国内国际、推进城乡融合和区域联动以优化生产力布局","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"要完整准确全面贯彻新发展理念，统筹国内国际，抓好城乡融合、区域联动","why":"统筹国内国际、抓好城乡融合和区域联动是贯彻新发展理念、优化生产力布局的要求。","origin":"逐题标记"},{"id":"k-94bd0deb6b482627","label":"加强党对经济工作的领导并完整准确全面贯彻新发展理念","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"要加强党对经济工作的领导，深化对社会主义经济建设规律的认识","why":"加强党的领导、深化对社会主义经济建设规律的认识和全面贯彻新发展理念是共同要求。","origin":"逐题标记"}]},"政治理论必刷100题#26":{"stem":"国内大循环是新发展格局的主体，是形成内生发展动力、把握发展主动权的基础。\n\n下列说法错误的是（       ）。","options":["企业是市场经济的细胞、经济活力的基础，外部冲击下小微企业首当其冲，要精准有\n\n效帮扶小微企业","就业事关经济稳定和社会安定，要千方百计稳定就业，支持企业稳岗，扩大各领域特\n\n别是服务业就业","围绕供需结构错配问题，完善扩大消费长效机制，形成市场主导的有效投资内生增长\n\n机制","健全新型举国体制，强化关键核心技术和前沿技术攻关，完善推动战略性产业发展政\n\n策和治理体系"],"answer":"A","analysis":"26.【答案】A\n\n  【解析】\n\n  本题考查理论与政策。\n\n  2025 年 6 月，求是网发布文章《如何进一步激发做强国内大循环的动力活力》\n                                        （以下简\n\n称文章）。\n\n  A 项错误，文章指出：“做强国内大循环，要着眼长远，也要立足当前······企\n\n业是市场经济的细胞、经济活力的基础，外部冲击下外贸企业首当其冲，要精准有效帮扶外\n\n贸企业，切实帮助解决实际困难······”故“外部冲击下小微企业首当其冲，要精准\n\n有效帮扶小微企业”说法错误，应为“外部冲击下外贸企业首当其冲，要精准有效帮扶外贸\n\n企业”。\n\n  B 项正确，文章指出：“······就业事关经济稳定和社会安定，要千方百计稳定\n\n就业，支持企业稳岗，扩大各领域特别是服务业就业，突出解决高校毕业生、农民工等就\n\n业······”\n\n  C 项正确，文章指出：“······围绕供需结构错配问题，完善扩大消费长效机制，\n\n形成市场主导的有效投资内生增长机制，加快培育完整内需体系；深化供给侧结构性改革，\n\n以自主可控、高质量的供给适应满足现有需求，创造引领新的需求······”\n\n  D 项正确，文章指出：“······聚焦科技创新和产业创新问题，健全相关规则和\n\n政策，健全新型举国体制，强化关键核心技术和前沿技术攻关，完善推动战略性产业发展政\n\n策和治理体系，加快形成同新质生产力更相适应的生产关系······”\n\n  本题为选非题，故正确答案为 A。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","经济"],"nature":"知识题","current":false,"links":[{"id":"k-42292c7e2f346d14","label":"外部冲击下精准帮扶外贸企业","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"外部冲击下外贸企业首当其冲","why":"外部冲击下优先实施精准有效帮扶的对象是外贸企业。","origin":"逐题标记"},{"id":"k-321e778afde7b8d8","label":"支持企业稳岗并重点扩大服务业就业","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"支持企业稳岗，扩大各领域特别是服务业就业","why":"做强国内大循环需要支持企业稳定岗位，并发挥服务业吸纳就业的作用。","origin":"逐题标记"},{"id":"k-e1ccdf6b39e1ca7f","label":"以扩大消费长效机制和市场主导的有效投资应对供需结构错配","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"形成市场主导的有效投资内生增长机制","why":"应对供需结构错配需要同时完善扩大消费长效机制和有效投资内生增长机制。","origin":"逐题标记"},{"id":"k-ce4897cd351e7073","label":"新型举国体制","catalog_id":"af1bf95a1262a21a","type":"制度与规则","role":"直接考查","field":"answer","quote":"健全新型举国体制，强化关键核心技术和前沿技术攻关","why":"健全新型举国体制是组织关键核心技术和前沿技术攻关、推动战略性产业发展的政策要求。","origin":"逐题标记"}]},"政治理论必刷100题#27":{"stem":"城镇化是现代化的必由之路，下列关于我国新型城镇化的表述，正确的有（   ）。\n\n     ①把提高城镇资源环境承载能力作为新型城镇化首要任务\n\n     ②加快补齐县城基础设施和公共服务短板，大力发展县域经济\n\n     ③拓宽城镇落户渠道，推行由常住地登记户口提供基本公共服务制度\n\n     ④发展现代化都市圈、优化空间格局，促进大中小城市和小城镇协调发展","options":["1 项","2 项","3 项","4 项"],"answer":"C","analysis":"27.【答案】C\n\n  【解析】\n\n  本题考查理论与政策。\n\n  ①错误，《深入实施以人为本的新型城镇化战略五年行动计划》在“一、总体要求”部\n\n分指出：“坚持以人为本。把推进农业转移人口市民化作为新型城镇化首要任务，坚持人民\n\n城市人民建、人民城市为人民······”故“提高城镇资源环境承载能力”表述错误，\n\n应为“推进农业转移人口市民化”。\n\n  ②正确，2025 政府工作报告在“三、2025 年政府工作任务”部分指出：“（八）推进\n\n新型城镇化和区域协调发展，进一步优化发展空间格局······深入实施新型城镇化战\n\n略行动。科学有序推进农业转移人口市民化······加快补齐县城基础设施和公共服务\n\n短板，大力发展县域经济，提高城乡规划、建设、治理融合水平······”\n\n  ③正确，《深入实施以人为本的新型城镇化战略五年行动计划》在“二、实施新一轮农\n\n业转移人口市民化行动”部分指出：“（一）发展方向。以进城农民工及其随迁家属为重点、\n\n兼顾城市间流动人口，进一步拓宽城镇落户渠道，努力缩小户籍人口城镇化率与常住人口城\n\n镇化率差距，推行由常住地登记户口提供基本公共服务制度······”\n\n  ④正确，2025 政府工作报告在“三、2025 年政府工作任务”部分指出：“（八）推进\n\n新型城镇化和区域协调发展，进一步优化发展空间格局······深入实施新型城镇化战\n\n略行动······发展现代化都市圈、优化空间格局，提升超大特大城市现代化治理水平，\n\n促进大中小城市和小城镇协调发展······”\n\n  故表述正确的有②③④，共 3 项。\n\n  故正确答案为 C。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","公共管理"],"nature":"知识题","current":true,"links":[{"id":"k-4795b507e2dd0725","label":"把推进农业转移人口市民化作为新型城镇化首要任务","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"把推进农业转移人口市民化作为新型城镇化首要任务","why":"行动计划把农业转移人口市民化列为以人为本的新型城镇化首要任务。","origin":"逐题标记"},{"id":"k-e5d2d791e4c48ef1","label":"补齐县城基础设施和公共服务短板并发展县域经济","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"加快补齐县城基础设施和公共服务短板，大力发展县域经济","why":"县城基础设施和公共服务补短板与发展县域经济同属新型城镇化部署。","origin":"逐题标记"},{"id":"k-c20354fbf1f418c6","label":"拓宽城镇落户渠道并推行由常住地登记户口提供基本公共服务制度","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"拓宽城镇落户渠道，推行由常住地登记户口提供基本公共服务制度","why":"行动计划将拓宽落户渠道与按常住地登记户口提供基本公共服务纳入农业转移人口市民化举措。","origin":"逐题标记"},{"id":"k-62d38cae7836cb1c","label":"现代化都市圈","catalog_id":"cbe2b045c4cc446b","type":"制度与规则","role":"直接考查","field":"question","quote":"发展现代化都市圈、优化空间格局，促进大中小城市和小城镇协调发展","why":"发展现代化都市圈的政策要求包括优化空间格局和促进各类城镇协调发展。","origin":"逐题标记"}]},"政治理论必刷100题#28":{"stem":"习近平总书记强调要守好实体经济这个根基，加快传统产业改造升级，壮大战略性\n\n新兴产业，超前布局未来产业，因地制宜发展新质生产力，建设具有国际竞争力的先进制造\n\n业集群。下列与制造业相关的说法正确的是（       ）。\n\n     ①要立足未来产业，扎实推进先进制造业高速发展，加快推动传统制造业升级\n\n     ②大力推动产业链供应链现代化，接续实施增强制造业核心竞争力行动\n\n  ③制造业要坚持高端化、智能化、绿色化方向，不断提高产品科技含量和附加值\n\n  ④制造业是国民经济的重要支柱，推进中国式现代化必须保持制造业合理比重","options":["①②③","①②④","①③④","②③④"],"answer":"D","analysis":"28.【答案】D\n\n  【解析】\n\n  本题考查理论与政策。\n\n  ①错误，2023 年 9 月 6 日至 8 日，习近平总书记在黑龙江考察时的讲话中指出：“要\n\n立足现有产业基础，扎实推进先进制造业高质量发展，加快推动传统制造业升级，发挥科技\n\n创新的增量器作用，全面提升三次产业，不断优化经济结构、调整产业结构。”故“要立足\n\n未来产业”“高速发展”说法错误，应为“要立足现有产业基础”“高质量发展”。\n\n  ②正确，2023 年 10 月 12 日，习近平总书记在进一步推动长江经济带高质量发展座谈\n\n会上的讲话中指出：“大力推动产业链供应链现代化，接续实施增强制造业核心竞争力行动，\n\n培育壮大先进制造业，加快发展战略性新兴产业和未来产业，促进数字经济和实体经济深度\n\n融合。”\n\n  ③正确，2025 年 1 月 22 日至 24 日，习近平总书记赴辽宁看望慰问基层干部群众时的\n\n讲话中指出：“制造业要坚持高端化、智能化、绿色化方向，不断提高产品科技含量和附加\n\n值，像鞍钢这样的国有大企业要为中国式现代化多作贡献。”\n\n  ④正确，2025 年 5 月 19 日至 20 日，习近平总书记在河南考察时的讲话中指出：“制\n\n造业是国民经济的重要支柱，推进中国式现代化必须保持制造业合理比重。现代制造业离不\n\n开科技赋能，要大力加强技术攻关，走自主创新的发展路子。”\n\n  故②③④表述正确。\n\n  故正确答案为 D。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","经济"],"nature":"知识题","current":false,"links":[{"id":"k-01f5c5547e1ff037","label":"立足现有产业基础推动先进制造业高质量发展和传统制造业升级","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"立足现有产业基础，扎实推进先进制造业高质量发展，加快推动传统制造业升级","why":"判定制造业发展要求时，需同时核对产业基础和高质量发展目标。","origin":"逐题标记"},{"id":"k-c3d30d65fc9dc5e6","label":"推进产业链供应链现代化并接续实施增强制造业核心竞争力行动","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"大力推动产业链供应链现代化，接续实施增强制造业核心竞争力行动","why":"产业链供应链现代化与增强制造业核心竞争力行动是配套部署。","origin":"逐题标记"},{"id":"k-46669862994b07d9","label":"制造业高端化、智能化、绿色化发展","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"制造业要坚持高端化、智能化、绿色化方向，不断提高产品科技含量和附加值","why":"制造业转型遵循高端化、智能化、绿色化方向，着眼于提升产品科技含量和附加值。","origin":"逐题标记","originalId":"k-c1fb622df43c2bf2"},{"id":"k-bf8075abdddcd377","label":"推进中国式现代化必须保持制造业合理比重","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"制造业是国民经济的重要支柱，推进中国式现代化必须保持制造业合理比重","why":"制造业的支柱地位是保持其合理比重的依据。","origin":"逐题标记"}]},"政治理论必刷100题#29":{"stem":"习近平总书记强调，要有效稳住经济基本盘，加快构建新发展格局，全面推动高质\n\n量发展。下列关于新发展格局说法不正确的是（     ）。","options":["国际循环越顺畅，越能形成对全球资源要素的引力场，越有利于构建以国内大循环为\n\n主体、国内国际双循环相互促进的新发展格局","畅通经济循环不能仅从单一环节入手，需要针对生产、分配、交换、消费各环节同时\n\n发力，使各种生产要素的组合在各环节有机衔接、循环流转","我国已成为 150 多个国家和地区的主要贸易伙伴，长期保持全球第二大外资流入国地\n\n位，国内大循环对世界各国具有强大吸引力和影响力","要加快构建新发展格局，依托我国超大规模市场优势吸引全球资源要素，增强国内国\n\n际两个市场两种资源联动效应"],"answer":"A","analysis":"29.【答案】A\n\n  【解析】\n\n  本题考查理论与政策。\n\n  A 项错误，2020 年第 21 期《求是》杂志发表的习近平总书记的重要文章《国家中长期\n\n经济社会发展战略若干重大问题》指出：“大国经济的优势就是内部可循环。我国有 14 亿\n\n人口，人均国内生产总值已经突破 1 万美元，是全球最大最有潜力的消费市场。居民消费优\n\n化升级，同现代科技和生产方式相结合，蕴含着巨大增长空间······扩大内需和扩大\n\n开放并不矛盾。国内循环越顺畅，越能形成对全球资源要素的引力场，越有利于构建以国内\n\n大循环为主体、国内国际双循环相互促进的新发展格局，越有利于形成参与国际竞争和合作\n\n新优势。”故选项中“国际循环越顺畅”表述错误，应是“国内循环越顺畅”。\n\n  B 项正确，\n       《人民日报》文章《深刻理解构建新发展格局的理论内涵与创新贡献》指出：\n\n“当前，我国正处于经济结构转型、产业优化升级、消费扩容提质的关键期，同时全国统一\n\n大市场建设还存在不少堵点、卡点问题。这对促进经济循环畅通无阻，实现供给和需求两端\n\n的动态平衡、良性互动提出了更高要求。从我国市场规模超大、发展不平衡不充分问题仍然\n\n存在等现实特征来看，畅通经济循环不能仅从单一环节入手，需要针对生产、分配、交换、\n\n消费各环节同时发力，使各种生产要素的组合在各环节有机衔接、循环流转，持续不断提高\n\n国民经济运行的质效。”\n\n  C 项正确，\n       《人民日报》文章《深刻理解构建新发展格局的理论内涵与创新贡献》指出：\n\n“今天，人类交往的世界性比过去任何时候都更深入、更广泛，各国相互联系和彼此依存比\n\n过去任何时候都更频繁、更紧密，经济全球化已经成为不可逆转的时代潮流。我国早已同世\n\n界经济体系深度融合，成为 150 多个国家和地区的主要贸易伙伴，长期保持全球第二大外资\n\n流入国地位，国内大循环对世界各国具有强大吸引力和影响力。”\n\n  D 项正确，2025 年第 1 期《求是》杂志发表的习近平总书记的重要文章《以中国式现代\n\n化全面推进强国建设、民族复兴伟业》指出：“推进中国式现代化，必须坚持独立自主、自\n\n立自强，坚持把国家和民族发展放在自己力量的基点上，坚持把我国发展进步的命运牢牢掌\n\n握在自己手中。要加快构建新发展格局，实现内部可循环，并依托我国超大规模市场优势吸\n\n引全球资源要素，增强国内国际两个市场两种资源联动效应。”\n\n  本题为选非题，故正确答案为 A。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","经济"],"nature":"知识题","current":false,"links":[{"id":"k-6e663bb030341b18","label":"国内大循环","catalog_id":"b524569d860543e7","type":"原理与机制","role":"直接考查","field":"answer","quote":"国内循环越顺畅，越能形成对全球资源要素的引力场","why":"畅通作为主体的国内大循环能够增强对全球资源要素的吸引力，促进国内国际双循环。","origin":"逐题标记"},{"id":"k-9c5da84e8594c75c","label":"畅通经济循环需要生产、分配、交换和消费各环节协同","catalog_id":null,"type":"原理与机制","role":"直接考查","field":"question","quote":"使各种生产要素的组合在各环节有机衔接、循环流转","why":"生产、分配、交换和消费各环节协同发力，才能促进生产要素顺畅流转。","origin":"逐题标记"},{"id":"k-1b74285f27479b26","label":"依托超大规模市场增强国内国际两个市场两种资源联动","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"增强国内国际两个市场两种资源联动效应","why":"构建新发展格局要利用国内超大规模市场吸引全球资源要素，发挥国内国际市场和资源的联动作用。","origin":"逐题标记"}]},"政治理论必刷100题#30":{"stem":"民族要复兴，乡村必振兴。下列关于推进乡村建设的重要表述正确的有（     ）\n                                          。\n\n  ①推动乡村全面振兴与新型城镇化有机结合，促进城乡产业发展、基础设施、公共服务\n\n一体化\n\n  ②开展以乡镇为统筹单元、以村为基本实施单元的全域土地综合整治\n\n  ③分类推进城乡供水一体化、集中供水规模化、小型供水规范化建设\n\n  ④以人员下沉为重点推进紧密型县域医共体建设，提升中心乡镇卫生院服务能力","options":["①②③","②③④","①②④","①③④"],"answer":"D","analysis":"30.【答案】D\n\n  【解析】\n\n  本题考查理论与政策。\n\n  ①正确，②错误，2025 年中央一号文件在“四、着力推进乡村建设”部分指出：“（十\n\n六）统筹县域城乡规划布局。顺应人口变化趋势，推动乡村全面振兴与新型城镇化有机结合，\n\n发挥县乡国土空间规划的空间统筹和要素保障作用，促进城乡产业发展、基础设施、公共服\n\n务一体化······在耕地总量不减少、永久基本农田布局基本稳定的前提下，开展以县\n\n域为统筹单元、以乡镇为基本实施单元的全域土地综合整治。”故“以乡镇为统筹单元、以\n\n村为基本实施单元”表述有误，应为“以县域为统筹单元、以乡镇为基本实施单元”。\n\n  ③正确，2025 年中央一号文件在“四、着力推进乡村建设”部分指出：“（十七）推\n\n动基础设施向农村延伸。分类推进城乡供水一体化、集中供水规模化、小型供水规范化建设，\n\n有条件的地方可推行农村供水县域统管和专业化管护。”\n\n  ④正确，2025 年中央一号文件在“四、着力推进乡村建设”部分指出：“（十八）提\n\n高农村基本公共服务水平······以人员下沉为重点推进紧密型县域医共体建设，提升\n\n中心乡镇卫生院服务能力，推动远程医疗服务体系建设。”\n\n  综上，①③④表述正确。\n\n  故正确答案为 D。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","公共管理"],"nature":"知识题","current":true,"links":[{"id":"k-26b61ed5615576c8","label":"乡村全面振兴与新型城镇化有机结合并推进城乡一体化","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"推动乡村全面振兴与新型城镇化有机结合","why":"县域城乡规划统筹旨在促进城乡产业发展、基础设施和公共服务一体化。","origin":"逐题标记"},{"id":"k-13c1a3a7e75457c3","label":"全域土地综合整治以县域为统筹单元、以乡镇为基本实施单元","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"应为“以县域为统筹单元、以乡镇为基本实施单元”","why":"县域负责统筹，乡镇承担基本实施，并应满足耕地总量不减少、永久基本农田布局基本稳定的前提。","origin":"逐题标记"},{"id":"k-5b54d9e218ae52a6","label":"分类推进城乡供水一体化、集中供水规模化和小型供水规范化","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"分类推进城乡供水一体化、集中供水规模化、小型供水规范化建设","why":"农村供水建设按供水形态分类推进一体化、规模化和规范化。","origin":"逐题标记"},{"id":"k-8301efeb35a1694f","label":"以人员下沉为重点推进紧密型县域医共体建设","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"以人员下沉为重点推进紧密型县域医共体建设，提升中心乡镇卫生院服务能力","why":"县域医共体建设以人员下沉为工作重点，并要求提升中心乡镇卫生院的服务能力。","origin":"逐题标记"}]},"政治理论必刷100题#31":{"stem":"开放是人类文明进步的重要动力，是世界繁荣发展的必由之路。下列关于我国对外\n\n开放相关表述正确的有（     ）。\n\n  ①有序扩大自主开放和单边开放，稳步扩大制度型开放\n\n  ②深化外贸体制改革，促进外贸稳质提量\n\n    ③持续扩大面向全球的高标准自由贸易区网络\n\n    ④拓展境外经贸合作区功能，发展中间品贸易","options":["①②③","②③④","①②④","①③④"],"answer":"D","analysis":"31.【答案】D\n\n  【解析】\n\n  本题考查理论与政策。\n\n  ①正确，2025 年 2 月 15 日，人民日报发表文章《扩大高水平对外开放——2025 年，中\n\n国经济这么干》指出：“以开放促改革、促发展，是我国现代化建设不断取得新成就的重要\n\n法宝，也是我国应对外部形势变化的主动作为······有序扩大自主开放和单边开放，\n\n稳步扩大制度型开放。”\n\n  ②错误，2025 年 2 月 15 日，人民日报发表文章《扩大高水平对外开放——2025 年，中\n\n国经济这么干》指出：“中国人民银行有关负责人表示，下一步，将会同相关部门推动意见\n\n各项举措落实落地······深化外贸体制改革，促进外贸稳量提质。”故“稳质提量”\n\n表述有误，应为“稳量提质”。\n\n  ③正确，2025 年政府工作报告在“三、2025 年政府工作任务”部分“（五）扩大高水\n\n平对外开放，积极稳外贸稳外资”中指出：“深化多双边和区域经济合作。持续扩大面向全\n\n球的高标准自由贸易区网络，推动签署中国－东盟自贸区 3.0 版升级协定，积极推动加入《数\n\n字经济伙伴关系协定》和《全面与进步跨太平洋伙伴关系协定》进程。”\n\n  ④正确，2025 年政府工作报告在“三、2025 年政府工作任务”部分“（五）扩大高水\n\n平对外开放，积极稳外贸稳外资”中指出：“稳定对外贸易发展。加大稳外贸政策力度，支\n\n持企业稳订单拓市场。优化融资、结算、外汇等金融服务，扩大出口信用保险承保规模和覆\n\n盖面，强化企业境外参展办展支持。促进跨境电商发展，完善跨境寄递物流体系，加强海外\n\n仓建设。拓展境外经贸合作区功能，发展中间品贸易，开拓多元化市场。”\n\n  综上，①③④表述正确。\n\n  故正确答案为 D。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","经济"],"nature":"知识题","current":true,"links":[{"id":"k-76f3ab01b88b79f9","label":"制度型开放","catalog_id":"31699340f47012e7","type":"制度与规则","role":"直接考查","field":"question","quote":"有序扩大自主开放和单边开放，稳步扩大制度型开放","why":"开放部署要求有序扩大自主开放和单边开放，同时稳步扩大制度型开放。","origin":"逐题标记"},{"id":"k-e8774128dc211731","label":"深化外贸体制改革并促进外贸稳量提质","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"深化外贸体制改革，促进外贸稳量提质","why":"外贸体制改革的目标是稳定外贸规模并提升外贸质量。","origin":"逐题标记"},{"id":"k-d11d9398a41ef59c","label":"持续扩大面向全球的高标准自由贸易区网络","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"持续扩大面向全球的高标准自由贸易区网络","why":"扩大高标准自由贸易区网络是深化多双边和区域经济合作的具体要求。","origin":"逐题标记"},{"id":"k-413643aca282b6b9","label":"拓展境外经贸合作区功能并发展中间品贸易","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"拓展境外经贸合作区功能，发展中间品贸易，开拓多元化市场","why":"拓展境外经贸合作区功能和发展中间品贸易是稳定对外贸易、开拓多元化市场的举措。","origin":"逐题标记"}]},"政治理论必刷100题#32":{"stem":"2024 年中央经济工作会议将以科技创新引领新质生产力发展，建设现代化产业体系\n\n列为 2025 年重点任务之一。下列关于建设现代化产业体系的表述不正确的是（          ）\n                                                。","options":["加强基础研究和关键核心技术攻关，超前布局重大科技项目","健全多层次金融服务体系，壮大耐心资本","综合整治“内卷式”竞争，规范市场主体行为","积极运用数字技术、绿色技术改造提升传统产业"],"answer":"C","analysis":"32.【答案】C\n\n  【解析】\n\n  本题考查理论与政策。\n\n  A、B、D 三项正确，C 项错误，2024 年中央经济工作会议明确了 2025 年经济工作重点\n\n内容，即“九项任务”，指出“二是以科技创新引领新质生产力发展，建设现代化产业体系。\n\n加强基础研究和关键核心技术攻关，超前布局重大科技项目，开展新技术新产品新场景大规\n\n模应用示范行动。开展‘人工智能+’行动，培育未来产业。加强国家战略科技力量建设。\n\n健全多层次金融服务体系，壮大耐心资本，更大力度吸引社会资本参与创业投资，梯度培育\n\n创新型企业。综合整治‘内卷式’竞争，规范地方政府和企业行为。积极运用数字技术、绿\n\n色技术改造提升传统产业。”故“规范市场主体行为”说法错误，应为“规范地方政府和企\n\n业行为”。\n\n  本题为选非题，故正确答案为 C。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","经济"],"nature":"知识题","current":true,"links":[{"id":"k-6905c95fceae446b","label":"加强基础研究和关键核心技术攻关并超前布局重大科技项目","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"加强基础研究和关键核心技术攻关，超前布局重大科技项目","why":"会议将基础研究、技术攻关和重大科技项目布局纳入现代化产业体系建设任务。","origin":"逐题标记"},{"id":"k-146b3490c92b8726","label":"健全多层次金融服务体系并壮大耐心资本","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"健全多层次金融服务体系，壮大耐心资本","why":"这是会议部署的现代化产业体系建设金融支持措施。","origin":"逐题标记"},{"id":"k-9fe805a639ce6c15","label":"“内卷式”竞争","catalog_id":"9a577840592b8b76","type":"制度与规则","role":"直接考查","field":"answer","quote":"综合整治‘内卷式’竞争，规范地方政府和企业行为。","why":"会议明确要求规范地方政府和企业行为，行为主体的表述决定该项正误。","origin":"逐题标记"},{"id":"k-c7e82c81295ae032","label":"传统产业","catalog_id":"1c1d38d153317062","type":"制度与规则","role":"直接考查","field":"question","quote":"积极运用数字技术、绿色技术改造提升传统产业","why":"运用数字技术和绿色技术改造提升传统产业属于会议部署的建设措施。","origin":"逐题标记"}]},"政治理论必刷100题#33":{"stem":"为大力提振消费，全方位扩大国内需求，中共中央办公厅、国务院办公厅印发的《提\n\n振消费专项行动方案》中，提出七大行动。根据该方案，下列措施属于“消费环境改善提升\n\n行动”的是（      ）。","options":["依法保障劳动者休息休假权益，不得违法延长劳动者工作时间","启动实施冰雪旅游提升计划，组织开展冰雪消费季等促消费活动","用好超长期特别国债资金，支持地方加力扩围实施消费品以旧换新","培育新型农业经营主体，因地制宜发展庭院经济、林下经济、民宿经济"],"answer":"A","analysis":"33.【答案】A\n\n  【解析】\n\n  本题考查理论与政策。\n\n  A 项正确，\n       《提振消费专项行动方案》中“六、消费环境改善提升行动”部分指出：“鼓\n\n励带薪年休假与小长假连休，实现弹性错峰休假。依法保障劳动者休息休假权益，不得违法\n\n延长劳动者工作时间。鼓励有条件的地方结合实际探索设置中小学春秋假。”\n\n  B 项错误，\n       《提振消费专项行动方案》中“三、服务消费提质惠民行动”部分指出：“启\n\n动实施冰雪旅游提升计划，组织开展冰雪消费季等促消费活动，建设一批冰雪主题高品质旅\n\n游景区、度假区，支持冰雪资源富集地区建设全球知名冰雪旅游高质量目的地。”\n\n  C 项错误，\n       《提振消费专项行动方案》中“四、大宗消费更新升级行动”部分指出：“用\n\n好超长期特别国债资金，支持地方加力扩围实施消费品以旧换新，推动汽车、家电、家装等\n\n大宗耐用消费品绿色化、智能化升级，支持换购合格安全的电动自行车，实施手机、平板、\n\n智能手表（手环）3 类数码产品购新补贴。”\n\n  D 项错误，\n       《提振消费专项行动方案》中“一、城乡居民增收促进行动”部分指出：“培\n\n育新型农业经营主体，因地制宜发展庭院经济、林下经济、民宿经济，落实农机报废更新补\n\n贴政策，强化产业联农带农。”\n\n  故正确答案为 A。","figs":[],"state":"待核","notes":["作答依赖该方案的具体部署，随题数据未注明印发年份，无法据此确认是否落在窗口内。"],"domains":["政治理论","经济"],"nature":"知识题","current":false,"links":[{"id":"k-68ab013ecdd81487","label":"消费环境改善提升行动中的劳动者休息休假权益保障","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"依法保障劳动者休息休假权益，不得违法延长劳动者工作时间","why":"方案将依法保障休息休假权益和禁止违法延长工时列入消费环境改善提升行动。","origin":"逐题标记"}]},"政治理论必刷100题#34":{"stem":"实施乡村振兴战略，是以习近平同志为核心的党中央着眼党和国家事业全局作出的\n\n重大决策，是新时代新征程“三农”工作的总抓手。下列与乡村振兴相关的表述不正确的是\n\n（     ）。","options":["乡村振兴战略是十九大报告中提出的战略，包括乡村产业、人才、文化、生态、组织\n\n振兴五个方面","到 2027 年，乡村全面振兴取得实质性进展，到 2035 年，乡村全面振兴取得决定性进\n\n展，农业现代化基本实现","促进县域城乡融合发展，鼓励县（市、区）将城镇常住人口全部纳入住房保障政策范\n\n围","要统筹不同区域，合理确定阶段性重点任务和推进时序，尊重客观规律，不超越发展\n\n阶段，不提脱离实际的目标"],"answer":"C","analysis":"34.【答案】C\n\n  【解析】\n\n  本题考查理论与政策。\n\n  A 项正确，2017 年 10 月 18 日，习近平总书记在党的十九大报告中提出了乡村振兴战略，\n\n包括乡村产业、人才、文化、生态、组织振兴五个方面。\n\n  B 项正确，2025 年 1 月，中共中央、国务院印发了《乡村全面振兴规划（2024-2027 年）》\n\n（以下简称《规划》）\n         。《规划》在“一、总体要求”部分指出：“主要目标是：到 2027 年，\n\n乡村全面振兴取得实质性进展，农业农村现代化迈上新台阶······到 2035 年，乡村\n\n全面振兴取得决定性进展，农业现代化基本实现，农村基本具备现代生活条件。”\n\n  C 项错误，2024 年 1 月 1 日，\n                      《中共中央   国务院关于学习运用“千村示范、万村整治”\n\n工程经验有力有效推进乡村全面振兴的意见》\n                   （以下简称《意见》）发布。《意见》在“四、\n\n提升乡村建设水平”部分指出：“（二十）促进县域城乡融合发展······实施新一轮\n\n农业转移人口市民化行动，鼓励有条件的县（市、区）将城镇常住人口全部纳入住房保障政\n\n策范围。”故“鼓励县（市、区）”表述错误，应为“鼓励有条件的县（市、区）”。\n\n  D 项正确，《规划》在“一、总体要求”部分指出：“工作中要做到······要统\n\n筹不同区域，合理确定阶段性重点任务和推进时序，尊重客观规律，不超越发展阶段，不提\n\n脱离实际的目标······”\n\n  本题为选非题，故正确答案为 C。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","社会治理"],"nature":"知识题","current":true,"links":[{"id":"k-6968cae8cf21349b","label":"乡村振兴战略","catalog_id":"64e0a00ebe161aac","type":"事实与事件","role":"直接考查","field":"answer","quote":"包括乡村产业、人才、文化、生态、组织振兴五个方面。","why":"党的十九大报告提出乡村振兴战略，解析据此确认战略的五个方面。","origin":"逐题标记"},{"id":"k-01c56f94ffc9caf9","label":"乡村全面振兴的2027年和2035年阶段目标","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"乡村全面振兴取得决定性进展，农业现代化基本实现，农村基本具备现代生活条件。","why":"规划明确到2027年取得实质性进展，到2035年取得决定性进展并基本实现农业现代化。","origin":"逐题标记"},{"id":"k-46b4352a61bc814b","label":"县域住房保障覆盖全体城镇常住人口的适用条件","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"鼓励有条件的县（市、区）将城镇常住人口全部纳入住房保障政","why":"政策鼓励具备条件的县（市、区）将城镇常住人口全部纳入住房保障范围。","origin":"逐题标记"},{"id":"k-a0bc27ccf9dfd2b3","label":"乡村全面振兴应分区域分阶段安排任务和时序","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"合理确定阶段性重点任务和推进时序，尊重客观规律，不超越发展阶段","why":"规划要求统筹区域差异，依据实际发展阶段部署重点任务和推进时序。","origin":"逐题标记"}]},"政治理论必刷100题#35":{"stem":"习近平总书记指出，中国将长期成为外资企业投资兴业的沃土，中国过去是、现在\n\n是、将来也必然是外商理想、安全、有为的投资目的地。关于外商来华投资的便利之处，下\n\n列说法正确的是（     ）。\n\n  ①对外开放是中国的基本国策，中国正在推进高水平对外开放，稳步扩大制度型开放\n\n  ②中国是全球第二大消费市场，拥有全球最大规模高等收入群体\n\n  ③中国尚未形成比较健全的利用外资法规政策体系和工作体系\n\n  ④中国长期保持政局稳定、社会安定，是世界公认的最安全国家之一","options":["①③","①④","③④","②③"],"answer":"B","analysis":"35.【答案】B\n\n  【解析】\n\n  本题考查理论与政策。\n\n  2025 年 3 月 28 日，习近平总书记会见国际工商界代表并发表重要讲话（以下简称讲话）。\n\n  ①正确，讲话指出：“对外开放是中国的基本国策，中国正在推进高水平对外开放，稳\n\n步扩大规则、规制、管理、标准等制度型开放。我愿在此重申，中国推进改革开放坚定不移，\n\n开放的大门只会越开越大，利用外资的政策没有变也不会变。”\n\n  ②错误，讲话指出：“中国是全球第二大消费市场，拥有全球最大规模中等收入群体，\n\n蕴含着巨大投资和消费潜力。”故该项中“拥有全球最大规模高等收入群体”表述有误，应\n\n为“拥有全球最大规模中等收入群体”。\n\n  ③错误，讲话指出：“中国已经形成比较健全的利用外资法规政策体系和工作体系。我\n\n们加强外商投资立法，推动贸易和投资自由化便利化，积极营造市场化、法治化、国际化一\n\n流营商环境······”故该项中“尚未形成”表述有误，应为“已经形成”。\n\n  ④正确，讲话指出：“中国长期保持政局稳定、社会安定，是世界公认的最安全国家之\n\n一。相信大家在华工作和生活，能够感受到以和为贵、和合共生的文明传承，体验到讲信修\n\n睦、亲仁善邻的社会氛围。”\n\n  故①④表述正确。\n\n  故正确答案为 B。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","经济"],"nature":"知识题","current":false,"links":[{"id":"k-76f3ab01b88b79f9","label":"制度型开放","catalog_id":"31699340f47012e7","type":"制度与规则","role":"直接考查","field":"question","quote":"对外开放是中国的基本国策，中国正在推进高水平对外开放，稳步扩大制度型开放","why":"稳步扩大规则、规制、管理、标准等制度型开放是推进高水平对外开放的政策方向。","origin":"逐题标记"},{"id":"k-97781378434526a5","label":"中国是全球第二大消费市场并拥有全球最大规模中等收入群体","catalog_id":null,"type":"事实与事件","role":"直接考查","field":"answer","quote":"中国是全球第二大消费市场，拥有全球最大规模中等收入群体，","why":"收入群体的准确层级是中等收入，这一事实用于判断消费市场表述。","origin":"逐题标记"},{"id":"k-250dc0a204f29da1","label":"中国已形成比较健全的利用外资法规政策体系和工作体系","catalog_id":null,"type":"事实与事件","role":"直接考查","field":"answer","quote":"中国已经形成比较健全的利用外资法规政策体系和工作体系。","why":"法规政策体系和工作体系的建设现状决定相关判断的正误。","origin":"逐题标记"},{"id":"k-2c6db5aa7569d12a","label":"中国长期保持政局稳定和社会安定","catalog_id":null,"type":"事实与事件","role":"直接考查","field":"answer","quote":"中国长期保持政局稳定、社会安定","why":"政局稳定和社会安定是题目考查的外商来华投资环境条件。","origin":"逐题标记"}]},"政治理论必刷100题#36":{"stem":"2025 年我们要扎实推进重点领域改革，着力破除制约发展的体制机制障碍，创造更\n\n加公平、更有活力的市场环境，下列与之相关的具体举措表述正确的有（        ）。\n\n  ①实施国有经济布局优化和结构调整指引，加快建立国有企业履行战略使命评价制度\n\n  ②政府要寓服务于管理之中，用服务的暖心增强企业的信心\n\n  ③打通市场准入退出等方面制约经济循环的卡点堵点，综合整治“内卷式”竞争\n\n  ④深化资本市场投融资综合改革，大力推动中长期资金入市","options":["①②③","②③④","①②④","①③④"],"answer":"D","analysis":"36.【答案】D\n\n  【解析】\n\n  本题考查理论与政策。\n\n  ①正确，②错误，2025 年政府工作报告在“三、2025 年政府工作任务”部分“（四）\n\n推动标志性改革举措加快落地，更好发挥经济体制改革牵引作用。扎实推进重点领域改革，\n\n着力破除制约发展的体制机制障碍，创造更加公平、更有活力的市场环境”中指出：“有效\n\n激发各类经营主体活力。坚持和落实‘两个毫不动摇’。高质量完成国有企业改革深化提升\n\n行动，实施国有经济布局优化和结构调整指引，加快建立国有企业履行战略使命评价制\n\n度······政府要寓管理于服务之中，用服务的暖心增强企业的信心。”\n\n  ③正确，2025 年政府工作报告在“三、2025 年政府工作任务”部分“（四）推动标志\n\n性改革举措加快落地，更好发挥经济体制改革牵引作用。扎实推进重点领域改革，着力破除\n\n制约发展的体制机制障碍，创造更加公平、更有活力的市场环境”中指出：“纵深推进全国\n\n统一大市场建设。加快建立健全基础制度规则，破除地方保护和市场分割，打通市场准入退\n\n出、要素配置等方面制约经济循环的卡点堵点，综合整治‘内卷式’竞争。”\n\n  ④正确，2025 年政府工作报告在“三、2025 年政府工作任务”部分“（四）推动标志\n\n性改革举措加快落地，更好发挥经济体制改革牵引作用。扎实推进重点领域改革，着力破除\n\n制约发展的体制机制障碍，创造更加公平、更有活力的市场环境”中指出：“深化财税金融\n\n体制改革。开展中央部门零基预算改革试点，支持地方深化零基预算改革······深化\n\n资本市场投融资综合改革，大力推动中长期资金入市，加强战略性力量储备和稳市机制建\n\n设。”\n\n  综上，①③④表述正确。\n\n  故正确答案为 D。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","经济","公共管理"],"nature":"知识题","current":true,"links":[{"id":"k-1dd18f359c18aba2","label":"国有经济布局优化和国有企业战略使命评价","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"实施国有经济布局优化和结构调整指引，加快建立国有企业履行战略使命评价制度","why":"报告将实施结构调整指引和建立战略使命评价制度列为国企改革举措。","origin":"逐题标记"},{"id":"k-e83c65f4421ead1f","label":"政府寓管理于服务之中","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"政府要寓管理于服务之中，用服务的暖心增强企业的信心。","why":"报告要求在服务中落实管理，管理和服务的位置决定表述正误。","origin":"逐题标记"},{"id":"k-89c1d03096d04b0b","label":"推进全国统一大市场建设","catalog_id":"a8fb7fb9427e00cc","type":"制度与规则","role":"直接考查","field":"question","quote":"打通市场准入退出等方面制约经济循环的卡点堵点，综合整治“内卷式”竞争","why":"报告将打通市场准入退出等方面的堵点与综合整治“内卷式”竞争列入统一大市场建设。","origin":"逐题标记"},{"id":"k-7f5afdaca5cfe92a","label":"深化资本市场投融资综合改革并推动中长期资金入市","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"深化资本市场投融资综合改革，大力推动中长期资金入市","why":"报告将资本市场投融资改革与推动中长期资金入市纳入财税金融体制改革。","origin":"逐题标记"}]},"政治理论必刷100题#37":{"stem":"农业强国是社会主义现代化强国的根基。下列举措属于“全方位夯实粮食安全根基，\n\n把中国人的饭碗端得更牢更稳”的有（        ）。\n\n  ①健全耕地数量、质量、生态“三位一体”保护制度体系\n\n  ②鼓励国内优势农产品参与国际竞争，推动农产品外贸转型升级\n\n  ③守牢 18.65 亿亩耕地和 15.46 亿亩永久基本农田保护红线\n\n  ④完善国家农产品加工技术研发体系，开发类别多样、品质优良的加工产品\n\n  ⑤健全保障耕地用于种植基本农作物管理体系，健全粮食主产区利益补偿机制","options":["2 项","3 项","4 项","5 项"],"answer":"B","analysis":"37.【答案】B\n\n  【解析】\n\n  本题考查理论与政策。\n\n  2025 年 4 月 7 日，中共中央、国务院印发《加快建设农业强国规划（2024－2035 年）》\n\n（以下简称《规划》）\n         。\n\n  ①③正确，\n      《规划》中“二、全方位夯实粮食安全根基，把中国人的饭碗端得更牢更稳”\n\n部分指出：“（一）全面加强耕地保护和建设。健全耕地数量、质量、生态‘三位一体’保\n\n护制度体系，改革完善耕地占补平衡制度，各类耕地占用纳入统一管理，完善补充耕地质量\n\n验收机制，确保达到平衡标准。守牢 18.65 亿亩耕地和 15.46 亿亩永久基本农田保护红线。”\n\n  ②错误，《规划》中“六、进一步深化农业对外合作，培育农业国际竞争新优势”部分\n\n指出：“（十九）提高农业国际竞争力。鼓励国内优势农产品参与国际竞争，推动农产品外\n\n贸转型升级。”故该项内容不属于“全方位夯实粮食安全根基，把中国人的饭碗端得更牢更\n\n稳”。\n\n  ④错误，《规划》中“五、全链条推进农业产业体系升级，提升农业综合效益”部分指\n\n出：“（十四）推动农产品加工流通优化升级。完善国家农产品加工技术研发体系，开发类\n\n别多样、品质优良的加工产品。”故该项内容不属于“全方位夯实粮食安全根基，把中国人\n\n的饭碗端得更牢更稳”。\n\n  ⑤正确，《规划》中“二、全方位夯实粮食安全根基，把中国人的饭碗端得更牢更稳”\n\n部分指出：“（三）健全粮食生产扶持政策。全面落实耕地保护和粮食安全党政同责，压实\n\n‘米袋子’保供责任。健全保障耕地用于种植基本农作物管理体系······健全粮食主\n\n产区利益补偿机制，完善产粮大县奖补制度。”\n\n  综上，①③⑤正确，共 3 项。\n\n  故正确答案为 B。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","经济"],"nature":"知识题","current":true,"links":[{"id":"k-caedc47bc4c7745b","label":"耕地数量、质量、生态三位一体保护制度","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"健全耕地数量、质量、生态“三位一体”保护制度体系","why":"规划将三位一体保护制度列为夯实粮食安全根基的耕地保护措施。","origin":"逐题标记"},{"id":"k-7710ae6ce7fdca2f","label":"耕地红线","catalog_id":"ac62f51740fec606","type":"制度与规则","role":"直接考查","field":"answer","quote":"守牢 18.65 亿亩耕地和 15.46 亿亩永久基本农田保护红线。","why":"规划明确两类保护红线的具体面积，并将其列入粮食安全任务。","origin":"逐题标记"},{"id":"k-6d2f594a351d9390","label":"粮食生产扶持中的耕地种植用途保障和主产区利益补偿","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"健全保障耕地用于种植基本农作物管理体系，健全粮食主产区利益补偿机制","why":"规划将保障耕地种植基本农作物和补偿粮食主产区利益共同列入粮食生产扶持政策。","origin":"逐题标记"}]},"政治理论必刷100题#38":{"stem":"习近平总书记指出，中国式现代化要靠科技现代化作支撑，实现高质量发展要靠科\n\n技创新培育新动能。下列与科技服务业发展相关的说法错误的是（           ）。","options":["培育壮大服务主体，引导科技服务机构专业化、市场化、平台化发展","推动质量持续提升，引导科技服务机构牢固树立质量第一的意识","发挥政府主导作用，引领科技服务机构健康秩序有效的高速发展","强化标准支撑引领，加强标准体系建设，强化标准实施"],"answer":"C","analysis":"38.【答案】C\n\n  【解析】\n\n  本题考查理论与政策。\n\n  2025 年 5 月，经国务院同意，工业和信息化部等九部门联合印发《关于加快推进科技\n\n服务业高质量发展的实施意见》（以下简称《实施意见》）。\n\n  A 项正确，《实施意见》明确，要优化科技服务业发展生态。一是培育壮大服务主体，\n\n引导科技服务机构专业化、市场化、平台化发展。\n\n  B 项正确，《实施意见》明确，要优化科技服务业发展生态。三是推动质量持续提升，\n\n引导科技服务机构牢固树立质量第一的意识，推广应用先进质量管理和方法，加强服务质量\n\n管理。\n\n  C 项错误，《实施意见》并未提及，且一般说“市场主导”，而非“政府主导”。\n\n  D 项正确，《实施意见》明确，要优化科技服务业发展生态。四是强化标准支撑引领，\n\n加强标准体系建设，加快研制一批重点领域标准，强化标准实施，提升科技服务业标准化发\n\n展水平。\n\n  本题为选非题，故正确答案为 C。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","科技","经济"],"nature":"知识题","current":true,"links":[{"id":"k-160f067f85c0f2b5","label":"科技服务机构专业化、市场化、平台化发展","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"引导科技服务机构专业化、市场化、平台化发展。","why":"实施意见将这三个方向用于培育壮大科技服务主体。","origin":"逐题标记"},{"id":"k-c02a6cbca919afb1","label":"科技服务机构持续提升服务质量","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"引导科技服务机构牢固树立质量第一的意识","why":"实施意见以质量第一和加强质量管理推动科技服务质量持续提升。","origin":"逐题标记"},{"id":"k-dd3f3dd7424a753c","label":"科技服务业标准体系建设与标准实施","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"加强标准体系建设，加快研制一批重点领域标准，强化标准实施","why":"实施意见把标准研制和实施作为提升科技服务业标准化水平的措施。","origin":"逐题标记"},{"id":"k-04b16df7eec1756e","label":"科技服务业发展中的市场主导取向","catalog_id":null,"type":"观点与论证","role":"解题依据","field":"answer","quote":"一般说“市场主导”，而非“政府主导”","why":"解析以通常采用的市场主导取向辨析题中对政府角色的表述。","origin":"逐题标记"}]},"政治理论必刷100题#39":{"stem":"改革开放以来，我国积极推进贸易投资自由化，在国际竞争与合作中促进本国经济\n\n融入世界经济大循环。相较于商品和要素流动型开放，制度型开放强调主动对接国际高标准\n\n经贸规则，推动规则、规制、管理、标准的相通相容。以下相关说法错误的是（          ）。","options":["规则开放是制度型开放的基础，为制度型开放提供基本行为准则","规制开放最终指向是各国监管规则的协调和一致，降低合规成本，提升国际经济活动\n\n效率","管理开放主要针对政府管理模式，其核心是放管结合，优化政务服务，提升行政效能","标准开放为管理提供了更具体的衡量尺度，有助于降低合规成本，提升在国际贸易体\n\n系中的适配性"],"answer":"C","analysis":"39.【答案】C\n\n  【解析】\n\n  本题考查理论与政策。\n\n  2025 年 2 月，求是网刊登了重要文章《以制度型开放建设更高水平开放型经济新体制》\n\n（以下简称文章）。\n\n  A 项正确，文章指出，规则意指通行的国际经贸规则，包括世界贸易组织规则和区域贸\n\n易协定规则······规则开放既包括遵守现有国际经贸规则，也包括参与全球治理、共\n\n建国际经贸新规则。规则开放是制度型开放的基础，为制度型开放提供基本行为准则。\n\n  B 项正确，文章指出，规制是指政府针对特定行业和领域实施的规范和控制，涉及政府\n\n对涉外经济活动的约束。规制开放着力于明晰政府边界，减少不必要的政府干预，其最终指\n\n向是各国监管规则的协调和一致，降低合规成本，提升国际经济活动效率。\n\n  C 项错误，文章指出，管理开放主要针对政府管理模式，其核心是简政放权，优化政务\n\n服务，提升行政效能。比如，加强国际贸易“单一窗口”建设、创新海关综合监管模式、实\n\n施“证照分离”等商事制度改革，都是政府优化管理模式，营造市场化、法治化、国际化一\n\n流营商环境的体现，是管理开放的重要内容。故“核心是放管结合”表述有误。\n\n  D 项正确，文章指出，标准是就商品生产而提供的规则、指南，包括环境标准、劳工标\n\n准、数字领域标准等。标准可以规范企业行为，确保企业按照合格流程开展生产经营活动，\n\n为提高产品质量以及服务水平提供了可能······标准开放为管理提供了更具体的衡\n\n量尺度，有助于降低合规成本，提升在国际贸易体系中的适配性。\n\n  本题为选非题，故正确答案为 C。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","经济","公共管理"],"nature":"知识题","current":false,"links":[{"id":"k-deaf678e08e0ae9c","label":"规则开放为制度型开放提供基本行为准则","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"规则开放是制度型开放的基础，为制度型开放提供基本行为准则。","why":"对接并参与建设国际经贸规则是规则开放发挥基础作用的体现。","origin":"逐题标记"},{"id":"k-d56a81095385d822","label":"规制开放指向各国监管规则协调一致","catalog_id":null,"type":"原理与机制","role":"直接考查","field":"answer","quote":"各国监管规则的协调和一致，降低合规成本，提升国际经济活动效率。","why":"监管规则协调有助于降低跨境经营合规成本并提升国际经济活动效率。","origin":"逐题标记"},{"id":"k-d31bfec672cb999c","label":"管理开放以简政放权为核心","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"管理开放主要针对政府管理模式，其核心是简政放权","why":"管理开放通过简政放权优化政务服务并提升行政效能，核心表述是本题辨析点。","origin":"逐题标记"},{"id":"k-e1a3e4ea85d37dc0","label":"标准开放提供管理衡量尺度并提升国际贸易适配性","catalog_id":null,"type":"原理与机制","role":"直接考查","field":"question","quote":"标准开放为管理提供了更具体的衡量尺度","why":"具体衡量尺度有助于降低合规成本并提高在国际贸易体系中的适配性。","origin":"逐题标记"}]},"政治理论必刷100题#40":{"stem":"习近平总书记关于科技自立自强的重要论述，系统阐述了推进我国科技创新的战略\n\n目标、重点任务、重大举措和基本要求。关于加快实现高水平科技自立自强，下列表述正确\n\n的有（          ）。\n\n     ①要以人工智能引领科研范式变革，加速各领域科技创新突破\n\n     ②现代制造业离不开科技赋能，要大力加强技术攻关，走自主创新的发展路子\n\n     ③要扎实推动科技创新和产业创新深度融合，融合的关键是促进科技成果转化应用\n\n     ④实现科技自主创新和人才自主培养良性互动，科技要进一步发挥先导性、基础性支撑\n\n作用","options":["1 项","2 项","3 项","4 项"],"answer":"B","analysis":"40.【答案】B\n\n  【解析】\n\n  本题考查理论与政策。\n\n  ①正确，2025 年 4 月 25 日，习近平总书记在二十届中央政治局第二十次集体学习时讲\n\n话指出，要持续加强基础研究，集中力量攻克高端芯片、基础软件等核心技术，构建自主可\n\n控、协同运行的人工智能基础软硬件系统。以人工智能引领科研范式变革，加速各领域科技\n\n创新突破。\n\n  ②正确，2025 年 5 月 19 日至 20 日，习近平总书记在河南考察时讲话指出，现代制造\n\n业离不开科技赋能，要大力加强技术攻关，走自主创新的发展路子。坚持自立自强，把关键\n\n核心技术牢牢掌握在自己手中，唯有如此，才能不断推动我国制造业高质量发展，为实现中\n\n国式现代化提供更澎湃动能、更坚实支撑。\n\n   ③错误，2025 年 4 月 1 日出版的第 7 期《求是》杂志发表的习近平总书记的文章《朝\n\n着建成科技强国的宏伟目标奋勇前进》指出，扎实推动科技创新和产业创新深度融合，助力\n\n发展新质生产力。融合的基础是增加高质量科技供给，融合的关键是强化企业科技创新主体\n\n地位，融合的途径是促进科技成果转化应用。故“融合的关键是促进科技成果转化应用”表\n\n述有误，应为“融合的关键是强化企业科技创新主体地位”。\n\n   ④错误，2025 年 3 月 6 日，习近平总书记在看望参加全国政协十四届三次会议的民盟、\n\n民进、教育界委员并参加联组会时讲话指出，实现科技自主创新和人才自主培养良性互动，\n\n教育要进一步发挥先导性、基础性支撑作用。故“科技要进一步发挥先导性、基础性支撑作\n\n用”表述有误，应为“教育要进一步发挥先导性、基础性支撑作用”。\n\n   故①②表述正确，共 2 项。\n\n   故正确答案为 B。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","科技"],"nature":"知识题","current":true,"links":[{"id":"k-6502eef7382b8c03","label":"以人工智能引领科研范式变革","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"以人工智能引领科研范式变革，加速各领域科技创新突破","why":"考查人工智能对科研方式和科技创新的引领作用。","origin":"逐题标记"},{"id":"k-f0370a94504e52ff","label":"加快高水平科技自立自强","catalog_id":"a68d785a35e10e78","type":"观点与论证","role":"直接考查","field":"question","quote":"现代制造业离不开科技赋能，要大力加强技术攻关，走自主创新的发展路子","why":"考查现代制造业掌握关键核心技术的自主创新要求。","origin":"逐题标记"},{"id":"k-efd4f4c5d2684f07","label":"科技创新与产业创新深度融合的关键和途径","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"地位，融合的途径是促进科技成果转化应用","why":"融合的关键是强化企业科技创新主体地位，途径是促进科技成果转化应用。","origin":"逐题标记"},{"id":"k-9eee624cb5addd30","label":"教育对科技自主创新和人才自主培养的支撑作用","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"教育要进一步发挥先导性、基础性支撑作用","why":"考查教育在促进科技自主创新和人才自主培养良性互动中的定位。","origin":"逐题标记"}]},"政治理论必刷100题#41":{"stem":"价格治理是宏观经济治理的重要内容。关于完善价格治理机制，下列表述不正确的\n\n是（      ）。","options":["规范市场价格行为，防止经营者以低于成本的价格开展恶性竞争","公办养老、托育、医疗机构基本服务收费，实行全面放开由市场调节","废止妨碍全国统一大市场建设和公平竞争的价格政策，防止政府对价格形成的不当干\n\n预","在公共数据授权运营中，用于公共治理、公益事业的公共数据产品和服务有条件无偿\n\n使用"],"answer":"B","analysis":"41.【答案】B\n\n   【解析】\n\n   本题考查理论与政策。\n\n   2024 年 12 月 5 日，中共中央办公厅、国务院办公厅印发《关于完善价格治理机制的意\n\n见》（以下简称《意见》）。\n\n   A 项正确，《意见》在“五、优化透明可预期的市场价格监管机制”部分指出：“（十\n\n二 ） 规 范 市 场 价 格 行 为 ······ 防 止 经 营 者 以 低 于 成 本 的 价 格 开 展 恶 性 竞\n\n争······”\n\n   B 项错误，\n        《意见》在“三、创新服务重点领域发展和安全的价格引导机制”部分指出：\n\n“（七）完善促进均衡可及的公共服务价格政策。公办养老、托育、医疗机构基本服务收费，\n\n实行政府指导价管理······”故“全面放开由市场调节”表述有误，应为“政府指导\n\n价管理”。\n\n   C 项正确，《意见》在“二、健全促进资源高效配置的市场价格形成机制”部分指出：\n\n“（三）营造竞争有序市场环境。废止妨碍全国统一大市场建设和公平竞争的价格政策，防\n\n止政府对价格形成的不当干预······”\n\n   D 项正确，\n        《意见》在“三、创新服务重点领域发展和安全的价格引导机制”部分指出：\n\n“（八）创新促进数字经济发展的公共数据价格政策······在公共数据授权运营中，\n\n用于公共治理、公益事业的公共数据产品和服务有条件无偿使用；用于产业发展、行业发展\n\n的公共数据产品和服务有条件有偿使用，按照补偿成本、合理盈利的原则确定收费标准并动\n\n态调整。”\n\n  本题为选非题，故正确答案为 B。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","经济"],"nature":"知识题","current":true,"links":[{"id":"k-27aabb6f443eaee2","label":"公办养老、托育、医疗机构基本服务收费实行政府指导价管理","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"公办养老、托育、医疗机构基本服务收费，\n\n实行政府指导价管理","why":"考查这些机构基本服务收费适用的价格管理方式。","origin":"逐题标记"},{"id":"k-818ebfad08e1e3b3","label":"市场价格治理中的低价恶性竞争防范","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"规范市场价格行为，防止经营者以低于成本的价格开展恶性竞争","why":"考查价格监管对低于成本开展恶性竞争的要求。","origin":"逐题标记"},{"id":"k-0a6da28c772630a4","label":"全国统一大市场建设","catalog_id":"4c18d7c76ff0f014","type":"制度与规则","role":"直接考查","field":"question","quote":"废止妨碍全国统一大市场建设和公平竞争的价格政策","why":"考查统一大市场建设对清理妨碍公平竞争的价格政策的要求。","origin":"逐题标记"},{"id":"k-5d69918771d1b71e","label":"公共数据授权运营按用途实行有条件有偿或无偿使用","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"用于公共治理、公益事业的公共数据产品和服务有条件无偿使用","why":"考查公共治理和公益事业用途适用的公共数据产品和服务价格规则。","origin":"逐题标记"}]},"政治理论必刷100题#42":{"stem":"对外开放是中国的基本国策，中国正在推进高水平对外开放，稳步扩大规则、规制、\n\n管理、标准等制度型开放。下列与我国高水平对外开放有关的说法不正确的是（        ）。","options":["要坚持以大开发促进大开放，提高西部地区对内对外开放水平","建设更高水平开放型经济新体制是我们主动作为以开放促改革、促发展的战略举措","要对标国际先进水平，把自由贸易试验区等高水平对外开放的有效举措和成熟经验及\n\n时上升为法律","实行高水平对外开放，必须具备强大的国内经济循环体系和稳固的基本盘"],"answer":"A","analysis":"42.【答案】A\n\n  【解析】\n\n  本题考查理论与政策。\n\n  A 项错误，2024 年 4 月 23 日，习近平总书记在新时代推动西部大开发座谈会上的讲话\n\n中指出：“要坚持以大开放促进大开发，提高西部地区对内对外开放水平。大力推进西部陆\n\n海新通道建设，推动沿线地区开发开放，深度融入共建‘一带一路’。”故“以大开发促进\n\n大开放”表述错误，应为“以大开放促进大开发”。\n\n  B 项正确，2023 年 7 月 11 日，习近平总书记在中央全面深化改革委员会第二次会议上\n\n的讲话中指出：“建设更高水平开放型经济新体制是我们主动作为以开放促改革、促发展的\n\n战略举措，要围绕服务构建新发展格局，以制度型开放为重点，聚焦投资、贸易、金融、创\n\n新等对外交流合作的重点领域深化体制机制改革，完善配套政策措施，积极主动把我国对外\n\n开放提高到新水平。”\n\n  C 项正确，2023 年 11 月 27 日，习近平总书记在二十届中央政治局第十次集体学习时的\n\n讲话中指出：“要对标国际先进水平，把自由贸易试验区等高水平对外开放的有效举措和成\n\n熟经验及时上升为法律，打造开放层次更高、营商环境更优、辐射作用更强的对外开放新高\n\n地。”\n\n  D 项正确，2021 年 1 月 11 日，习近平总书记在省部级主要领导干部学习贯彻党的十九\n\n届五中全会精神专题研讨班上的讲话中指出：“构建新发展格局，实行高水平对外开放，必\n\n须具备强大的国内经济循环体系和稳固的基本盘，并以此形成对全球要素资源的强大吸引力、\n\n在激烈国际竞争中的强大竞争力、在全球资源配置中的强大推动力。”\n\n  本题为选非题，故正确答案为 A。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","经济"],"nature":"知识题","current":true,"links":[{"id":"k-ff3a3a6fc272c1b3","label":"西部地区以大开放促进大开发","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"要坚持以大开放促进大开发，提高西部地区对内对外开放水平","why":"考查西部地区扩大开放与推进开发之间的政策方向。","origin":"逐题标记"},{"id":"k-76f3ab01b88b79f9","label":"制度型开放","catalog_id":"31699340f47012e7","type":"制度与规则","role":"直接考查","field":"answer","quote":"以制度型开放为重点","why":"制度型开放是建设更高水平开放型经济新体制、以开放促改革促发展的重点。","origin":"逐题标记"},{"id":"k-462149626c4782a6","label":"将自贸试验区等开放举措和成熟经验及时上升为法律","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"把自由贸易试验区等高水平对外开放的有效举措和成\n\n熟经验及时上升为法律","why":"考查将经过实践检验的高水平开放成果转化为法律制度的要求。","origin":"逐题标记"},{"id":"k-de1dc123a6c275d0","label":"高水平对外开放以强大的国内经济循环和稳固的基本盘为条件","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"必须具备强大的国内经济循环体系和稳固的基本盘","why":"考查实行高水平对外开放所依托的国内经济条件。","origin":"逐题标记"}]},"政治理论必刷100题#43":{"stem":"坚持和完善基本经济制度必须坚持“两个毫不动摇”，公有制经济和非公有制经济\n\n都是社会主义市场经济的重要组成部分，都是我国经济社会发展的重要基础。以下相关说法\n\n不正确的是（       ）。","options":["深化政治体制改革是进一步全面深化改革的重点，主要任务是完善有利于推动高质量\n\n发展的体制机制","着眼推动非公有制经济发展，提出制定民营经济促进法，有利于更好激发全社会内生\n\n动力和创新活力","党和国家保证各种所有制经济依法平等使用生产要素、公平参与市场竞争、同等受到\n\n法律保护","党和国家对民营经济发展的基本方针政策，已经纳入中国特色社会主义制度体系，将\n\n一以贯之坚持和落实，不能变，也不会变"],"answer":"A","analysis":"43.【答案】A\n\n  【解析】\n\n  本题考查理论与政策。\n\n  A 项错误，2024 年 8 月 15 日，习近平总书记在《关于〈中共中央关于进一步全面深化\n\n改革、推进中国式现代化的决定〉的说明》中指出，深化经济体制改革仍是进一步全面深化\n\n改革的重点，主要任务是完善有利于推动高质量发展的体制机制，塑造发展新动能新优势，\n\n坚持和落实“两个毫不动摇”，构建全国统一大市场，完善市场经济基础制度。故“深化政\n\n治体制改革”有误，应是“深化经济体制改革”。\n\n  B 项正确，2024 年 8 月 15 日，习近平总书记在《关于〈中共中央关于进一步全面深化\n\n改革、推进中国式现代化的决定〉的说明》中指出，着眼增强国有企业核心功能、提升核心\n\n竞争力······着眼推动非公有制经济发展，提出制定民营经济促进法，加强产权执法\n\n司法保护······提出加强公平竞争审查刚性约束······这些举措将更好激发\n\n全社会内生动力和创新活力。\n\n  C 项正确，2025 年 2 月 17 日，习近平总书记在民营企业座谈会上的讲话中指出，党和\n\n国家保证各种所有制经济依法平等使用生产要素、公平参与市场竞争、同等受到法律保护，\n\n促进各种所有制经济优势互补、共同发展，促进非公有制经济健康发展和非公有制经济人士\n\n健康成长。\n\n  D 项正确，2025 年 2 月 17 日，习近平总书记在民营企业座谈会上的讲话中指出，党和\n\n国家对民营经济发展的基本方针政策，已经纳入中国特色社会主义制度体系，将一以贯之坚\n\n持和落实，不能变，也不会变。新时代新征程民营经济发展前景广阔、大有可为，广大民营\n\n企业和民营企业家大显身手正当其时。\n\n  本题为选非题，故正确答案为 A。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","经济"],"nature":"知识题","current":true,"links":[{"id":"k-d77fd5ea4356cf82","label":"进一步全面深化改革以经济体制改革为重点","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"改革、推进中国式现代化的决定〉的说明》中指出，深化经济体制改革仍是进一步全面深化","why":"考查进一步全面深化改革的重点及其完善高质量发展体制机制的主要任务。","origin":"逐题标记"},{"id":"k-3ba756a60062ad2d","label":"提出制定民营经济促进法以激发社会内生动力和创新活力","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"着眼推动非公有制经济发展，提出制定民营经济促进法","why":"考查推动非公有制经济发展所采取的具体立法部署及其目的。","origin":"逐题标记"},{"id":"k-afebf20e30b5ec05","label":"“两个毫不动摇”","catalog_id":"39174200a2f5f745","type":"制度与规则","role":"直接考查","field":"answer","quote":"依法平等使用生产要素、公平参与市场竞争、同等受到法律保护","why":"考查落实“两个毫不动摇”对各类所有制经济提供的平等保障。","origin":"逐题标记"},{"id":"k-8ad204b416d318ef","label":"民营经济","catalog_id":"213cbd4fab59c3ce","type":"制度与规则","role":"直接考查","field":"question","quote":"党和国家对民营经济发展的基本方针政策，已经纳入中国特色社会主义制度体系","why":"考查民营经济基本方针政策的制度定位和持续性。","origin":"逐题标记"}]},"政治理论必刷100题#44":{"stem":"推动中部地区崛起是以习近平同志为核心的党中央作出的重大战略决策。下列关于\n\n中部地区崛起的表述，正确的有（      ）。\n\n     ①要加强现代化交通基础设施体系建设，强化中部地区的大通道格局\n\n     ②要围绕对话交流、重大事项协商、规划衔接，建立健全中部地区省际合作机制\n\n     ③要统筹推进深层次改革和高水平开放，持续打造更具竞争力的内陆开放高地\n\n  ④到 2035 年，中部地区现代化经济体系全面建成","options":["1 项","2 项","3 项","4 项"],"answer":"C","analysis":"44.【答案】C\n\n  【解析】\n\n  本题考查理论与政策。\n\n  ①正确，2024 年 3 月 20 日，习近平总书记在新时代推动中部地区崛起座谈会上指出：\n\n“要加强与其他重大发展战略的衔接，更好融入和支撑新发展格局······加强现代化\n\n交通基础设施体系建设，强化中部地区的大通道格局。”\n\n  ②正确，2021 年 4 月 23 日发布的《中共中央   国务院关于新时代推动中部地区高质量\n\n发展的意见》在“三、坚持协调发展，增强城乡区域发展协同性”部分指出：“（十一）推\n\n动省际协作和交界地区协同发展。围绕对话交流、重大事项协商、规划衔接，建立健全中部\n\n地区省际合作机制。”\n\n  ③正确，2024 年 3 月 20 日，习近平总书记在新时代推动中部地区崛起座谈会上强调：\n\n“要统筹推进深层次改革和高水平开放，持续打造更具竞争力的内陆开放高地。”\n\n  ④错误，2021 年 4 月 23 日发布的《中共中央   国务院关于新时代推动中部地区高质量\n\n发展的意见》在“一、总体要求”部分指出：“（二）主要目标。到 2035 年，中部地区现\n\n代化经济体系基本建成，产业整体迈向中高端······”故“全面建成”表述错误，应\n\n为“基本建成”。\n\n   故正确的有①②③，共 3 项。\n\n   故正确答案为 C。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","经济"],"nature":"知识题","current":true,"links":[{"id":"k-23b9b52adc801c03","label":"中部地区以现代化交通基础设施强化大通道格局","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"要加强现代化交通基础设施体系建设，强化中部地区的大通道格局","why":"考查新时代推动中部地区崛起的交通建设部署。","origin":"逐题标记"},{"id":"k-785becfc5369c929","label":"中部地区省际合作机制的协作事项","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"围绕对话交流、重大事项协商、规划衔接，建立健全中部地区省际合作机制","why":"考查中部地区建立省际合作机制所涵盖的协作事项。","origin":"逐题标记"},{"id":"k-80ed55f1de5c9bb3","label":"中部地区统筹深层次改革和高水平开放以打造内陆开放高地","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"要统筹推进深层次改革和高水平开放，持续打造更具竞争力的内陆开放高地","why":"考查中部地区打造内陆开放高地的改革开放要求。","origin":"逐题标记"},{"id":"k-f727931b29028092","label":"到2035年中部地区现代化经济体系基本建成","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"到 2035 年，中部地区现\n\n代化经济体系基本建成","why":"考查中部地区现代化经济体系在2035年应达到的建设阶段。","origin":"逐题标记"}]},"政治理论必刷100题#45":{"stem":"习近平总书记强调，要加快补上内需特别是消费短板，使内需成为拉动经济增长的\n\n主动力和稳定锚，这一重要论述凸显了提振消费在全局工作中的重要性。下列关于消费能力\n\n保障支持行动的表述正确的有（        ）。\n\n  ①拓宽财产性收入渠道\n\n  ②健全最低工资标准调整机制，科学合理提高最低工资标准\n\n  ③健全基本养老保险待遇合理调整机制\n\n  ④加大消费品以旧换新支持力度\n\n  ⑤研究建立育儿补贴制度","options":["2 项","3 项","4 项","5 项"],"answer":"A","analysis":"45.【答案】A\n\n   【解析】\n\n   本题考查理论与政策。\n\n   2025 年 3 月，中共中央办公厅、国务院办公厅印发《提振消费专项行动方案》\n                                         （以下简\n\n称《方案》）\n     。\n\n   ①错误，《方案》在“一、城乡居民增收促进行动”中提到：“（二）拓宽财产性收入\n\n渠道。多措并举稳住股市，加强战略性力量储备和稳市机制建设······”\n\n   ②错误，《方案》在“一、城乡居民增收促进行动”中提到：“（一）促进工资性收入\n\n合 理 增 长 ······ 健 全 最 低 工 资 标 准 调 整 机 制 ， 科 学 合 理 提 高 最 低 工 资 标\n\n准······”\n\n   ③正确，《方案》在“二、消费能力保障支持行动”中提到：“（七）提高医疗养老保\n\n障能力。健全基本养老保险待遇合理调整机制，2025 年提高城乡居民基础养老金和城乡居\n\n民基本医疗保险财政补助标准······”\n\n   ④错误，《方案》在“四、大宗消费更新升级行动”中提到：“（十五）加大消费品以\n\n旧换新支持力度。用好超长期特别国债资金······”\n\n   ⑤正确，《方案》在“二、消费能力保障支持行动”中提到：“（五）加大生育养育保\n\n障力度。研究建立育儿补贴制度······”\n\n   故③⑤表述正确，共 2 项。\n\n   故正确答案为 A。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","经济"],"nature":"知识题","current":true,"links":[{"id":"k-77afdc0ca18e348a","label":"《提振消费专项行动方案》的消费能力保障支持行动","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"健全基本养老保险待遇合理调整机制","why":"健全基本养老保险待遇合理调整机制是该行动提高医疗养老保障能力的措施。","origin":"逐题标记"},{"id":"k-80e78a1d0d350c3b","label":"育儿补贴制度","catalog_id":"dacac9bacd101e70","type":"制度与规则","role":"直接考查","field":"answer","quote":"障力度。研究建立育儿补贴制度","why":"研究建立育儿补贴制度属于该行动的生育养育保障措施。","origin":"逐题标记"},{"id":"k-466671fd53beeb11","label":"《提振消费专项行动方案》的城乡居民增收促进行动","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"“一、城乡居民增收促进行动”中提到：“（二）拓宽财产性收入\n\n渠道。","why":"拓宽财产性收入渠道与健全最低工资标准调整机制均归入城乡居民增收促进行动。","origin":"逐题标记"},{"id":"k-f0b4ead371af1ddf","label":"实施消费品以旧换新","catalog_id":"249b6ddd9b684c24","type":"制度与规则","role":"直接考查","field":"answer","quote":"“四、大宗消费更新升级行动”中提到：“（十五）加大消费品以\n\n旧换新支持力度。","why":"考查加大消费品以旧换新支持力度在方案中所属的行动。","origin":"逐题标记"}]},"政治理论必刷100题#46":{"stem":"中国特色现代企业制度是中国特色社会主义制度的重要组成部分。下列关于完善中\n\n国特色现代企业制度，表述有误的是（          ）。","options":["以产权清晰、权责明确、政企分开、管理科学为基础，以完善公司治理为重点","经过 5 年左右，推动所有国有企业普遍建立符合国情的中国特色现代企业制度","健全以职工代表大会为基本形式的企业民主管理制度，坚持和完善职工董事制度","坚持以制度建设促发展，破解体制机制障碍，推动公司治理结构和组织形态创新"],"answer":"B","analysis":"46.【答案】B\n\n   【解析】\n\n   本题考查理论与政策。\n\n   2025 年 5 月，中共中央办公厅、国务院办公厅正式发布《中共中央办公厅 国务院办公\n\n厅关于完善中国特色现代企业制度的意见》，以下简称《意见》\n                           。\n\n   A 项正确，《意见》中“一、总体要求”部分指出：“以坚持和加强党的领导为根本，\n\n以产权清晰、权责明确、政企分开、管理科学为基础，以完善公司治理为重点，以改革创新\n\n为动力，弘扬企业家精神，加快建设更多世界一流企业，为以中国式现代化全面推进强国建\n\n设、民族复兴伟业提供有力支撑。”\n\n  B 项错误，《意见》中“一、总体要求”部分指出：“经过 5 年左右，推动具备条件的\n\n企业普遍建立适合国情、符合实际、满足发展需要的中国特色现代企业制度，企业党的建设\n\n全面加强，治理结构更加健全，市场化运营机制更加完善，科学管理水平进一步提高，推动\n\n自主创新、支撑产业升级、履行社会责任等作用充分发挥。”故“推动所有国有企业普遍建\n\n立符合国情的中国特色现代企业制度”表述有误，应为“推动具备条件的企业普遍建立适合\n\n国情、符合实际、满足发展需要的中国特色现代企业制度”。\n\n  C 项正确，《意见》中“四、提升企业科学管理水平”部分指出：“健全以职工代表大\n\n会为基本形式的企业民主管理制度，坚持和完善职工董事制度。注重发挥工会等群团组织作\n\n用，积极推行工资集体协商制度，建立符合企业实际、具备可操作性的集体协商机制。”\n\n  D 项正确，《意见》中“一、总体要求”部分指出：“坚持以制度建设促发展，破解体\n\n制机制障碍，推动公司治理结构和组织形态创新，完善企业制度，支持和引导各类企业提高\n\n资源要素利用效率和经营管理水平。”\n\n  本题为选非题，故正确答案为 B。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","经济"],"nature":"知识题","current":true,"links":[{"id":"k-4522b855176bbb2d","label":"中国特色现代企业制度","catalog_id":"ac232bb3da2166c7","type":"制度与规则","role":"直接考查","field":"answer","quote":"经过 5 年左右，推动具备条件的\n\n企业普遍建立适合国情、符合实际、满足发展需要的中国特色现代企业制度","why":"考查五年左右建设目标的适用范围，判定依据是企业是否具备条件。","origin":"逐题标记"},{"id":"k-fe35a3967360cf44","label":"完善中国特色现代企业制度的治理基础和改革重点","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"以产权清晰、权责明确、政企分开、管理科学为基础，以完善公司治理为重点","why":"考查现代企业制度的基本要求及推动治理结构和组织形态创新的着力点。","origin":"逐题标记"},{"id":"k-9fac6a162326dd37","label":"企业民主管理的职工代表大会和职工董事制度","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"健全以职工代表大会为基本形式的企业民主管理制度，坚持和完善职工董事制度","why":"考查完善现代企业制度中的企业民主管理形式和治理安排。","origin":"逐题标记"}]},"政治理论必刷100题#47":{"stem":"习近平总书记强调，科学制定和接续实施五年规划，是我们党治国理政一条重要经\n\n验，也是中国特色社会主义一个重要政治优势。关于科学谋划好“十五五”时期经济社会发\n\n展，下列说法错误的是（      ）。","options":["必须准确把握“十五五”时期的阶段性要求，紧紧围绕全面实现社会主义现代化目标","前瞻性把握国际形势发展变化对我国的影响，因势利导对经济布局进行调整优化","把造福人民作为根本价值取向，坚持在发展中保障和改善民生，稳步推动共同富裕","各地区要深入调查研究，在确定发展思路和战略举措时注重体现自身特色、发挥比较\n\n优势"],"answer":"A","analysis":"47.【答案】A\n\n  【解析】\n\n  本题考查理论与政策。\n\n  2025 年 4 月 30 日，习近平总书记主持召开部分省区市“十五五”时期经济社会发展座\n\n谈会并发表重要讲话（以下简称讲话）。\n\n  A 项错误，讲话指出，谋划“十五五”时期经济社会发展，必须准确把握“十五五”时\n\n期的阶段性要求，着眼强国建设、民族复兴伟业，紧紧围绕基本实现社会主义现代化目标，\n\n一个领域一个领域合理确定目标任务、提出思路举措。故“全面实现”表述有误，应为“基\n\n本实现”。\n\n  B 项正确，讲话指出，谋划“十五五”时期经济社会发展，要前瞻性把握国际形势发展\n\n变化对我国的影响，因势利导对经济布局进行调整优化。\n\n  C 项正确，讲话指出，中国式现代化是全体人民共同富裕的社会主义现代化。谋划“十\n\n五五”时期经济社会发展，要不忘初心，把造福人民作为根本价值取向，坚持在发展中保障\n\n和改善民生，稳步推动共同富裕。\n\n  D 项正确，讲话指出，各地区谋划“十五五”时期经济社会发展，要在全国大局中精准\n\n定位，加强规划衔接。要深入调查研究，坚持目标导向和问题导向相统一，在确定发展思路\n\n和战略举措时注重体现自身特色、发挥比较优势。\n\n  本题为选非题，故正确答案为 A。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","经济"],"nature":"知识题","current":true,"links":[{"id":"k-89eb4fb079f70fa6","label":"基本实现社会主义现代化","catalog_id":"053a24013e87f6af","type":"制度与规则","role":"直接考查","field":"answer","quote":"紧紧围绕基本实现社会主义现代化目标","why":"考查谋划“十五五”时期经济社会发展所围绕的现代化阶段目标。","origin":"逐题标记"},{"id":"k-b50e99a74832ba6d","label":"“十五五”经济布局随国际形势变化调整优化","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"前瞻性把握国际形势发展变化对我国的影响，因势利导对经济布局进行调整优化","why":"考查对外部形势的研判如何用于经济布局调整。","origin":"逐题标记"},{"id":"k-aa052a4589f73e60","label":"全体人民共同富裕","catalog_id":"c1c181c77df0cdd7","type":"观点与论证","role":"直接考查","field":"question","quote":"把造福人民作为根本价值取向，坚持在发展中保障和改善民生，稳步推动共同富裕","why":"考查“十五五”时期发展规划的价值取向及共同富裕要求。","origin":"逐题标记"},{"id":"k-550df2ebbc9b86bc","label":"“十五五”地区规划衔接全国大局并发挥比较优势","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"在确定发展思路\n\n和战略举措时注重体现自身特色、发挥比较优势","why":"考查各地区在全国大局中找准定位并结合自身条件制定举措的要求。","origin":"逐题标记"}]},"政治理论必刷100题#48":{"stem":"数字贸易是数字经济的重要组成部分，已成为国际贸易发展的新趋势和经济的新增\n\n长点。关于数字贸易，下列表述正确的有（         ）。\n\n     ①坚持稳中求进工作总基调，促进实体经济和数字经济深度融合，促进数字贸易改革创\n\n新发展\n\n     ②按照创新为基、安全为要，扩大开放、合作共赢，深化改革、系统治理，试点先行、\n\n重点突破的原则，促进数字贸易改革创新发展\n\n     ③培育壮大数字贸易经营主体，积极培育外向度高、具有独特竞争优势的中小型数字贸\n\n易企业\n\n     ④加强多渠道支持保障，充分发挥服务贸易创新发展引导基金作用，带动社会资本投资\n\n数字贸易领域","options":["1 项","2 项","3 项","4 项"],"answer":"C","analysis":"48.【答案】C\n\n  【解析】\n\n  本题考查理论与政策。\n\n  2024 年 11 月 28 日，\n                  《中共中央办公厅   国务院办公厅关于数字贸易改革创新发展的意\n\n见》（以下简称《意见》）对外发布。\n\n  ①正确，《意见》“一、总体要求”部分指出：“······完整准确全面贯彻新发\n\n展理念，坚持稳中求进工作总基调，服务构建新发展格局，着力推动高质量发展，统筹国内\n\n国际两个大局，统筹发展和安全，促进实体经济和数字经济深度融合，促进数字贸易改革创\n\n新发展······”\n\n  ②错误，\n     《意见》“一、总体要求”部分指出：“按照创新为要、安全为基，扩大开放、\n\n合作共赢，深化改革、系统治理，试点先行、重点突破的原则，促进数字贸易改革创新发展。\n                                        ”\n\n故“创新为基、安全为要”说法错误。\n\n  ③正确，《意见》“二、支持数字贸易细分领域和经营主体发展”部分指出：“（五）\n\n培育壮大数字贸易经营主体。培育一批具有较强创新能力和影响力的数字贸易领军企业。积\n\n极培育外向度高、具有独特竞争优势的中小型数字贸易企业。”\n\n  ④正确，《意见》“五、强化组织保障”部分指出：“（十六）加强多渠道支持保障。\n\n加强数字技术研发支持，促进成果转化及与其他行业的融合创新发展。充分发挥服务贸易创\n\n新发展引导基金作用，带动社会资本投资数字贸易领域。”\n\n  综上，①③④表述正确，共 3 项。\n\n  故正确答案为 C。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","经济"],"nature":"知识题","current":true,"links":[{"id":"k-f21d7fa71f536ad2","label":"稳中求进工作总基调","catalog_id":"81ecb322a280cd46","type":"制度与规则","role":"直接考查","field":"answer","quote":"坚持稳中求进工作总基调","why":"该意见把稳中求进和促进实体经济与数字经济深度融合作为数字贸易改革创新发展的总体要求。","origin":"逐题标记"},{"id":"k-c942f879f87b0c86","label":"数字贸易改革创新坚持创新为要、安全为基","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"按照创新为要、安全为基","why":"创新对应“为要”，安全对应“为基”，两者的定位决定原则表述是否准确。","origin":"逐题标记"},{"id":"k-48c47b7ed5ee0f0d","label":"数字贸易经营主体培育覆盖高外向度、有独特竞争优势的中小企业","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"极培育外向度高、具有独特竞争优势的中小型数字贸易企业","why":"意见明确把具备这两项特征的中小型数字贸易企业纳入培育范围。","origin":"逐题标记"},{"id":"k-dfd7a07483ebdd85","label":"服务贸易创新发展引导基金带动社会资本投资数字贸易","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"新发展引导基金作用，带动社会资本投资数字贸易领域","why":"该基金通过引导社会资本进入数字贸易领域提供多渠道支持。","origin":"逐题标记"}]},"政治理论必刷100题#49":{"stem":"健全资源环境要素市场化配置体系，推进碳排放权、用水权、排污权等市场化交易，\n\n是提升资源环境要素利用效率的关键举措。下列相关表述正确的有（          ）。\n\n     ①完善全国温室气体强制减排交易市场，逐步扩大支持领域\n\n     ②坚持节约优先方针，完善贯穿能源生产和消费全链条的节能管理制度\n\n     ③以省级行政区域为单位因地制宜建立健全排污权有偿使用和交易制度\n\n     ④坚持政府主导原则，分类健全资源环境要素价格形成机制","options":["1 项","2 项","3 项","4 项"],"answer":"B","analysis":"49.【答案】B\n\n  【解析】\n\n  本题考查理论与政策。\n\n  2025 年 5 月 14 日，中共中央办公厅    国务院办公厅印发《关于健全资源环境要素市场\n\n化配置体系的意见》（以下简称《意见》\n                 ）。\n\n  ①错误，《意见》在“三、优化资源环境要素交易范围”部分指出：“（三）完善碳市\n\n场覆盖范围。结合碳达峰碳中和工作需要、行业降碳潜力和碳排放核算基础等，稳步扩大全\n\n国碳排放权交易市场行业覆盖范围，扩展交易主体，丰富交易品种、交易方式。完善全国温\n\n室气体自愿减排交易市场，逐步扩大支持领域。”故“完善全国温室气体强制减排交易市场”\n\n表述有误，应为“完善全国温室气体自愿减排交易市场”。\n\n  ②正确，《意见》在“三、优化资源环境要素交易范围”部分指出：“（四）健全节能\n\n市场化机制。坚持节约优先方针，完善贯穿能源生产和消费全链条的节能管理制度，发展节\n\n能咨询、诊断、设计、融资、改造、托管等综合服务模式，不断壮大节能服务产业。”\n\n  ③正确，《意见》在“三、优化资源环境要素交易范围”部分指出：“（六）持续深化\n\n排污权交易。以省级行政区域为单位因地制宜建立健全排污权有偿使用和交易制度，扩展交\n\n易主体，丰富交易品种、交易方式。”\n\n  ④错误，《意见》在“四、健全资源环境要素交易制度”部分指出：“（十）健全价格\n\n形成机制。坚持市场化原则，分类健全资源环境要素价格形成机制，充分反映市场供求关系、\n\n资源稀缺程度、环境损害成本、生态产品价值，发挥价格杠杆作用，促进资源环境要素高效\n\n合理配置。”故“坚持政府主导原则”表述有误，应为“坚持市场化原则”。\n\n  综上，②③表述正确，共 2 项。\n\n  故正确答案为 B。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","生态环境","经济"],"nature":"知识题","current":true,"links":[{"id":"k-7f602a4ba445680b","label":"完善全国温室气体自愿减排交易市场并逐步扩大支持领域","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"室气体自愿减排交易市场，逐步扩大支持领域","why":"该政策要求逐步扩大支持领域的市场是全国温室气体自愿减排交易市场。","origin":"逐题标记"},{"id":"k-ddbebe8c29187bbd","label":"节约优先与能源生产消费全链条节能管理","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"坚持节约优先方针，完善贯穿能源生产和消费全链条的节能管理制度","why":"节约优先是方针，节能管理制度覆盖生产和消费全链条。","origin":"逐题标记"},{"id":"k-e5d5200e491540b1","label":"以省级行政区域为单位因地制宜建立排污权有偿使用和交易制度","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"以省级行政区域为单位因地制宜建立健全排污权有偿使用和交易制度","why":"规定明确了制度建设的行政区域单位和因地制宜的要求。","origin":"逐题标记"},{"id":"k-d30f371870af4e9c","label":"资源环境要素价格形成坚持市场化原则并分类健全机制","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"坚持市场化原则，分类健全资源环境要素价格形成机制","why":"市场化是分类健全资源环境要素价格形成机制的原则。","origin":"逐题标记"}]},"政治理论必刷100题#50":{"stem":"习近平总书记强调，2025 年是“十四五”规划收官之年，要在加紧落实规划目标任\n\n务的同时，适应形势变化，把握战略重点，科学谋划好“十五五”时期经济社会发展。下列\n\n与之相关的说法不正确的是（        ）。","options":["要更加注重统筹发展和安全，以高效能治理促进高质量发展和高水平安全良性互动","谋划“十五五”时期经济社会发展，要把造福人民作为根本价值取向","“十五五”时期，必须把推动高质量发展摆在更加突出的战略位置","坚持全面推进传统产业转型升级、积极发展新兴产业、超前布局未来产业并举"],"answer":"C","analysis":"50.【答案】C\n\n  【解析】\n\n  本题考查理论与政策。\n\n  2025 年 4 月 30 日上午，习近平总书记在上海主持召开部分省区市“十五五”时期经济\n\n社会发展座谈会并发表重要讲话。\n\n  A 项正确，习近平总书记指出，谋划“十五五”时期经济社会发展，要前瞻性把握国际\n\n形势发展变化对我国的影响，因势利导对经济布局进行调整优化······要更加注重统\n\n筹发展和安全，通盘考虑内外部风险挑战，健全国家安全体系，增强维护安全能力，以高效\n\n能治理促进高质量发展和高水平安全良性互动，以新安全格局保障新发展格局。\n\n  B 项正确，习近平总书记指出，中国式现代化是全体人民共同富裕的社会主义现代化。\n\n谋划“十五五”时期经济社会发展，要不忘初心，把造福人民作为根本价值取向，坚持在发\n\n展中保障和改善民生，稳步推动共同富裕。\n\n  C 项错误，D 项正确，习近平总书记强调，“十五五”时期，必须把因地制宜发展新质\n\n生产力摆在更加突出的战略位置，以科技创新为引领、以实体经济为根基，坚持全面推进传\n\n统产业转型升级、积极发展新兴产业、超前布局未来产业并举，加快建设现代化产业体系。\n\n  本题为选非题，故正确答案为 C。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","经济"],"nature":"知识题","current":true,"links":[{"id":"k-cd27115c75d73688","label":"统筹发展和安全","catalog_id":"9317b72d8b159e70","type":"观点与论证","role":"直接考查","field":"question","quote":"以高效能治理促进高质量发展和高水平安全良性互动","why":"讲话要求谋划“十五五”时更加注重统筹发展和安全，并以高效能治理促进两者良性互动。","origin":"逐题标记"},{"id":"k-3fa2d4cacc6129bc","label":"谋划“十五五”经济社会发展以造福人民为根本价值取向","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"把造福人民作为根本价值取向","why":"讲话把造福人民确立为规划谋划的根本价值取向，要求在发展中保障和改善民生。","origin":"逐题标记"},{"id":"k-07ef47dc10f156ad","label":"新质生产力","catalog_id":"cd67a12c3d0c8d5b","type":"制度与规则","role":"直接考查","field":"answer","quote":"生产力摆在更加突出的战略位置","why":"讲话明确把因地制宜发展新质生产力摆在“十五五”时期更加突出的战略位置。","origin":"逐题标记"},{"id":"k-9b15547988c8ddb9","label":"现代化产业体系","catalog_id":"af8bc6ff1a9b111f","type":"制度与规则","role":"直接考查","field":"answer","quote":"统产业转型升级、积极发展新兴产业、超前布局未来产业并举，加快建设现代化产业体系","why":"建设现代化产业体系要求传统产业转型升级、新兴产业发展和未来产业超前布局并举。","origin":"逐题标记"}]},"政治理论必刷100题#51":{"stem":"党的十八届三中全会开启了新时代全面深化改革、系统整体设计推进改革新征程，\n\n开创了我国改革开放全新局面，具有划时代意义。关于新时代改革的方法论，下列表述错误\n\n的是（         ）。","options":["改革是利益格局调整的过程，应力争同时满足所有人的利益诉求","改革过程中，要坚持以人为本，以实绩实效和人民群众满意度检验改革","善于运用法治思维和法治方式推进改革，维护法治权威，做到重大改革于法有据","改革越深入，对开放的水平要求就越高；开放水平越高，对改革的促进作用就越大"],"answer":"A","analysis":"51.【答案】A\n\n  【解析】\n\n  本题考查理论与政策。\n\n  2025 年第 2 期《求是》杂志发表了习近平总书记的重要文章《进一步全面深化改革中\n\n的几个重大理论和实践问题》（以下简称文章）。\n\n  A 项错误，文章指出：“要看到，改革是利益格局调整的过程，不可能同时满足所有人\n\n的利益诉求。”故该项中“应力争同时满足”表述有误，应为“不可能同时满足”。\n\n  B 项正确，文章指出：“改革过程中，要坚持以人为本，以实绩实效和人民群众满意度\n\n检验改革，真正让人民群众在改革中不断增强获得感、幸福感、安全感。”\n\n  C 项正确，文章指出：“善于运用法治思维和法治方式推进改革，维护法治权威，做到\n\n重大改革于法有据。坚持法律面前人人平等，平等保护公民、法人和其他组织合法权益，不\n\n能搞选择性执法，更不能搞法外开恩。”\n\n  D 项正确，文章指出：“进一步全面深化改革和高水平对外开放是相辅相成、相互促进\n\n的。改革越深入，对开放的水平要求就越高；开放水平越高，对改革的促进作用就越大。”\n\n  本题为选非题，故正确答案为 A。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","法律"],"nature":"知识题","current":false,"links":[{"id":"k-4c3f651ed30d4662","label":"改革调整利益格局，难以同时满足所有人的利益诉求","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"改革是利益格局调整的过程，不可能同时满足所有人","why":"利益格局调整涉及不同诉求，文章明确指出改革不可能同时满足所有人的利益诉求。","origin":"逐题标记"},{"id":"k-f4204304ba934d04","label":"以实绩实效和人民群众满意度检验改革","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"坚持以人为本，以实绩实效和人民群众满意度检验改革","why":"坚持以人为本要求把实际成效和群众满意度都纳入改革成效检验。","origin":"逐题标记"},{"id":"k-706604ca8d59a95b","label":"运用法治思维和法治方式推进改革，确保重大改革于法有据","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"善于运用法治思维和法治方式推进改革，维护法治权威，做到重大改革于法有据","why":"法治对改革方式和重大改革的法律依据提出明确要求。","origin":"逐题标记"},{"id":"k-fb82cf7f9abfa2a5","label":"进一步全面深化改革与高水平对外开放相互促进","catalog_id":null,"type":"原理与机制","role":"直接考查","field":"answer","quote":"改革越深入，对开放的水平要求就越高；开放水平越高，对改革的促进作用就越大","why":"深化改革提高对开放水平的要求，提高开放水平又能促进改革。","origin":"逐题标记"}]},"政治理论必刷100题#52":{"stem":"习近平总书记强调，推进边疆治理体系和治理能力现代化，是中国式现代化的应有\n\n之义。下列关于习近平总书记的边疆治理理念，表述正确的有几项？\n\n    ①要坚持把铸牢中华民族共同体意识作为边疆民族地区工作的主线\n\n    ②要打造一支政治立场坚定、理论修养和综合素质过硬的边疆治理研究队伍\n\n    ③要坚持把全面建成小康社会、少数民族一个都不能少作为边疆治理的底线要求\n\n    ④要把边疆地区发展纳入中国式现代化战略全局，纳入区域协调发展战略、区域重大战\n\n略","options":["1","2","3","4"],"answer":"B","analysis":"52.【答案】B\n\n  【解析】\n\n  本题考查政治常识。\n\n  ①错误，2024 年 12 月 9 日，中共中央政治局就我国历史上的边疆治理进行第十八次集\n\n体学习。习近平总书记在主持学习时强调，要坚持把推进中华民族共同体建设作为边疆民族\n\n地区工作的主线。引导边疆地区各族群众不断增强对伟大祖国、中华民族、中华文化、中国\n\n共产党、中国特色社会主义的认同，构筑中华民族共有精神家园。故“把铸牢中华民族共同\n\n体意识作为边疆民族地区工作的主线”应是“把推进中华民族共同体建设作为边疆民族地\n\n区工作的主线”。\n\n  ②正确，2024 年 12 月 9 日，中共中央政治局就我国历史上的边疆治理进行第十八次集\n\n体学习。习近平总书记在主持学习时指出，要加强边疆史和边疆治理相关的多学科研究，加\n\n快建构中国自主的边疆学知识体系。深化边疆治理重大理论和现实问题研究，推出更多具有\n\n影响力、说服力的研究成果。运用好边疆研究成果，讲好新时代中国边疆治理故事。打造一\n\n支政治立场坚定、理论修养和综合素质过硬的边疆治理研究队伍。\n\n  ③错误，2024 年 12 月 9 日，中共中央政治局就我国历史上的边疆治理进行第十八次集\n\n体学习。习近平总书记在主持学习时强调，要坚持把维护国家安全和社会稳定作为边疆治理\n\n的底线要求。完善共建共治共享的社会治理制度，不断夯实基层基础，提升边疆地区社会治\n\n理效能。加强基础设施建设，强化科技赋能，提高卫国戍边整体能力。故“把全面建成小康\n\n社会、少数民族一个都不能少作为边疆治理的底线要求”应是“把维护国家安全和社会稳定\n\n作为边疆治理的底线要求”。\n\n  ④正确，2024 年 12 月 9 日，中共中央政治局就我国历史上的边疆治理进行第十八次集\n\n体学习。习近平总书记在主持学习时指出，推进中国式现代化，边疆地区一个都不能少。要\n\n把边疆地区发展纳入中国式现代化战略全局，纳入区域协调发展战略、区域重大战略，完整\n\n准确全面贯彻新发展理念，支持边疆地区依托自身条件禀赋，在融入新发展格局、融入全国\n\n统一大市场中实现自身高质量发展。\n\n  故②④表述正确，共 2 项。\n\n  故正确答案为 B。\n\n  【解析视频】","figs":[],"state":"已标记","notes":[],"domains":["政治理论","社会治理"],"nature":"知识题","current":true,"links":[{"id":"k-40ff1c577156271c","label":"以推进中华民族共同体建设为边疆民族地区工作主线","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"推进中华民族共同体建设作为边疆民族","why":"讲话将推进中华民族共同体建设明确为边疆民族地区工作主线。","origin":"逐题标记"},{"id":"k-03c58c94ebbcdde9","label":"边疆治理研究队伍须政治立场坚定、理论修养和综合素质过硬","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"打造一支政治立场坚定、理论修养和综合素质过硬的边疆治理研究队伍","why":"讲话对边疆治理研究队伍提出政治立场、理论修养和综合素质三方面要求。","origin":"逐题标记"},{"id":"k-3c91ffae4f24261e","label":"维护国家安全和社会稳定是边疆治理的底线要求","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"维护国家安全和社会稳定作为边疆治理","why":"维护国家安全和社会稳定共同构成边疆治理的底线要求。","origin":"逐题标记"},{"id":"k-a2a4f239feec1a30","label":"边疆地区发展纳入中国式现代化战略全局和两项区域战略","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"把边疆地区发展纳入中国式现代化战略全局，纳入区域协调发展战略、区域重大战略","why":"讲话明确边疆地区发展同时纳入中国式现代化战略全局、区域协调发展战略和区域重大战略。","origin":"逐题标记"}]},"政治理论必刷100题#53":{"stem":"习近平总书记指出：“团结奋斗是党领导人民创造历史伟业的必由之路。”这一重\n\n要论断，深刻揭示了过去我们取得成功、未来我们接续前进的力量所在。我们靠团结奋斗创\n\n造了辉煌历史，还要靠团结奋斗开辟美好未来。以下相关说法正确的有（        ）。\n\n    ①团结奋斗是中国共产党和中国人民最显著的精神标识\n\n    ②党的领导是统一战线团结人凝聚人的根本保证\n\n    ③把深化党的创新理论武装作为团结奋斗的思想基础\n\n    ④把团结和斗争统一起来，发扬“团结—批评—团结”的优良传统\n\n    ⑤统一战线是团结海内外全体中华儿女实现中华民族伟大复兴的重要法宝","options":["2 项","3 项","4 项","5 项"],"answer":"D","analysis":"53.【答案】D\n\n  【解析】\n\n  本题考查理论与政策。\n\n  2025 年 7 月，中共中央统战部在《求是》杂志上刊文《画好团结奋斗的最大同心圆》\n                                           （以\n\n下简称文章）。\n\n  ①正确，文章在“二、坚持原则立场，始终坚守团结奋斗的正确方向”部分指出：“团\n\n结奋斗是中国共产党和中国人民最显著的精神标识，中国共产党 100 多年的历史就是党领导\n\n人民团结拼搏的奋斗史······”\n\n  ②正确，文章在“二、坚持原则立场，始终坚守团结奋斗的正确方向”部分指出：“把\n\n坚持党的全面领导作为团结奋斗的根本保证······统一战线是党领导的统一战线，党\n\n的领导是统一战线团结人凝聚人的根本保证······”\n\n  ③正确，文章在“二、坚持原则立场，始终坚守团结奋斗的正确方向”部分指出：“把\n\n深化党的创新理论武装作为团结奋斗的思想基础。新时代新征程团结奋斗，根本在于用习近\n\n平新时代中国特色社会主义思想统一意志和行动······”\n\n  ④正确，文章在“二、坚持原则立场，始终坚守团结奋斗的正确方向”部分指出：“把\n\n凝聚人心汇聚力量作为团结奋斗的主要任务······要把团结和斗争统一起来，发扬\n\n‘团结—批评—团结’的优良传统，在事关大是大非的原则问题上立场坚定、旗帜鲜明，敢\n\n于同一切破坏团结统一的错误言行作坚决斗争······”\n\n  ⑤正确，文章在“三、把握着力重点，不断汇聚团结奋斗的强大合力”部分指出：“统\n\n一战线是团结海内外全体中华儿女实现中华民族伟大复兴的重要法宝。新征程上，统一战线\n\n承担着促进中华儿女大团结的历史责任······”\n\n  故①②③④⑤均表述正确，共 5 项。\n\n  故正确答案为 D。","figs":[],"state":"已标记","notes":[],"domains":["政治理论"],"nature":"知识题","current":false,"links":[{"id":"k-9bf29c07d7ac740f","label":"团结奋斗是中国共产党和中国人民最显著的精神标识","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"团结奋斗是中国共产党和中国人民最显著的精神标识","why":"这一判断以党领导人民团结拼搏的奋斗史为依据。","origin":"逐题标记"},{"id":"k-fd799f951e5f2260","label":"党的领导是统一战线团结人凝聚人的根本保证","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"党的领导是统一战线团结人凝聚人的根本保证","why":"统一战线由党领导，党的领导为其团结人、凝聚人提供政治保证。","origin":"逐题标记"},{"id":"k-748d71754df565c8","label":"深化党的创新理论武装是团结奋斗的思想基础","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"深化党的创新理论武装作为团结奋斗的思想基础","why":"党的创新理论为新时代新征程团结奋斗统一意志和行动。","origin":"逐题标记"},{"id":"k-84406bbb9cb88354","label":"团结奋斗中统一团结和斗争并发扬“团结—批评—团结”传统","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"把团结和斗争统一起来，发扬“团结—批评—团结”的优良传统","why":"在凝聚人心的同时，对破坏团结统一的错误言行坚持原则、开展斗争。","origin":"逐题标记"},{"id":"k-e7232480a573137c","label":"统一战线是团结海内外中华儿女实现民族复兴的重要法宝","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"统一战线是团结海内外全体中华儿女实现中华民族伟大复兴的重要法宝","why":"统一战线承担促进中华儿女大团结的历史责任，为民族复兴汇聚力量。","origin":"逐题标记"}]},"政治理论必刷100题#54":{"stem":"协商民主是实践全过程人民民主的重要形式。关于全面发展协商民主，下列说法不\n\n正确的是：","options":["协商民主包括政党协商、人大协商、政府协商、政协协商、人民团体协商、基层协商\n\n以及社会组织协商","中国人民政治协商会议的主要职能是政治协商、民主监督、依法行政","健全协商于决策之前和决策实施之中的落实机制，完善协商成果采纳、落实、反馈机\n\n制","协商民主是党领导人民有效治理国家、保证人民当家作主的重要制度设计"],"answer":"B","analysis":"54.【答案】B\n\n  【解析】\n\n  本题考查理论与政策。\n\n  A 项正确，党的二十大报告在“六、发展全过程人民民主，保障人民当家作主”部分指\n\n出：“协商民主是实践全过程人民民主的重要形式。完善协商民主体系，统筹推进政党协商、\n\n人大协商、政府协商、政协协商、人民团体协商、基层协商以及社会组织协商，健全各种制\n\n度化协商平台，推进协商民主广泛多层制度化发展。”\n\n  B 项错误，中国人民政治协商会议的主要职能是政治协商、民主监督、参政议政。这三\n\n项主要职能是各党派团体、各族各界人士在中国政治体制中参与国事、发挥作用的重要内容\n\n和基本形式，体现了人民政协的性质和特点，是人民政协区别于其他政治组织的重要标志。\n\n选项中“依法行政”表述错误，应为“参政议政”。\n\n  C 项正确，党的二十届三中全会通过的《中共中央关于进一步全面深化改革 推进中国\n\n式现代化的决定》在“八、健全全过程人民民主制度体系”部分指出：“健全协商民主机\n\n制······完善协商民主体系，丰富协商方式······健全协商于决策之前和决策\n\n实施之中的落实机制，完善协商成果采纳、落实、反馈机制。”\n\n  D 项正确，2019 年 9 月 20 日，习近平总书记在中央政协工作会议暨庆祝中国人民政治\n\n协商会议成立 70 周年大会上的讲话中指出：“协商民主是党领导人民有效治理国家、保证\n\n人民当家作主的重要制度设计，同选举民主相互补充、相得益彰。人民政协在协商中促进广\n\n泛团结、推进多党合作、实践人民民主，既秉承历史传统，又反映时代特征，充分体现了我\n\n国社会主义民主有事多商量、遇事多商量、做事多商量的特点和优势。”\n\n  本题为选非题，故正确答案为 B。","figs":[],"state":"已标记","notes":[],"domains":["政治理论"],"nature":"知识题","current":false,"links":[{"id":"k-cd103ea7d100d309","label":"社会主义协商民主的七类协商渠道","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"人大协商、政府协商、政协协商、人民团体协商、基层协商以及社会组织协商","why":"政党、人大、政府、政协、人民团体、基层和社会组织协商构成题目所考查的渠道范围。","origin":"逐题标记"},{"id":"k-6ad5ecbfc9ce3c8d","label":"人民政协的主要职能是政治协商、民主监督和参政议政","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"中国人民政治协商会议的主要职能是政治协商、民主监督、参政议政","why":"参政议政与政治协商、民主监督并列为人民政协的三项主要职能。","origin":"逐题标记"},{"id":"k-0fe7109701cd68dc","label":"协商贯穿决策前和实施中并实行成果采纳、落实和反馈","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"实施之中的落实机制，完善协商成果采纳、落实、反馈机制","why":"协商民主机制同时明确开展协商的时点和协商成果的处理环节。","origin":"逐题标记"},{"id":"k-275eec537c1fb9bc","label":"协商民主是党领导人民有效治理国家、保证人民当家作主的重要制度设计","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"协商民主是党领导人民有效治理国家、保证人民当家作主的重要制度设计","why":"这一制度定位明确了协商民主在国家治理和保障人民当家作主中的作用。","origin":"逐题标记"}]},"政治理论必刷100题#55":{"stem":"概括提出并深入阐述中国式现代化理论，是党的二十大的一个重大理论创新，是科\n\n学社会主义的最新重大成果。关于中国式现代化，下列说法错误的是（         ）。","options":["中国式现代化深深植根于中华优秀传统文化，体现科学社会主义的先进本质","中国式现代化是一种全新的人类文明形态，是对西方式现代化理论和实践的重大超越","中国式现代化是我们为如何唤醒“睡狮”、实现民族复兴这个重大历史课题所给出的\n\n答案","积极输出中国式现代化、“中国模式”，必然会造福一些受“道路选择”困扰的发展\n\n中国家"],"answer":"D","analysis":"55.【答案】D\n\n  【解析】\n\n  本题考查理论与政策。\n\n  2025 年第 1 期《求是》杂志发表了习近平总书记重要文章《以中国式现代化全面推进\n\n强国建设、民族复兴伟业》（以下简称文章）\n                   。\n\n  A、B 两项正确，文章指出：“中国式现代化，深深植根于中华优秀传统文化，体现科\n\n学社会主义的先进本质，借鉴吸收一切人类优秀文明成果，代表人类文明进步的发展方向，\n\n展现了不同于西方现代化模式的新图景，是一种全新的人类文明形态。中国式现代化作为科\n\n学社会主义的最新重大成果，在国际上引起广泛关注······中国式现代化是对西方式\n\n现代化理论和实践的重大超越······中国式现代化中蕴含的独特世界观、价值观、历\n\n史观、文明观、民主观、生态观等及其伟大实践，是对世界现代化理论和实践的重大创新。”\n\n  C 项正确，D 项错误，文章指出：“‘道路选择’困扰着许多发展中国家。中国式现代\n\n化的初步成功实践和取得的显著成就，新时代以来‘东升西降’、‘中治西乱’的鲜明对比，\n\n使广大发展中国家看到了新的希望，有了新的选择。中国式现代化，是我们为如何唤醒‘睡\n\n狮’、实现民族复兴这个重大历史课题所给出的答案，是选择自己的道路、做自己的事情。\n\n我们无意也没有输出中国式现代化、‘中国模式’，但中国式现代化为广大发展中国家独立\n\n自主迈向现代化树立了典范，必然会为一些发展中国家所借鉴。”故 D 项“积极输出”“必\n\n然会造福······发展中国家”表述错误，应为“无意也没有输出”“必然会为一些发\n\n展中国家所借鉴”。\n\n  本题为选非题，故正确答案为 D。","figs":[],"state":"已标记","notes":[],"domains":["政治理论"],"nature":"知识题","current":false,"links":[{"id":"k-677ff089a4d50bd2","label":"中国式现代化植根于中华优秀传统文化并体现科学社会主义先进本质","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"中国式现代化深深植根于中华优秀传统文化，体现科学社会主义的先进本质","why":"这一表述分别明确了中国式现代化的文化根基和社会主义属性。","origin":"逐题标记"},{"id":"k-07dbbc0396f95575","label":"中国式现代化开创人类文明新形态并超越西方式现代化理论和实践","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"中国式现代化是一种全新的人类文明形态，是对西方式现代化理论和实践的重大超越","why":"中国式现代化的独特理念和实践展现了人类文明发展的新图景。","origin":"逐题标记"},{"id":"k-1654a31f6370d6b4","label":"以中国式现代化全面推进中华民族伟大复兴","catalog_id":"a527cafd4023765d","type":"观点与论证","role":"直接考查","field":"answer","quote":"实现民族复兴这个重大历史课题所给出的答案","why":"中国式现代化回答了通过自主选择发展道路实现民族复兴的历史课题。","origin":"逐题标记"},{"id":"k-ffae7f6fdc4683e5","label":"中国式现代化为发展中国家自主迈向现代化提供可借鉴的经验","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"自主迈向现代化树立了典范，必然会为一些发展中国家所借鉴","why":"国际意义在于提供可自主借鉴的经验，中国无意输出自身模式。","origin":"逐题标记"}]},"政治理论必刷100题#56":{"stem":"习近平总书记指出：“要持之以恒净化政治生态”“严明政治纪律和政治规矩，严\n\n肃党内政治生活”“促进政治生态山清水秀”。下列与政治建设相关的表述不正确的是\n\n（            ）。","options":["新征程上，要坚持以党的政治建设为统领，推动全面从严治党向纵深发展","政治上的先进性，是马克思主义政党区别于其他政党的一个显著特征","旗帜鲜明讲政治是我们党的政治优势、是我们党永葆生机活力的根本保证","巩固和发展中国共产党领导的最广泛的爱国统一战线是新时代最大的政治"],"answer":"D","analysis":"56.【答案】D\n\n  【解析】\n\n  本题考查理论与政策。\n\n  A 项正确，2024 年 2 月 22 日《人民日报》发表的文章《加强党的政治建设   推动全面\n\n从严治党向纵深发展（深入学习贯彻习近平新时代中国特色社会主义思想）\n                                》指出，党的十\n\n八大以来，以习近平同志为核心的党中央明确了政治建设在新时代党的建设中的战略定位，\n\n抓住了全面从严治党的根本性问题。新征程上，要坚持以党的政治建设为统领，推动全面从\n\n严治党向纵深发展。\n\n  B 项正确，2024 年 2 月 22 日《人民日报》发表的文章《加强党的政治建设   推动全面\n\n从严治党向纵深发展（深入学习贯彻习近平新时代中国特色社会主义思想）\n                                》指出，政治上\n\n的先进性，是马克思主义政党区别于其他政党的一个显著特征。加强党的政治建设，目的就\n\n是坚定政治信仰，强化政治领导，提高政治能力，净化政治生态，实现全党团结统一、行动\n\n一致。\n\n  C 项正确，2022 年 10 月 12 日《光明日报》发表的文章《新时代党的政治建设取得重大\n\n历史性成就》指出，强调旗帜鲜明讲政治是我们党的政治优势、是我们党永葆生机活力的根\n\n本保证。旗帜鲜明讲政治，既是马克思主义政党的鲜明特征，也是我们党一以贯之的政治优\n\n势。讲政治，是我们党补钙壮骨、强身健体的根本保证，是我们党培养自我革命勇气、增强\n\n自我净化能力的根本途径。\n\n  D 项错误，2023 年 12 月 29 日，习近平总书记在全国政协新年茶话会上发表重要讲话。\n\n他强调，以中国式现代化全面推进强国建设、民族复兴伟业，是新时代新征程党和国家的中\n\n心任务，是新时代最大的政治。故“巩固和发展中国共产党领导的最广泛的爱国统一战线”\n\n表述错误，应为“以中国式现代化全面推进强国建设、民族复兴伟业”。\n\n  本题为选非题，故正确答案为 D。","figs":[],"state":"已标记","notes":[],"domains":["政治理论"],"nature":"知识题","current":false,"links":[{"id":"k-1654a31f6370d6b4","label":"以中国式现代化全面推进中华民族伟大复兴","catalog_id":"a527cafd4023765d","type":"观点与论证","role":"直接考查","field":"answer","quote":"以中国式现代化全面推进强国建设、民族复兴伟业，是新时代新征程党和国家的中\n\n心任务，是新时代最大的政治","why":"新时代最大的政治这一定位是判断题中相关表述的依据。","origin":"逐题标记"},{"id":"k-9a9a9867c701a684","label":"党的政治建设","catalog_id":"43a0142f83147a14","type":"观点与论证","role":"直接考查","field":"question","quote":"坚持以党的政治建设为统领，推动全面从严治党向纵深发展","why":"题目考查党的政治建设在推进全面从严治党中的统领地位。","origin":"逐题标记"},{"id":"k-526664b140c06248","label":"政治上的先进性是马克思主义政党的显著特征","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"政治上的先进性，是马克思主义政党区别于其他政党的一个显著特征","why":"题目要求辨认马克思主义政党在政治上的显著特征。","origin":"逐题标记"},{"id":"k-cb8a75e17fe6c2b4","label":"旗帜鲜明讲政治是党的政治优势和永葆生机活力的根本保证","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"旗帜鲜明讲政治是我们党的政治优势、是我们党永葆生机活力的根本保证","why":"题目要求核对旗帜鲜明讲政治在党的建设中的作用。","origin":"逐题标记"}]},"政治理论必刷100题#57":{"stem":"当前我国同周边关系处于近代以来最好的时期，同时也进入周边格局和世界变局深\n\n度联动的重要阶段。关于当前我国同周边关系，下列表述正确的是（          ）。","options":["以安危与共、求同存异、对话协商的亚洲安全模式为基本遵循","以睦邻、安邻、富邻、亲诚惠容、命运与共为理念方针","以统筹国内国际两个大局为战略支撑","以高质量共建“一带一路”为共同愿景"],"answer":"B","analysis":"57.【答案】B\n\n  【解析】\n\n  本题考查理论与政策。\n\n  A、C、D 三项错误，B 项正确，2025 年 4 月 8 日至 9 日，中央周边工作会议在北京举行，\n\n习近平总书记出席会议并发表重要讲话。会议指出，当前我国同周边关系处于近代以来最好\n\n的时期，同时也进入周边格局和世界变局深度联动的重要阶段。要坚持以习近平新时代中国\n\n特色社会主义思想为指导，紧紧围绕党和国家中心任务，统筹国内国际两个大局、发展安全\n\n两件大事，高举人类命运共同体旗帜，以建设和平、安宁、繁荣、美丽、友好“五大家园”\n\n为共同愿景，以睦邻、安邻、富邻、亲诚惠容、命运与共为理念方针，以和平、合作、开放、\n\n包容的亚洲价值观为基本遵循，以高质量共建“一带一路”为主要平台，以安危与共、求同\n\n存异、对话协商的亚洲安全模式为战略支撑，携手周边国家共创美好未来。\n\n  故正确答案为 B。","figs":[],"state":"已标记","notes":[],"domains":["政治理论"],"nature":"知识题","current":true,"links":[{"id":"k-bc6fe8ff593a50fa","label":"周边工作的理念方针是睦邻、安邻、富邻、亲诚惠容、命运与共","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"以睦邻、安邻、富邻、亲诚惠容、命运与共为理念方针","why":"题目要求准确辨认中央周边工作部署中的理念方针。","origin":"逐题标记"},{"id":"k-8167806ac7f256dc","label":"建设和平、安宁、繁荣、美丽、友好“五大家园”是周边工作的共同愿景","catalog_id":null,"type":"观点与论证","role":"解题依据","field":"answer","quote":"以建设和平、安宁、繁荣、美丽、友好“五大家园”\n\n为共同愿景","why":"共同愿景的具体内容可用于核对选项中的政策定位。","origin":"逐题标记"},{"id":"k-264d3ff2a3543720","label":"和平、合作、开放、包容的亚洲价值观是周边工作的基本遵循","catalog_id":null,"type":"观点与论证","role":"解题依据","field":"answer","quote":"以和平、合作、开放、\n\n包容的亚洲价值观为基本遵循","why":"基本遵循的具体内容可用于区分亚洲价值观和亚洲安全模式的定位。","origin":"逐题标记"},{"id":"k-b11f5757baa9e36c","label":"高质量共建“一带一路”是周边工作的主要平台","catalog_id":null,"type":"观点与论证","role":"解题依据","field":"answer","quote":"以高质量共建“一带一路”为主要平台","why":"主要平台的定位可用于核对选项对高质量共建“一带一路”的归类。","origin":"逐题标记"},{"id":"k-399c221745f3140a","label":"安危与共、求同存异、对话协商的亚洲安全模式是周边工作的战略支撑","catalog_id":null,"type":"观点与论证","role":"解题依据","field":"answer","quote":"以安危与共、求同\n\n存异、对话协商的亚洲安全模式为战略支撑","why":"战略支撑的具体内容可用于核对选项对亚洲安全模式和统筹国内国际两个大局的定位。","origin":"逐题标记"}]},"政治理论必刷100题#58":{"stem":"文化是一个国家、一个民族的灵魂，是民族生存和发展的重要力量。纵观人类文明\n\n发展史，文化兴则国运兴，文化强则民族强。关于习近平文化思想，下列说法不正确的是\n\n（       ）。","options":["深化文化体制机制改革要激发全民族文化创新创造活力","始终坚持文化建设着眼于经济发展、落脚于经济发展","加强国际传播能力建设，形成同我国综合国力和国际地位相匹配的国际话语权","要在创造性转化和创新性发展中赓续中华文脉"],"answer":"B","analysis":"58.【答案】B\n\n  【解析】\n\n  本题考查理论与政策。\n\n  A 项正确，党的二十届三中全会通过的《中共中央关于进一步全面深化改革          推进中国\n\n式现代化的决定》在“十、深化文化体制机制改革”中指出：“中国式现代化是物质文明和\n\n精神文明相协调的现代化。必须增强文化自信，发展社会主义先进文化，弘扬革命文化，传\n\n承中华优秀传统文化，加快适应信息技术迅猛发展新形势，培育形成规模宏大的优秀文化人\n\n才队伍，激发全民族文化创新创造活力。”\n\n  B 项错误，习近平总书记在中共中央政治局第十七次集体学习时强调：“要始终坚持文\n\n化建设着眼于人、落脚于人。着眼满足人民群众多样化、多层次、多方面的精神文化需求，\n\n提升文化服务和文化产品供给能力，增强人民群众文化获得感、幸福感。”故“着眼于经济\n\n发展、落脚于经济发展”表述错误，应为“着眼于人、落脚于人”。\n\n  C 项正确，党的二十大报告在“八、推进文化自信自强，铸就社会主义文化新辉煌”部\n\n分指出：“（五）增强中华文明传播力影响力······加强国际传播能力建设，全面提\n\n升国际传播效能，形成同我国综合国力和国际地位相匹配的国际话语权。”\n\n  D 项正确，习近平总书记在中共中央政治局第十七次集体学习时指出：“要在创造性转\n\n化和创新性发展中赓续中华文脉。高扬中华民族的文化主体性，把历经沧桑留下的中华文明\n\n瑰宝呵护好、弘扬好、发展好。深入挖掘和阐发中华优秀传统文化的精神内涵，用马克思主\n\n义激活中华传统文化中的优秀因子并赋予其新的时代内涵，发展新时代中国特色社会主义文\n\n化。”\n\n  本题为选非题，故正确答案为 B。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","文化"],"nature":"知识题","current":false,"links":[{"id":"k-d99d03e079c229cd","label":"文化建设要着眼于人、落脚于人","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"文化建设着眼于人、落脚于人","why":"文化建设的着眼点和落脚点是题目要求辨析的核心。","origin":"逐题标记"},{"id":"k-b7327d285ec6ad13","label":"深化文化体制机制改革要激发全民族文化创新创造活力","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"深化文化体制机制改革要激发全民族文化创新创造活力","why":"题目要求核对深化文化体制机制改革对创新创造活力的要求。","origin":"逐题标记"},{"id":"k-546fac34f2e6a836","label":"加强国际传播能力建设以形成同我国综合国力和国际地位相匹配的国际话语权","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"加强国际传播能力建设，形成同我国综合国力和国际地位相匹配的国际话语权","why":"题目要求核对国际传播能力建设与国际话语权的目标关系。","origin":"逐题标记"},{"id":"k-d40d09c540a4554b","label":"在创造性转化和创新性发展中赓续中华文脉","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"在创造性转化和创新性发展中赓续中华文脉","why":"题目要求辨认赓续中华文脉的两项要求。","origin":"逐题标记"}]},"政治理论必刷100题#59":{"stem":"文化兴则国运兴，文化强则民族强。习近平总书记指出，“建设文化强国，事关中\n\n国式现代化建设全局，事关中华民族复兴大业，事关提升国际竞争力。”关于习近平文化思\n\n想，下列说法不正确的是（      ）。","options":["意识形态工作是为国家立心、为民族立魂的工作","中华优秀传统文化是中华文明的智慧结晶和精华所在，是中华民族的根和魂","调动人民群众的积极性是做好新闻舆论工作的第一位要求","互联网日益成为意识形态斗争的主阵地、主战场、最前沿"],"answer":"C","analysis":"59.【答案】C\n\n  【解析】\n\n  本题考查理论与政策。\n\n  A 项正确，党的二十大报告指出，意识形态工作是为国家立心、为民族立魂的工作。牢\n\n牢掌握党对意识形态工作领导权，全面落实意识形态工作责任制，巩固壮大奋进新时代的主\n\n流思想舆论。\n\n  B 项正确，2022 年 5 月 27 日，习近平总书记在中共十九届中央政治局第三十九次集体\n\n学习时的讲话中指出，中华优秀传统文化是中华文明的智慧结晶和精华所在，是中华民族的\n\n根和魂，是我们在世界文化激荡中站稳脚跟的根基。\n\n  C 项错误，新闻舆论工作有鲜明的意识形态属性，坚持正确的政治方向是做好新闻舆论\n\n工作的第一位要求，党性原则是党的新闻舆论工作的根本原则。故“调动人民群众的积极性”\n\n表述错误，应为“坚持正确的政治方向”。\n\n  D 项正确，2018 年 4 月 20 日，习近平总书记在全国网络安全和信息化工作会议上强调，\n\n信息流通无国界，网络空间有硝烟。互联网日益成为意识形态斗争的主阵地、主战场、最前\n\n沿。能不能牢牢掌握意识形态工作领导权，关键要看能不能占领网上阵地，能不能赢得网上\n\n主导权。\n\n  本题为选非题，故正确答案为 C。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","文化"],"nature":"知识题","current":false,"links":[{"id":"k-b8287c6e4e5e6952","label":"坚持正确的政治方向是做好新闻舆论工作的第一位要求","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"坚持正确的政治方向是做好新闻舆论\n\n工作的第一位要求","why":"新闻舆论工作的首要要求决定相关表述的正误。","origin":"逐题标记"},{"id":"k-2cb4d6b25892af6b","label":"意识形态工作是为国家立心、为民族立魂的工作","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"意识形态工作是为国家立心、为民族立魂的工作","why":"题目要求判断对意识形态工作作用的表述是否准确。","origin":"逐题标记"},{"id":"k-84e7d2fd808616ac","label":"中华优秀传统文化是中华文明的智慧结晶和精华所在，是中华民族的根和魂","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"中华优秀传统文化是中华文明的智慧结晶和精华所在，是中华民族的根和魂","why":"题目要求核对中华优秀传统文化对中华文明和中华民族的意义。","origin":"逐题标记"},{"id":"k-79b625cb0327b9f8","label":"互联网日益成为意识形态斗争的主阵地、主战场、最前沿","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"互联网日益成为意识形态斗争的主阵地、主战场、最前沿","why":"题目要求判断互联网在意识形态斗争中的阵地定位。","origin":"逐题标记"}]},"政治理论必刷100题#60":{"stem":"团结奋斗是中国人民创造历史伟业的必由之路。下列与之相关的说法不正确的是\n\n（      ）。","options":["能团结奋斗的民族才有前途，能团结奋斗的政党才能立于不败之地","新征程上我们要靠马克思主义进一步凝心聚力、团结奋斗","我们靠团结奋斗创造了辉煌历史，还要靠团结奋斗开辟美好未来","必须发扬斗争精神，把握斗争方向，掌握斗争规律，增强斗争本领"],"answer":"B","analysis":"60.【答案】B\n\n  【解析】\n\n  本题考查理论与政策。\n\n  2025 年 7 月 1 日出版的第 13 期《求是》杂志发表了习近平总书记的重要文章《团结奋\n\n斗是中国人民创造历史伟业的必由之路》。这是习近平总书记 2016 年 10 月至 2025 年 4 月期\n\n间有关重要论述的节录。\n\n  A 项正确，2022 年 1 月 30 日，习近平总书记在 2022 年春节团拜会上的讲话中指出：“百\n\n年奋斗历史告诉我们，团结就是力量，奋斗开创未来；能团结奋斗的民族才有前途，能团结\n\n奋斗的政党才能立于不败之地。”\n\n  B 项错误，2023 年 12 月 21 日、22 日，习近平总书记在中央政治局学习贯彻习近平新\n\n时代中国特色社会主义思想主题教育专题民主生活会上的讲话中指出：“团结奋斗是党领导\n\n人民创造历史伟业的必由之路。团结奋斗要靠目标凝心聚力，新征程上我们就要靠中国式现\n\n代化进一步凝心聚力、团结奋斗。”故“马克思主义”表述有误，应改为“中国式现代化”。\n\n  C 项正确，2022 年 1 月 30 日，习近平总书记在 2022 年春节团拜会上的讲话中指出：“一\n\n百年来，党和人民取得的一切成就都是团结奋斗的结果，团结奋斗是中国共产党和中国人民\n\n最显著的精神标识······我们靠团结奋斗创造了辉煌历史，还要靠团结奋斗开辟美好\n\n未来。”\n\n  D 项正确，2021 年 11 月 11 日，习近平总书记在党的十九届六中全会第二次全体会议上\n\n的讲话中指出：“我们党依靠斗争创造历史，更要依靠斗争赢得未来······我们必须\n\n把握新的伟大斗争的历史特点，发扬斗争精神，把握斗争方向，把握斗争主动权，坚定斗争\n\n意志，掌握斗争规律，增强斗争本领，有效应对重大挑战、抵御重大风险、克服重大阻力、\n\n解决重大矛盾，战胜前进道路上的一切艰难险阻，不断夺取新时代伟大斗争的新胜利。”\n\n  本题为选非题，故正确答案为 B。","figs":[],"state":"已标记","notes":[],"domains":["政治理论"],"nature":"知识题","current":false,"links":[{"id":"k-7244092500c056a9","label":"新征程要靠中国式现代化进一步凝心聚力、团结奋斗","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"团结奋斗要靠目标凝心聚力，新征程上我们就要靠中国式现\n\n代化进一步凝心聚力、团结奋斗","why":"中国式现代化作为凝聚力量的共同目标是题目要求辨析的核心。","origin":"逐题标记"},{"id":"k-466e66e213486cfd","label":"团结奋斗是民族赢得前途、政党立于不败之地的重要条件","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"能团结奋斗的民族才有前途，能团结奋斗的政党才能立于不败之地","why":"题目要求核对团结奋斗对于民族和政党的意义。","origin":"逐题标记"},{"id":"k-f3d1d670216db872","label":"团结奋斗贯穿于创造历史成就和开辟未来","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"我们靠团结奋斗创造了辉煌历史，还要靠团结奋斗开辟美好未来","why":"题目要求辨认团结奋斗在历史和未来两个阶段中的作用。","origin":"逐题标记"},{"id":"k-a3e46e7df98813af","label":"开展伟大斗争要发扬斗争精神、把握斗争方向和规律、增强斗争本领","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"必须发扬斗争精神，把握斗争方向，掌握斗争规律，增强斗争本领","why":"题目要求核对开展伟大斗争的具体要求。","origin":"逐题标记"}]},"政治理论必刷100题#61":{"stem":"党的十八大以来，我们坚持把文化建设摆在治国理政突出位置，作出一系列重大部\n\n署，形成新时代中国特色社会主义文化思想。以下关于文化建设的说法，不正确的是\n\n（       ）。","options":["要把育人才、建队伍作为重要而紧迫的战略任务，统筹各类人才培养，建设一支规模\n\n宏大、结构合理、锐意创新的高水平文化人才队伍","高扬中华民族的文化主体性，把历经沧桑留下的中华文明瑰宝呵护好、弘扬好、发展\n\n好","马克思主义是我们提高国家文化软实力最深厚的源泉，是我们提高国家文化软实力的\n\n重要途径","文物承载灿烂文明，传承历史文化，维系民族精神，是老祖宗留给我们的宝贵遗产，\n\n是加强社会主义精神文明建设的深厚滋养"],"answer":"C","analysis":"61.【答案】C\n\n  【解析】\n\n  本题考查理论与政策。\n\n  A 项正确，2025 年 4 月 16 日出版的第 8 期《求是》杂志发表了中共中央总书记、国家\n\n主席、中央军委主席习近平的重要文章《加快建设文化强国》。文章指出，文化创造核心在\n\n人。要把育人才、建队伍作为重要而紧迫的战略任务，统筹各类人才培养，建设一支规模宏\n\n大、结构合理、锐意创新的高水平文化人才队伍。\n\n  B 项正确，2024 年 10 月 28 日，习近平总书记在中共中央政治局第十七次集体学习时指\n\n出，要在创造性转化和创新性发展中赓续中华文脉。高扬中华民族的文化主体性，把历经沧\n\n桑留下的中华文明瑰宝呵护好、弘扬好、发展好。\n\n  C 项错误，2013 年 12 月 30 日，习近平总书记在十八届中央政治局第十二次集体学习时\n\n指出，中华文化是我们提高国家文化软实力最深厚的源泉，是我们提高国家文化软实力的重\n\n要途径。因此“马克思主义”说法错误，应是“中华文化”。\n\n  D 项正确，2016 年 3 月 23 日，习近平总书记对文物工作作出重要指示。他指出，文物\n\n承载灿烂文明，传承历史文化，维系民族精神，是老祖宗留给我们的宝贵遗产，是加强社会\n\n主义精神文明建设的深厚滋养。\n\n  本题为选非题，故正确答案为 C。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","文化"],"nature":"知识题","current":false,"links":[{"id":"k-baf5042153f805c5","label":"中华文化是提高国家文化软实力最深厚的源泉","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"中华文化是我们提高国家文化软实力最深厚的源泉","why":"文化软实力的源泉是题目要求辨析的核心。","origin":"逐题标记"},{"id":"k-481a781c59dda820","label":"文化强国建设要把育人才、建队伍作为重要而紧迫的战略任务","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"把育人才、建队伍作为重要而紧迫的战略任务","why":"题目要求核对育人才、建队伍在文化建设中的战略地位。","origin":"逐题标记"},{"id":"k-27898b69aaacf74c","label":"高扬中华民族文化主体性要呵护好、弘扬好、发展好中华文明瑰宝","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"高扬中华民族的文化主体性，把历经沧桑留下的中华文明瑰宝呵护好、弘扬好、发展\n\n好","why":"题目要求核对高扬文化主体性对待中华文明瑰宝的要求。","origin":"逐题标记"},{"id":"k-71cc41cc86c100ca","label":"文物是加强社会主义精神文明建设的深厚滋养","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"是加强社会主义精神文明建设的深厚滋养","why":"题目以文物传承历史文化、维系民族精神的作用考查其对精神文明建设的意义。","origin":"逐题标记"}]},"政治理论必刷100题#62":{"stem":"党的十八大以来，以习近平总书记为核心的党中央高度重视社会主义精神文明建设，\n\n为推动精神文明建设领域发生全面、深刻、根本性的变化，发表了一系列重要论述。下列有\n\n关说法不正确的是（   ）。","options":["爱国主义始终是把中华民族坚强团结在一起的精神力量","以精神文明引领物质文明，是中国式现代化的重要特征","中华优秀传统文化是涵养社会主义核心价值观的重要源泉","抓精神文明建设要办实事、讲实效，紧紧围绕促进人民福祉来进行"],"answer":"B","analysis":"62.【答案】B\n\n  【解析】\n\n  本题考查理论与政策。\n\n  A 项正确，2013 年 3 月 17 日，习近平总书记在第十二届全国人民代表大会第一次会议\n\n上指出，实现中国梦必须弘扬中国精神。这就是以爱国主义为核心的民族精神，以改革创新\n\n为核心的时代精神。这种精神是凝心聚力的兴国之魂、强国之魂。爱国主义始终是把中华民\n\n族坚强团结在一起的精神力量，改革创新始终是鞭策我们在改革开放中与时俱进的精神力量。\n\n  B 项错误，2025 年 5 月 23 日，全国精神文明建设表彰大会在北京召开，会上传达了习\n\n近平总书记对精神文明建设工作作出的重要指示，习近平总书记指出，物质文明和精神文明\n\n相协调，是中国式现代化的重要特征。党的十八大以来，党中央持续推进社会主义精神文明\n\n建设，巩固壮大社会主流价值，全民族精神面貌更加奋发昂扬，人民文明素养和社会文明程\n\n度显著提升。故“以精神文明引领物质文明”说法错误，应为“物质文明和精神文明相协\n\n调”。\n\n  C 项正确，2014 年 10 月 15 日，习近平总书记在文艺工作座谈会上指出，中华优秀传统\n\n文化是中华民族的精神命脉，是涵养社会主义核心价值观的重要源泉，也是我们在世界文化\n\n激荡中站稳脚跟的坚实根基。\n\n  D 项正确，2015 年 2 月 28 日，习近平在会见第四届全国文明城市、文明村镇、文明单\n\n位和未成年人思想道德建设工作先进代表时指出，抓精神文明建设要办实事、讲实效，紧紧\n\n围绕促进人民福祉来进行，坚决反对形式主义、官僚主义，努力满足人民群众不断增长的精\n\n神文化需求。各级党委要担负好自己的责任，切实抓好精神文明建设各项工作。\n\n  本题为选非题，故正确答案为 B。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","文化"],"nature":"知识题","current":false,"links":[{"id":"k-bea39803d34d2724","label":"物质文明和精神文明相协调是中国式现代化的重要特征","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"物质文明和精神文明\n\n相协调，是中国式现代化的重要特征","why":"两种文明的协调关系决定对中国式现代化特征的表述是否准确。","origin":"逐题标记","originalId":"k-1e2b5b89e5425daa"},{"id":"k-dd039e3fc1a6a4fa","label":"爱国主义是团结中华民族的精神力量","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"爱国主义始终是把中华民族坚强团结在一起的精神力量","why":"题目要求核对爱国主义对中华民族的凝聚作用。","origin":"逐题标记"},{"id":"k-6ac7819d0e49b988","label":"中华优秀传统文化是涵养社会主义核心价值观的重要源泉","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"中华优秀传统文化是涵养社会主义核心价值观的重要源泉","why":"题目要求核对中华优秀传统文化与社会主义核心价值观的关系。","origin":"逐题标记"},{"id":"k-012f63d30d58022c","label":"精神文明建设要围绕促进人民福祉办实事、讲实效","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"抓精神文明建设要办实事、讲实效，紧紧围绕促进人民福祉来进行","why":"题目要求核对精神文明建设的工作目标和实效要求。","origin":"逐题标记"}]},"政治理论必刷100题#63":{"stem":"少年儿童的幸福成长，始终是习近平总书记心中最温柔的牵挂。以下有关习总书记\n\n关心少年儿童健康成长的讲话，表述正确的有（     ）。\n\n  ①少年儿童是推进强国建设、民族复兴伟业的未来生力军\n\n  ②一个人可以有很多志向，但人生最重要的志向应该同祖国和人民联系在一起\n\n  ③定时体检、均衡营养是增强少年儿童体质最有效的手段\n\n  ④帮助学生在体育锻炼中享受乐趣、增强体质、健全人格、锻炼意志\n\n  ⑤美好生活都是靠劳动创造出来的，广大青少年要热爱劳动、热爱大自然","options":["2 项","3 项","4 项","5 项"],"answer":"C","analysis":"63.【答案】C\n\n  【解析】\n\n  本题考查理论与政策。\n\n  ①正确，2025 年 5 月 27 日，习近平致中国少年先锋队第九次全国代表大会的贺信中指\n\n出：“少年儿童是推进强国建设、民族复兴伟业的未来生力军，少先队是少年儿童健康成长\n\n的大学校。”\n\n  ②正确，2015 年 6 月 1 日，中国少年先锋队第七次全国代表大会在京开幕。中共中央\n\n总书记、国家主席、中央军委主席习近平亲切会见全体代表。他指出：“要从小学习立志。\n\n志向是人生的航标。一个人要做出一番成就，就要有自己的志向。一个人可以有很多志向，\n\n但人生最重要的志向应该同祖国和人民联系在一起，这是人们各种具体志向的底盘，也是人\n\n生的脊梁。”\n\n  ③错误，2023 年 5 月，习近平总书记在北京育英学校考察时指出：“体育锻炼是增强\n\n少年儿童体质最有效的手段。现在生活条件好了，孩子们不是要吃得胖胖的，而是要长得壮\n\n壮的、练得棒棒的。”故“定时体检、均衡营养”说法错误，应是“体育锻炼”。\n\n  ④正确，2020 年 9 月，在主持召开教育文化卫生体育领域专家代表座谈会时，习近平\n\n总书记强调：“一方面，要让孩子们跑起来。另一方面，体育锻炼要讲究科学，做好保护和\n\n准备工作，帮助学生在体育锻炼中享受乐趣、增强体质、健全人格、锻炼意志。”\n\n  ⑤正确，2025 年 4 月，习近平总书记在参加首都义务植树活动时说：“美好生活都是\n\n靠劳动创造出来的，广大青少年要热爱劳动、热爱大自然，积极参加植树造林等公益活动，\n\n在劳动中锻炼身体、锤炼意志、增长知识，做到德智体美劳全面发展。”\n\n  故①②④⑤表述正确，共 4 项。\n\n  故正确答案为 C。","figs":[],"state":"已标记","notes":[],"domains":["政治理论"],"nature":"知识题","current":false,"links":[{"id":"k-309315bac8d2c6a2","label":"少年儿童是推进强国建设、民族复兴伟业的未来生力军","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"少年儿童是推进强国建设、民族复兴伟业的未来生力军","why":"题目要求核对少年儿童在强国建设、民族复兴伟业中的定位。","origin":"逐题标记"},{"id":"k-0f5c844f4b88a9d2","label":"人生最重要的志向应该同祖国和人民联系在一起","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"人生最重要的志向应该同祖国和人民联系在一起","why":"题目要求核对对少年儿童立志方向的要求。","origin":"逐题标记"},{"id":"k-5334bfbc0dd6987b","label":"体育锻炼是增强少年儿童体质最有效的手段","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"体育锻炼是增强\n\n少年儿童体质最有效的手段","why":"增强少年儿童体质的手段是题目要求辨析的具体内容。","origin":"逐题标记"},{"id":"k-dbabec9fa224ee82","label":"学校体育要帮助学生享受乐趣、增强体质、健全人格、锻炼意志","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"帮助学生在体育锻炼中享受乐趣、增强体质、健全人格、锻炼意志","why":"题目要求核对学校体育锻炼的四项育人目标。","origin":"逐题标记"},{"id":"k-9c50dfc7a5975103","label":"劳动创造美好生活，青少年要热爱劳动、热爱大自然","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"美好生活都是靠劳动创造出来的，广大青少年要热爱劳动、热爱大自然","why":"题目要求核对关于劳动价值和青少年成长的具体要求。","origin":"逐题标记"}]},"政治理论必刷100题#64":{"stem":"习近平总书记指出，建设更高水平平安中国，事关事业兴旺发达、事关人民美好生\n\n活、事关国家长治久安。下列关于建设更高水平平安中国的举措表述正确的有（     ）。\n\n  ①把捍卫国家政治安全摆在首位，推动公共安全治理模式向事前预防转型\n\n  ②总体国家安全观是建设更高水平平安中国的唯一遵循，必须坚定不移贯彻\n\n  ③把专项治理和系统治理、依法治理、综合治理、源头治理结合起来，发展壮大群防群\n\n治力量\n\n  ④完善社会治理体系、健全社会工作体制机制，建设人人有责、人人尽责、人人享有的\n\n社会治理共同体\n\n  ⑤始终坚持党中央对国家安全工作、对政法工作的绝对领导，充分发挥各级党委在平安\n\n建设中总揽全局、协调各方的领导作用","options":["2 项","3 项","4 项","5 项"],"answer":"C","analysis":"64.【答案】C\n\n  【解析】\n\n  本题考查理论与政策。\n\n  2025 年 2 月 28 日上午，中共中央政治局就建设更高水平平安中国进行第十九次集体学\n\n习，习近平总书记主持学习并发表重要讲话（以下简称讲话）。\n\n  ①正确，讲话指出，要把捍卫国家政治安全摆在首位，坚定维护国家政权安全、制度安\n\n全、意识形态安全。要完善公共安全体系，推动公共安全治理模式向事前预防转型，加强防\n\n灾减灾救灾、安全生产、食品药品安全、网络安全、人工智能安全等方面工作。\n\n  ②错误，讲话指出，总体国家安全观是建设更高水平平安中国的重要遵循，必须坚定不\n\n移贯彻。各级党委和政府要坚持系统思维，进一步树立发展是硬道理、安全也是硬道理的理\n\n念，在工作中自觉把发展和安全统一起来，共同谋划、一体部署、相互促进。故“唯一遵循”\n\n说法错误，应是“重要遵循”。\n\n  ③正确，讲话指出，建设更高水平平安中国，必须强化社会治安整体防控。要把专项治\n\n理和系统治理、依法治理、综合治理、源头治理结合起来，发展壮大群防群治力量，筑起真\n\n正的铜墙铁壁。\n\n  ④正确，讲话指出，要不断增进民生福祉，扎实推进共同富裕，切实维护人民群众合法\n\n权益，维护社会公平正义。要完善社会治理体系、健全社会工作体制机制，建设人人有责、\n\n人人尽责、人人享有的社会治理共同体。\n\n  ⑤正确，讲话指出，党的领导是平安中国建设的根本保证。要始终坚持党中央对国家安\n\n全工作、对政法工作的绝对领导，充分发挥各级党委在平安建设中总揽全局、协调各方的领\n\n导作用。\n\n  故①③④⑤说法正确，共 4 项。\n\n  故正确答案为 C。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","社会治理"],"nature":"知识题","current":true,"links":[{"id":"k-473c43235efd31f0","label":"总体国家安全观","catalog_id":"499077802f3e9111","type":"制度与规则","role":"直接考查","field":"answer","quote":"总体国家安全观是建设更高水平平安中国的重要遵循","why":"政策原文将总体国家安全观定位为平安中国建设的重要遵循。","origin":"逐题标记"},{"id":"k-419f54bd4d79bd94","label":"国家政治安全优先与公共安全治理事前预防","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"把捍卫国家政治安全摆在首位，推动公共安全治理模式向事前预防转型","why":"这项举措同时考查国家政治安全的优先地位和公共安全治理的转型方向。","origin":"逐题标记"},{"id":"k-394eb3d9e53ec1db","label":"社会治安整体防控结合专项治理与系统、依法、综合、源头治理","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"理和系统治理、依法治理、综合治理、源头治理结合起来，发展壮大群防群治力量","why":"强化社会治安整体防控要求结合多种治理方式，并壮大群防群治力量。","origin":"逐题标记"},{"id":"k-3f1c376e61227ee3","label":"社会治理共同体的人人有责、人人尽责、人人享有要求","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"人人尽责、人人享有的社会治理共同体","why":"完善社会治理体系和健全社会工作体制机制指向建设人人有责、人人尽责、人人享有的共同体。","origin":"逐题标记"},{"id":"k-e70be2bb8023926d","label":"平安中国建设坚持党中央对国家安全工作和政法工作的绝对领导","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"全工作、对政法工作的绝对领导，充分发挥各级党委在平安建设中总揽全局、协调各方","why":"党的领导是平安中国建设的根本保证，各级党委承担总揽全局、协调各方的职责。","origin":"逐题标记"}]},"政治理论必刷100题#65":{"stem":"党的十八大以来，党中央深刻把握新形势下我国城市发展规律，坚持人民城市人民\n\n建、人民城市为人民，推动城市发展取得历史性成就。关于城市工作的重要论述，说法正确\n\n的有（          ）。\n\n     ①坚持因地制宜、分类指导，以建设创新、宜居、美丽、韧性、文明、智慧的现代化人\n\n民城市为目标\n\n     ②坚持利用第一、应保尽保、以用促保，在城市更新全过程、各环节加强城市文化遗产\n\n保护\n\n     ③老旧小区改造是城市更新的一个重点，也是一项民生工程，既要保留历史记忆和特色\n\n风貌，又要解决居民关切的实际问题\n\n     ④我国城镇化正从快速增长期转向高质量发展期，城市发展正从大规模增量扩张阶段转\n\n向存量提质增效为主的阶段\n\n     ⑤着力建设舒适便利的宜居城市，坚持人口、产业、城镇、交通一体规划，优化城市空\n\n间结构","options":["①②⑤","②③④","②③⑤","①③⑤"],"answer":"D","analysis":"65.【答案】D\n\n  【解析】\n\n  本题考查理论与政策。\n\n  2025 年 7 月 14 日至 15 日，中央城市工作会议召开。\n\n  ①正确，会议指出，当前和今后一个时期城市工作的总体要求是：······坚持和\n\n加强党的全面领导，认真践行人民城市理念，坚持稳中求进工作总基调，坚持因地制宜、分\n\n类指导，以建设创新、宜居、美丽、韧性、文明、智慧的现代化人民城市为目标，以推动城\n\n市高质量发展为主题，以坚持城市内涵式发展为主线，以推进城市更新为重要抓手。\n\n  ②错误，2025 年 5 月，中共中央办公厅、国务院办公厅印发的《关于持续推进城市更\n\n新行动的意见》在“总体要求”部分指出：“工作中要做到：······坚持保护第一、\n\n应保尽保、以用促保，在城市更新全过程、各环节加强城市文化遗产保护。”故“利用第一”\n\n表述有误，应为“保护第一”。\n\n  ③正确，2024 年 4 月 22 日至 24 日，习近平总书记在重庆考察时指出，老旧小区改造\n\n是城市更新的一个重点，也是一项民生工程，既要保留历史记忆和特色风貌，又要解决居民\n\n关切的实际问题。\n\n  ④错误，会议指出，我国城镇化正从快速增长期转向稳定发展期，城市发展正从大规模\n\n增量扩张阶段转向存量提质增效为主的阶段。故“快速增长期转向高质量发展期”表述有误，\n\n应为“快速增长期转向稳定发展期”。\n\n  ⑤正确，会议部署城市工作 7 个方面的重点任务，三是着力建设舒适便利的宜居城市。\n\n坚持人口、产业、城镇、交通一体规划，优化城市空间结构；加快构建房地产发展新模式，\n\n稳步推进城中村和危旧房改造；大力发展生活性服务业，提高公共服务水平，牢牢兜住民生\n\n底线。\n\n  综上，①③⑤表述正确。\n\n  故正确答案为 D。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","公共管理"],"nature":"知识题","current":true,"links":[{"id":"k-037f61aed9e69a4c","label":"现代化人民城市的六项目标与因地制宜分类指导","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"类指导，以建设创新、宜居、美丽、韧性、文明、智慧的现代化人民城市为目标","why":"会议将六项城市建设目标与因地制宜、分类指导要求一并明确。","origin":"逐题标记"},{"id":"k-6548716f32fc5d7f","label":"城市更新中文化遗产保护第一、应保尽保、以用促保","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"应保尽保、以用促保，在城市更新全过程、各环节加强城市文化遗产保护","why":"政策要求将保护置于首位，并将文化遗产保护贯穿城市更新全过程。","origin":"逐题标记"},{"id":"k-7b8bac1c6a492016","label":"老旧小区改造兼顾历史风貌保护与居民实际需求","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"既要保留历史记忆和特色风貌，又要解决居民","why":"老旧小区改造兼具城市更新和民生工程属性，因此要同时保留历史风貌并回应居民关切。","origin":"逐题标记"},{"id":"k-be95226e605647dc","label":"我国城镇化进入稳定发展期与城市发展转向存量提质增效","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"我国城镇化正从快速增长期转向稳定发展期","why":"会议对城镇化进程和城市发展方式分别作出阶段判断，后者以存量提质增效为主。","origin":"逐题标记"},{"id":"k-1ab87841fd160ef2","label":"宜居城市建设中的人口、产业、城镇、交通一体规划","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"坚持人口、产业、城镇、交通一体规划，优化城市空间结构","why":"会议将四个要素的一体规划列为建设舒适便利的宜居城市的具体任务。","origin":"逐题标记"}]},"政治理论必刷100题#66":{"stem":"基层治理是国家治理的重要组成部分，是国家治理的基石。在以习近平同志为核心\n\n的党中央坚强领导下，通过坚持和加强党对基层治理的领导，充分调动亿万群众的积极性主\n\n动性创造性，有效应对改革发展中出现的各种社会风险挑战，激发基层活力，续写了社会长\n\n期稳定奇迹。以下相关说法正确的有（      ）。\n\n     ①加强基层党组织建设，把基层党组织建设成为团结带领群众贯彻党的理论和路线方针\n\n政策、落实党的任务的战斗堡垒\n\n     ②要把服务群众、造福群众作为基层治理的出发点和落脚点，为人民群众提供优质高效\n\n的公共服务\n\n     ③要夯实社会治理基层基础，推动社会治理重心下移，构建党组织领导的共建共治共享\n\n的城乡基层治理格局\n\n    ④要深入推进社区治理创新，构建富有活力和效率的新型基层社会治理体系","options":["①②","②③④","①②④","①②③④"],"answer":"D","analysis":"66.【答案】D\n\n  【解析】\n\n  本题考查理论与政策。\n\n  2025 年 4 月，题为《抓好基层治理现代化这项基础性工作》的文章（以下简称文章）\n\n发表。\n\n  ①正确，文章指出，坚持以党建引领基层治理。习近平总书记指出：“坚持以党建引领\n\n基层治理，提高基层党组织领导基层治理能力”······加强基层党组织建设，把基层\n\n党组织建设成为团结带领群众贯彻党的理论和路线方针政策、落实党的任务的战斗堡垒，才\n\n能不断引领基层治理取得新成效。\n\n  ②正确，文章指出，坚持服务群众、造福群众。习近平总书记指出：“要把服务群众、\n\n造福群众作为基层治理的出发点和落脚点”。加强基层治理的一个重要内容是创造既充满活\n\n力又拥有良好秩序的社会环境，实现这一目标的重要手段就是为人民群众提供优质高效的公\n\n共服务，在高效服务中实现有效治理。\n\n  ③正确，文章指出，构建共建共治共享的城乡基层治理格局。习近平总书记指出：“要\n\n夯实社会治理基层基础，推动社会治理重心下移，构建党组织领导的共建共治共享的城乡基\n\n层治理格局。”\n\n  ④正确，文章指出，创新基层治理方式。习近平总书记指出：“要深入推进社区治理创\n\n新，构建富有活力和效率的新型基层社会治理体系。”\n\n  故正确的有①②③④。\n\n  故正确答案为 D。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","社会治理"],"nature":"知识题","current":false,"links":[{"id":"k-822ba0160341550b","label":"基层党组织在基层治理中的战斗堡垒作用","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"政策、落实党的任务的战斗堡垒","why":"党建引领基层治理要求基层党组织团结带领群众贯彻党的理论和路线方针政策、落实党的任务。","origin":"逐题标记"},{"id":"k-0e3d5833ee0c27fb","label":"基层治理以服务群众、造福群众为出发点和落脚点","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"造福群众作为基层治理的出发点和落脚点","why":"为群众提供优质高效的公共服务是落实这一要求、实现有效治理的途径。","origin":"逐题标记"},{"id":"k-6fed0dadc033dc9b","label":"治理重心下移与党组织领导的城乡基层共建共治共享","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"推动社会治理重心下移，构建党组织领导的共建共治共享","why":"夯实社会治理基层基础要求推动治理重心下移，并由党组织领导构建城乡基层治理格局。","origin":"逐题标记"},{"id":"k-f1dc468c55a7e7c8","label":"以社区治理创新构建富有活力和效率的基层社会治理体系","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"新，构建富有活力和效率的新型基层社会治理体系","why":"社区治理创新是改进基层治理方式、提升基层社会治理活力和效率的要求。","origin":"逐题标记"}]},"政治理论必刷100题#67":{"stem":"2025 年 6 月，中共中央办公厅、国务院办公厅印发《关于进一步保障和改善民生   着\n\n力解决群众急难愁盼的意见》。对实施医疗卫生强基工程，提出三个“下沉”。下列不属于\n\n三个“下沉”内容的是（          ）。","options":["推动城市医疗资源向县级医院和城乡基层下沉，逐步实现紧密型县域医共体建设全覆\n\n盖","推动远程医疗服务网络下沉，推广“分布式检查、集中式诊断”医疗服务模式","支持高水平医学人才向县级医院下沉，重点强化基层医疗卫生机构短板专业建设","支持高水平医院人员、服务、技术、管理等向基层医疗卫生机构下沉，推进城市医联\n\n体建设"],"answer":"B","analysis":"67.【答案】B\n\n  【解析】\n\n  本题考查理论与政策。\n\n  A、C、D 三项正确，B 项错误，\n                  《关于进一步保障和改善民生     着力解决群众急难愁盼的\n\n意见》在“三、扩大基础民生服务普惠性”部分“（六）推进优质医疗卫生资源共享”中指\n\n出：“推进优质医疗资源扩容下沉和区域均衡布局，优化区域医疗中心建设模式、管理体制\n\n和运行机制。实施医疗卫生强基工程，推动城市医疗资源向县级医院和城乡基层下沉，逐步\n\n实现紧密型县域医共体建设全覆盖。支持高水平医院人员、服务、技术、管理等向基层医疗\n\n卫生机构下沉，推进城市医联体建设。支持高水平医学人才向县级医院下沉，重点强化基层\n\n医疗卫生机构短板专业建设，因地制宜培育办好基层特色专科，提高常见病多发病诊治水平，\n\n推动基层医疗卫生机构提高服务能力。”\n\n  本题为选非题，故正确答案为 B。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","公共管理"],"nature":"知识题","current":true,"links":[{"id":"k-a8a2fb78a556548e","label":"医疗卫生强基工程","catalog_id":"6a7f675fdb5d48b7","type":"制度与规则","role":"直接考查","field":"answer","quote":"推动城市医疗资源向县级医院和城乡基层下沉","why":"三个“下沉”分别涉及城市医疗资源、高水平医院的人员服务技术管理、高水平医学人才，承接范围分别为县级医院和城乡基层、基层医疗卫生机构、县级医院。","origin":"逐题标记"}]},"政治理论必刷100题#68":{"stem":"习近平总书记强调，发展是解决民生问题的“总钥匙”，民生是发展的“指南针”。\n\n坚持在发展中增进民生福祉，下列相关说法不正确的是（           ）。","options":["坚守底线、突出重点、完善制度、引导预期，注重机会公平，保障基本民生","必须加快社会事业改革，解决好人民最关心最直接最现实的利益问题","在发展中保障和改善民生是中国式现代化的唯一任务","必须坚持人人尽责、人人享有，让所有劳动者在推动发展中分享发展成果"],"answer":"C","analysis":"68.【答案】C\n\n  【解析】\n\n  本题考查理论与政策。\n\n  A 项正确，2015 年 10 月 26 日至 29 日，中国共产党第十八届中央委员会第五次全体会\n\n议提出，按照人人参与、人人尽力、人人享有的要求，坚守底线、突出重点、完善制度、引\n\n导预期，注重机会公平，保障基本民生，实现全体人民共同迈入全面小康社会。\n\n  B 项正确，党的十八届三中全会通过的《中共中央关于全面深化改革若干重大问题的决\n\n定》在“十二、推进社会事业改革创新”部分指出：“实现发展成果更多更公平惠及全体人\n\n民，必须加快社会事业改革，解决好人民最关心最直接最现实的利益问题，努力为社会提供\n\n多样化服务，更好满足人民需求。”\n\n  C 项错误，党的二十届三中全会通过的《中共中央关于进一步全面深化改革 推进中国\n\n式现代化的决定》在“十一、健全保障和改善民生制度体系”部分指出：“在发展中保障和\n\n改善民生是中国式现代化的重大任务。必须坚持尽力而为、量力而行，完善基本公共服务制\n\n度体系，加强普惠性、基础性、兜底性民生建设，解决好人民最关心最直接最现实的利益问\n\n题，不断满足人民对美好生活的向往。”故“在发展中保障和改善民生是中国式现代化的唯\n\n一任务”表述错误，应为“在发展中保障和改善民生是中国式现代化的重大任务”。\n\n  D 项正确，\n       《习近平新时代中国特色社会主义思想学习纲要（2023 年版）》第十二章明确\n\n提到：“改善民生既是党和政府工作的方向，也是人民群众自身奋斗的目标。做好民生工作，\n\n必须坚持人人尽责、人人享有，让所有劳动者在推动发展中分享发展成果。”\n\n  本题为选非题，故正确答案为 C。","figs":[],"state":"已标记","notes":[],"domains":["政治理论"],"nature":"知识题","current":false,"links":[{"id":"k-18c308cec72bd4a4","label":"在发展中保障和改善民生是中国式现代化的重大任务","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"在发展中保障和改善民生是中国式现代化的重大任务","why":"题目要求准确把握保障和改善民生在中国式现代化中的任务定位。","origin":"逐题标记"},{"id":"k-84847d642fbd8d82","label":"基本民生保障的底线、重点、制度、预期与机会公平要求","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"坚守底线、突出重点、完善制度、引导预期，注重机会公平，保障基本民生","why":"题目检验基本民生保障的工作要求及机会公平原则。","origin":"逐题标记"},{"id":"k-a055caf0484c20ab","label":"以社会事业改革促进发展成果更多更公平惠及全体人民","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"必须加快社会事业改革，解决好人民最关心最直接最现实的利益问题","why":"加快社会事业改革和回应群众切身利益诉求是促进发展成果公平共享的要求。","origin":"逐题标记"},{"id":"k-909311a1a80d1dc0","label":"民生工作坚持人人尽责、人人享有","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"必须坚持人人尽责、人人享有，让所有劳动者在推动发展中分享发展成果","why":"民生工作将劳动者参与推动发展与共享发展成果相联系。","origin":"逐题标记"}]},"政治理论必刷100题#69":{"stem":"党的十八大以来，我们坚持把教育作为国之大计、党之大计，全面贯彻党的教育方\n\n针，作出深入实施科教兴国战略、加快教育现代化的重大决策。下列关于加快建设教育强国\n\n的说法错误的是（        ）。","options":["坚定不移落实好立德树人根本任务，坚持不懈用马克思主义思想铸魂育人","强化教育对科技和人才的支撑作用，坚持推动教育科技人才良性循环","培养造就新时代高水平教师队伍，实施教育家精神铸魂强师行动，加强师德师风建设","建设具有全球影响力的重要教育中心，深入推动教育对外开放"],"answer":"A","analysis":"69.【答案】A\n\n  【解析】\n\n  本题考查理论与政策。\n\n  2025 年 6 月 1 日出版的第 11 期《求是》杂志发表中共中央总书记、国家主席、中央军\n\n委主席习近平的重要文章《加快建设教育强国》，以下简称文章。\n\n  A 项错误，文章指出，第一，坚定不移落实好立德树人根本任务。坚持不懈用新时代中\n\n国特色社会主义思想铸魂育人，实施新时代立德树人工程，坚持思政课建设与党的创新理论\n\n武装同步推进。故“马克思主义思想”表述有误，应为“新时代中国特色社会主义思想”。\n\n  B 项正确，文章指出，第二，强化教育对科技和人才的支撑作用。坚持推动教育科技人\n\n才良性循环，统筹实施科教兴国战略、人才强国战略、创新驱动发展战略，一体推进教育发\n\n展、科技创新、人才培养。\n\n  C 项正确，文章指出，第四，培养造就新时代高水平教师队伍。实施教育家精神铸魂强\n\n师行动，加强师德师风建设，不断提高教师培养培训质量，统筹优化教师管理与资源配置。\n\n  D 项正确，文章指出，第五，建设具有全球影响力的重要教育中心。深入推动教育对外\n\n开放，统筹“引进来”和“走出去”，不断提升教育国际影响力、竞争力和话语权。\n\n  本题为选非题，故正确答案为 A。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","公共管理"],"nature":"知识题","current":false,"links":[{"id":"k-b04cf0c4881c60de","label":"新时代立德树人工程","catalog_id":"f38d8f67c27bf86e","type":"制度与规则","role":"直接考查","field":"answer","quote":"国特色社会主义思想铸魂育人，实施新时代立德树人工程","why":"落实立德树人根本任务要求坚持用新时代中国特色社会主义思想铸魂育人。","origin":"逐题标记"},{"id":"k-e7676eca049c3ac1","label":"教育对科技和人才的支撑作用与教育科技人才良性循环","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"强化教育对科技和人才的支撑作用，坚持推动教育科技人才良性循环","why":"教育强国建设要求统筹教育发展、科技创新和人才培养，发挥教育的支撑作用。","origin":"逐题标记"},{"id":"k-65185c0762be6570","label":"建设高素质专业化教师队伍","catalog_id":"6b35b860c9e28c54","type":"制度与规则","role":"直接考查","field":"question","quote":"实施教育家精神铸魂强师行动，加强师德师风建设","why":"教育家精神铸魂强师和师德师风建设是培养新时代高水平教师队伍的具体要求。","origin":"逐题标记"},{"id":"k-d79e4f69d14e2138","label":"通过教育对外开放建设具有全球影响力的重要教育中心","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"建设具有全球影响力的重要教育中心，深入推动教育对外开放","why":"相关部署要求统筹教育领域的引进来和走出去，提升教育国际影响力。","origin":"逐题标记"}]},"政治理论必刷100题#70":{"stem":"习近平总书记指出，促进高质量充分就业，是新时代新征程就业工作的新定位、新\n\n使命。关于促进高质量充分就业，下列举措不恰当的是（          ）。","options":["鼓励企业建设职业技能培训基地，形成以市场化培训为主导、行业企业自主培训为主\n\n体的职业技能培训供给体系","推动高等教育高质量发展，扩大理工农医类专业招生规模，根据社会需要、产业需求、\n\n职业开发优化调整学科专业设置","发挥民营企业就业引领作用，综合运用财政支持、税收优惠等政策，引导各类主体更\n\n好履行稳岗扩岗社会责任","健全创业培训、创业服务、创业孵化、创业活动支持体系，优化创业促进就业政策环\n\n境，提升创业质量"],"answer":"C","analysis":"70.【答案】C\n\n  【解析】\n\n  本题考查理论与政策。\n\n  2024 年 9 月，《中共中央   国务院关于实施就业优先战略促进高质量充分就业的意见》\n\n（以下简称《意见》）发布。\n\n  A 项正确，《意见》在“三、着力解决结构性就业矛盾”部分指出：“（七）健全终身\n\n职业技能培训制度。······加强公共实训基地、高技能人才培训基地建设，鼓励企业\n\n建设职业技能培训基地，形成以市场化培训为主导、行业企业自主培训为主体的职业技能培\n\n训供给体系。”\n\n  B 项正确，《意见》在“三、着力解决结构性就业矛盾”部分指出：“（六）提高教育\n\n供给与人才需求的匹配度。······推动高等教育高质量发展，扩大理工农医类专业招\n\n生规模，根据社会需要、产业需求、职业开发优化调整学科专业设置。”\n\n  C 项错误，\n       《意见》在“二、推动经济社会发展与就业促进协调联动”部分指出：“（三）\n\n支持各类经营主体稳岗扩岗。发挥国有企业就业引领作用，综合运用财政支持、税收优惠、\n\n金融支持、社会保障等政策，引导各类主体更好履行稳岗扩岗社会责任。”故“民营企业”\n\n表述有误，应为“国有企业”。\n\n  D 项正确，《意见》在“四、完善重点群体就业支持体系”部分指出：“（十三）优化\n\n自主创业灵活就业保障制度。健全创业培训、创业服务、创业孵化、创业活动支持体系，优\n\n化创业促进就业政策环境，提升创业质量。”\n\n  本题为选非题，故正确答案为 C。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","经济","公共管理"],"nature":"知识题","current":true,"links":[{"id":"k-fa4c9b1efd99976e","label":"职业技能培训供给以市场化培训为主导、行业企业自主培训为主体","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"形成以市场化培训为主导、行业企业自主培训为主体","why":"政策明确了职业技能培训的供给结构，并鼓励企业建设职业技能培训基地。","origin":"逐题标记"},{"id":"k-9eeed367c9360dfe","label":"以扩招理工农医专业和优化专业设置提高教育供需匹配度","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"根据社会需要、产业需求、职业开发优化调整学科专业设置","why":"扩大理工农医类专业招生和按需求优化专业设置是提高教育供给与人才需求匹配度的措施。","origin":"逐题标记"},{"id":"k-41bd0663b65c9692","label":"国有企业发挥就业引领作用与各类经营主体稳岗扩岗","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"发挥国有企业就业引领作用","why":"政策明确了就业引领主体，并要求使用财政、税收等工具引导各类主体履行稳岗扩岗责任。","origin":"逐题标记"},{"id":"k-6732eea197b8c87e","label":"创业培训、服务、孵化和活动支持体系","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"健全创业培训、创业服务、创业孵化、创业活动支持体系","why":"四类支持措施共同用于优化创业促进就业的政策环境、提升创业质量。","origin":"逐题标记"}]},"政治理论必刷100题#71":{"stem":"有效应对我国人口老龄化，事关国家发展全局。下列关于我国养老工作的表述，正\n\n确的有（      ）。\n\n  ①大力发展银发经济，丰富养老服务场景，释放养老消费潜力\n\n  ②建立健全养老服务标准和评价体系，引领养老服务高质量发展\n\n  ③扩大养老保险覆盖面，逐步实现基本养老保险城市人员全覆盖\n\n  ④落实发展养老服务优惠扶持政策，鼓励社会力量参与提供基本养老服务\n\n  ⑤到 2035 年，全体老年人享有基本养老服务，适合我国国情的养老服务体系成熟定型","options":["2 项","3 项","4 项","5 项"],"answer":"C","analysis":"71.【答案】C\n\n  【解析】\n\n  本题考查理论与政策。\n\n  ①正确，《中共中央   国务院关于深化养老服务改革发展的意见》在“四、构建养老服\n\n务事业产业发展三方协同机制”部分指出：“（十一）发挥养老服务产业发展市场配置资源\n\n作用······大力发展银发经济，加强老年用品研发和推广，丰富养老服务场景，释放\n\n养老消费潜力。”\n\n  ②正确，《国务院办公厅关于建立健全养老服务综合监管制度促进养老服务高质量发展\n\n的意见》在“三、创新监管方式”部分指出：“（十二）发挥标准规范引领作用。建立健全\n\n养老服务标准和评价体系，实施养老机构服务质量、安全基本规范等标准，引领养老服务高\n\n质量发展······”\n\n  ③错误，《中共中央   国务院关于加强新时代老龄工作的意见》在“二、健全养老服务\n\n体系”部分指出：“（六）完善多层次养老保障体系。扩大养老保险覆盖面，逐步实现基本\n\n养老保险法定人员全覆盖······”故“城市人员全覆盖”表述有误，应为“法定人员\n\n全覆盖”。\n\n  ④正确，\n     《关于推进基本养老服务体系建设的意见》在“二、重点工作”部分指出：“（三）\n\n完善基本养老服务保障机制······落实发展养老服务优惠扶持政策，鼓励社会力量参\n\n与提供基本养老服务，支持物业服务企业因地制宜提供居家社区养老服务。”\n\n  ⑤正确，《中共中央   国务院关于深化养老服务改革发展的意见》在“一、总体要求”\n\n部分指出：“主要目标是：······到 2035 年，养老服务网络更加健全，服务供给与\n\n需求更加协调适配，全体老年人享有基本养老服务，适合我国国情的养老服务体系成熟定\n\n型。”\n\n  故表述正确的有①②④⑤，共 4 项。\n\n  故正确答案为 C。","figs":[],"state":"待核","notes":["《中共中央 国务院关于深化养老服务改革发展的意见》的发布年份待核。"],"domains":["政治理论","公共管理"],"nature":"知识题","current":false,"links":[{"id":"k-a329c346aba5023e","label":"银发经济","catalog_id":"a7aa1c1117e2d655","type":"制度与规则","role":"直接考查","field":"question","quote":"大力发展银发经济，丰富养老服务场景，释放养老消费潜力","why":"题目考查发展银发经济的具体政策方向，即丰富养老服务场景和释放养老消费潜力。","origin":"逐题标记"},{"id":"k-9000bb8382ecfe18","label":"以养老服务标准和评价体系引领养老服务高质量发展","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"建立健全养老服务标准和评价体系，引领养老服务高质量发展","why":"养老服务监管政策要求以质量、安全等标准和评价体系引领服务发展。","origin":"逐题标记"},{"id":"k-f3787eb1bfac677e","label":"基本养老保险逐步实现法定人员全覆盖","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"养老保险法定人员全覆盖","why":"基本养老保险的扩面目标按法定人员范围界定。","origin":"逐题标记"},{"id":"k-3d692f1b00429d93","label":"以优惠扶持政策鼓励社会力量参与提供基本养老服务","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"落实发展养老服务优惠扶持政策，鼓励社会力量参与提供基本养老服务","why":"政策将社会力量参与服务供给纳入基本养老服务保障机制。","origin":"逐题标记"},{"id":"k-dfa03c2991ab7cf7","label":"到2035年全体老年人享有基本养老服务且养老服务体系成熟定型","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"到 2035 年，全体老年人享有基本养老服务，适合我国国情的养老服务体系成熟定型","why":"题目要求确认改革发展意见规定的目标年份、服务对象和体系建设目标。","origin":"逐题标记"}]},"政治理论必刷100题#72":{"stem":"习近平总书记强调，各地区谋划“十五五”时期经济社会发展，要在全国大局中精\n\n准定位，加强规划衔接。关于科学谋划好“十五五”时期经济社会发展，下列相关表述不正\n\n确的是（       ）。","options":["对各方面的目标任务，要深入分析论证，确保科学精准、能够如期实现","增强维护安全能力，以高效能治理促进高质量发展和高水平安全良性互动","要分别推进教育科技人才独立发展，筑牢新质生产力发展的基础性、战略性支撑","要研究推出一批均衡性可及性强的民生政策举措，着力解决群众急难愁盼问题"],"answer":"C","analysis":"72.【答案】C\n\n  【解析】\n\n  本题考查理论与政策。\n\n  2025 年 4 月 30 日上午，中共中央总书记习近平在上海主持召开部分省区市“十五五”\n\n时期经济社会发展座谈会并发表重要讲话。\n\n  A 项正确，习近平总书记在讲话中强调：“科学制定和接续实施五年规划，是我们党治\n\n国理政一条重要经验，也是中国特色社会主义一个重要政治优势。谋划‘十五五’时期经济\n\n社会发展，必须准确把握‘十五五’时期的阶段性要求······对各方面的目标任务，\n\n要深入分析论证，确保科学精准、能够如期实现。要统筹谋划，抓住关键性、决定性因素，\n\n把握好节奏和进度······”\n\n  B 项正确，习近平总书记在讲话中指出：“谋划‘十五五’时期经济社会发展，要前瞻\n\n性把握国际形势发展变化对我国的影响，因势利导对经济布局进行调整优化。要坚定不移办\n\n好自己的事，坚定不移扩大高水平对外开放······增强维护安全能力，以高效能治理\n\n促进高质量发展和高水平安全良性互动，以新安全格局保障新发展格局。”\n\n  C 项错误，习近平总书记在讲话中强调：“‘十五五’时期，必须把因地制宜发展新质\n\n生产力摆在更加突出的战略位置，以科技创新为引领、以实体经济为根基，坚持全面推进传\n\n统产业转型升级、积极发展新兴产业、超前布局未来产业并举，加快建设现代化产业体\n\n系······要统筹推进教育科技人才一体发展，筑牢新质生产力发展的基础性、战略性\n\n支撑。”故“要分别推进教育科技人才独立发展”说法错误，应为“要统筹推进教育科技人\n\n才一体发展”。\n\n  D 项正确，习近平总书记在讲话中指出：“中国式现代化是全体人民共同富裕的社会主\n\n义现代化。谋划‘十五五’时期经济社会发展，要不忘初心，把造福人民作为根本价值取向，\n\n坚持在发展中保障和改善民生，稳步推动共同富裕······要研究推出一批均衡性可及\n\n性强的民生政策举措，着力解决群众急难愁盼问题。涉及老百姓的事情关键在实，各项政策\n\n举措要实实在在、富有实效，坚持尽力而为、量力而行。”\n\n  本题为选非题，故正确答案为 C。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","公共管理"],"nature":"知识题","current":true,"links":[{"id":"k-a05d0ae16801c166","label":"“十五五”规划目标任务须经分析论证，确保科学精准、能够如期实现","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"要深入分析论证，确保科学精准、能够如期实现","why":"解析确认分析论证是保证规划目标科学可行的要求。","origin":"逐题标记"},{"id":"k-8be9882f382414de","label":"以高效能治理促进高质量发展和高水平安全良性互动","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"以高效能治理促进高质量发展和高水平安全良性互动","why":"该部署明确了以治理效能统筹发展与安全的路径。","origin":"逐题标记"},{"id":"k-db21bc47f4a87c60","label":"统筹推进教育科技人才一体发展以支撑新质生产力","catalog_id":null,"type":"原理与机制","role":"直接考查","field":"answer","quote":"要统筹推进教育科技人才一体发展","why":"一体发展是筑牢新质生产力基础性、战略性支撑的要求。","origin":"逐题标记"},{"id":"k-f9fddb9bab41e56d","label":"“十五五”民生政策须增强均衡性和可及性","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"要研究推出一批均衡性可及性强的民生政策举措，着力解决群众急难愁盼问题","why":"解析确认均衡性、可及性是拟推出民生政策的明确要求。","origin":"逐题标记"}]},"政治理论必刷100题#73":{"stem":"基层是社会的细胞，基层治理是国家治理的基石。我们党始终重视基层建设，不断\n\n加强基层治理。研究总结我们党加强基层治理的探索与经验，有助于在新征程上加强基层治\n\n理体系和治理能力现代化建设，为续写社会长期稳定奇迹新篇章提供学理支撑。关于基层工\n\n作的相关经验，下列对应正确的有几项？\n\n  ①变群众上访为领导下访，深入基层——“枫桥经验”\n\n  ②权力受到约束、村务全面公开、群众有效监督、自我能够纠偏——“后陈经验”\n\n  ③谦和礼让、知进退、和为贵——“六尺巷工作法”\n\n  ④紧紧咬住实体经济发展不放松——“晋江经验”\n\n  ⑤从农村环境整治入手，造就万千美丽乡村——“千万工程”","options":["2","3","4","5"],"answer":"C","analysis":"73.【答案】C\n\n  【解析】\n\n  本题考查理论与政策。\n\n  ①错误，2003 年 9 月 18 日，时任浙江省委书记的习近平同志亲自倡导并带头到金华市\n\n浦江县下访接待群众，推动形成了“变群众上访为领导下访，深入基层，联系群众，真下真\n\n访民情，实心实意办事”为主要内容的“浦江经验”。“枫桥经验”是指 20 世纪 60 年代初，\n\n枫桥镇干部群众总结出的工作原则“小事不出村、大事不出镇、矛盾不上交”。\n\n  ②正确，“后陈经验”是指在 2004 年 6 月，浙江金华武义江畔的后陈村诞生的全国首\n\n个村务监督委员会，以最直接的村务公开，重塑了信任的纽带。其核心理念是“权力受到约\n\n束、村务全面公开、群众有效监督、自我能够纠偏”。\n\n  ③正确，“六尺巷工作法”是安徽省桐城市创新推出的基层治理方法，以六尺巷典故蕴\n\n含的“礼让和谐”文化为核心，通过党建引导、多元调解和群众参与化解矛盾纠纷，实现基\n\n层善治。其主要内涵是“谦和礼让、知进退、和为贵”。\n\n  ④正确，“晋江经验”是 2002 年时任福建省省长的习近平在晋江调研时提出的县域经\n\n济发展模式，核心内容包含“六个始终坚持”和“正确处理好五大关系”，旨在推动政府与\n\n市场协同发展。该经验强调以实体经济为根基，注重传统产业与高新技术产业协调互促，倡\n\n导政府引导服务和市场导向相结合。\n\n  ⑤正确，“千万工程”全称是“千村示范、万村整治”工程。2003 年 6 月，时任浙江\n\n省委书记的习近平同志，以农村生产、生活、生态的“三生”环境改善为重点，在浙江省启\n\n动“千万工程”，从农村环境整治入手，由点及面、迭代升级，持续努力造就万千美丽乡村，\n\n造福万千农民群众，创造了推进乡村全面振兴的成功经验和实践范例。\n\n  故②③④⑤对应正确，共 4 项。\n\n  故正确答案为 C。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","社会治理"],"nature":"知识题","current":false,"links":[{"id":"k-4ee933ef5be993e7","label":"“浦江经验”以领导下访接待群众为主要做法","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"answer","quote":"变群众上访为领导下访，深入基层，联系群众","why":"领导干部主动下访是识别浦江经验的关键做法。","origin":"逐题标记"},{"id":"k-3e0519a056c604c7","label":"“枫桥经验”强调基层就地化解矛盾","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"小事不出村、大事不出镇、矛盾不上交","why":"该原则说明枫桥经验着重把矛盾化解在基层。","origin":"逐题标记"},{"id":"k-181746d46e6fdc2e","label":"“后陈经验”通过村务公开和群众监督约束村级权力","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"权力受到约束、村务全面公开、群众有效监督、自我能够纠偏","why":"村务监督委员会以公开和监督形成村级权力约束与纠偏机制。","origin":"逐题标记"},{"id":"k-4452ac06a25d9a53","label":"“六尺巷工作法”以礼让和谐文化化解基层矛盾","catalog_id":null,"type":"方法与技能","role":"直接考查","field":"answer","quote":"谦和礼让、知进退、和为贵","why":"解析确认礼让和谐是这一基层调解方法的核心。","origin":"逐题标记"},{"id":"k-8624982e9c630b63","label":"“晋江经验”以实体经济为县域经济发展根基","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"该经验强调以实体经济为根基","why":"坚持发展实体经济是辨认这一县域经济发展经验的要点。","origin":"逐题标记"},{"id":"k-8e546bb0b57ff3a5","label":"“千万工程”经验","catalog_id":"ae3e8603d2c7cdac","type":"概念与词义","role":"直接考查","field":"question","quote":"从农村环境整治入手，造就万千美丽乡村——“千万工程”","why":"农村环境整治是这一乡村建设实践的起点。","origin":"逐题标记"}]},"政治理论必刷100题#74":{"stem":"教育是强国建设、民族复兴之基。建设教育强国是全面建成社会主义现代化强国的\n\n战略先导，是实现高水平科技自立自强的重要支撑。关于加快建设教育强国，下列表述不正\n\n确的是（    ）。","options":["强化教育对科技和人才的支撑作用","把立德树人作为教育的根本任务","要建设具有全球影响力的重要教育中心","人民满意度是各级各类教育的生命线"],"answer":"D","analysis":"74.【答案】D\n\n  【解析】\n\n  本题考查理论与政策。\n\n  A 项正确，2025 年 6 月 1 日，《求是》杂志发表习近平总书记的重要文章《加快建设教\n\n育强国》指出：“强化教育对科技和人才的支撑作用。要坚持推动教育科技人才良性循环，\n\n统筹实施科教兴国战略、人才强国战略、创新驱动发展战略，一体推进教育发展、科技创新、\n\n人才培养。要以科技发展、国家战略需求为牵引，着眼提高创新能力，完善高校学科设置调\n\n整机制和人才培养模式。”\n\n  B 项正确，党的二十大报告指出：“全面贯彻党的教育方针，落实立德树人根本任务，\n\n培养德智体美劳全面发展的社会主义建设者和接班人。”\n\n  C 项正确，2025 年 6 月 1 日，《求是》杂志发表习近平总书记的重要文章《加快建设教\n\n育强国》指出：“建设具有全球影响力的重要教育中心。要深入推动教育对外开放，统筹‘引\n\n进来’和‘走出去’，不断提升教育国际影响力、竞争力和话语权。”\n\n  D 项错误，2023 年 5 月 29 日，习近平总书记在二十届中央政治局第五次集体学习时强\n\n调：“要坚持把高质量发展作为各级各类教育的生命线，加快建设高质量教育体系。”选项\n\n中“人民满意度”表述错误，应为“高质量发展”。\n\n  本题为选非题，故本题答案为 D。","figs":[],"state":"已标记","notes":[],"domains":["政治理论"],"nature":"知识题","current":true,"links":[{"id":"k-6052906762f60011","label":"建设教育强国要强化教育对科技和人才的支撑作用","catalog_id":null,"type":"原理与机制","role":"直接考查","field":"answer","quote":"强化教育对科技和人才的支撑作用。","why":"解析以教育发展、科技创新、人才培养一体推进说明这项要求。","origin":"逐题标记"},{"id":"k-f2b489cac21d826a","label":"立德树人是教育的根本任务","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"落实立德树人根本任务","why":"党的二十大报告明确了教育的根本任务。","origin":"逐题标记"},{"id":"k-d79e4f69d14e2138","label":"建设具有全球影响力的重要教育中心","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"建设具有全球影响力的重要教育中心。","why":"教育对外开放要服务于提升教育的国际影响力和竞争力。","origin":"逐题标记","originalId":"k-ffb1a94cba76fe4c"},{"id":"k-4546e942c098e952","label":"高质量发展是各级各类教育的生命线","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"要坚持把高质量发展作为各级各类教育的生命线","why":"该表述明确了建设高质量教育体系的首要质量要求。","origin":"逐题标记"}]},"政治理论必刷100题#75":{"stem":"城市是现代化建设的重要载体、人民幸福生活的重要空间。下列关于推动城市高质\n\n量发展的说法不正确的是（   ）。","options":["发展分散式、独立化的现代化城市群和都市圈，构建布局合理的现代化城市体系","支持超大特大城市布局科技创新平台基地，提升原创性、颠覆性科技创新能力","适时调整扩大经济规模大、人口增长快的县级市和特大镇经济社会管理权限","结合高质量共建“一带一路”，建设一批国际门户枢纽城市和区域性开放节点城市"],"answer":"A","analysis":"75.【答案】A\n\n  【解析】\n\n  本题考查理论与政策。\n\n  2025 年 8 月 15 日，\n                 《中共中央 国务院关于推动城市高质量发展的意见》印发，以下简\n\n称《意见》。\n\n  A 项错误，《意见》在“二、优化现代化城市体系”部分指出：“（一）稳妥有序推动\n\n城市群一体化和都市圈同城化发展。发展组团式、网络化的现代化城市群和都市圈，构建布\n\n局合理的现代化城市体系。”故“分散式、独立化”表述错误，应为“组团式、网络化”。\n\n  B 项正确，《意见》在“二、优化现代化城市体系”部分指出：“（二）增强超大特大\n\n城市综合竞争力······支持超大特大城市布局科技创新平台基地，提升原创性、颠覆\n\n性科技创新能力。推动有条件的省份培育发展省域副中心城市。”\n\n  C 项正确，《意见》在“二、优化现代化城市体系”部分指出：“（三）提高中小城市\n\n和县城承载能力······因地制宜发展小城镇。适时调整扩大经济规模大、人口增长快\n\n的县级市和特大镇经济社会管理权限。”\n\n  D 项正确，《意见》在“三、培育壮大城市发展新动能”部分指出：“（七）提升城市\n\n对外开放合作水平······结合高质量共建‘一带一路’，建设一批国际门户枢纽城市\n\n和区域性开放节点城市。”\n\n  本题为选非题，故正确答案为 A。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","公共管理"],"nature":"知识题","current":true,"links":[{"id":"k-460b58dc5ec080c8","label":"组团式、网络化发展现代化城市群和都市圈","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"城市群一体化和都市圈同城化发展。发展组团式、网络化的现代化城市群和都市圈","why":"组团式、网络化是优化现代化城市体系的明确布局要求。","origin":"逐题标记"},{"id":"k-c91819e2d39ed423","label":"支持超大特大城市布局科技创新平台基地","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"支持超大特大城市布局科技创新平台基地，提升原创性、颠覆性科技创新能力","why":"政策明确了创新平台的布局对象和能力建设目标。","origin":"逐题标记"},{"id":"k-b41208974cfdf04d","label":"适时扩大经济规模大、人口增长快的县级市和特大镇管理权限","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"适时调整扩大经济规模大、人口增长快的县级市和特大镇经济社会管理权限","why":"经济规模、人口增速与行政类别共同界定适用对象。","origin":"逐题标记"},{"id":"k-6310d6fba43245e1","label":"结合高质量共建“一带一路”建设国际门户枢纽和区域性开放节点城市","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"结合高质量共建“一带一路”，建设一批国际门户枢纽城市和区域性开放节点城市","why":"政策明确了提升城市对外开放水平涉及的两类节点城市。","origin":"逐题标记"}]},"政治理论必刷100题#76":{"stem":"处理好发展和保护的关系，是一个世界性难题，也是人类社会发展面临的永恒课题。\n\n下列关于高质量发展和高水平保护，说法不正确的是（     ）。","options":["生态环境保护和经济发展不是矛盾对立的关系，而是辩证统一的关系","生态环境保护的成败归根到底取决于经济结构和经济发展方式","生态优先、绿色低碳的高质量发展只有依靠高水平保护才能实现","高水平保护为高质量发展提供不可或缺的财政、科技、市场等支持"],"answer":"D","analysis":"76.【答案】D\n\n  【解析】\n\n  本题考查理论与政策。\n\n  A、B 两项正确，2018 年 4 月 26 日，习近平总书记主持召开深入推动长江经济带发展座\n\n谈会时发表讲话指出，生态环境保护和经济发展不是矛盾对立的关系，而是辩证统一的关系。\n\n生态环境保护的成败归根到底取决于经济结构和经济发展方式。要坚持在发展中保护、在保\n\n护中发展，不能把生态环境保护和经济发展割裂开来，更不能对立起来。\n\n  C 项正确，2023 年 7 月 17 日，习近平总书记在全国生态环境保护大会上的讲话中指出，\n\n处理好发展和保护的关系，是一个世界性难题，也是人类社会发展面临的永恒课\n\n题······高水平保护是高质量发展的重要支撑，生态优先、绿色低碳的高质量发展只\n\n有依靠高水平保护才能实现。\n\n  D 项错误，2025 年 8 月 5 日，求是网评论员文章《高质量发展和高水平保护不是“二选\n\n一”的单选题》指出，生态环境保护的成败归根结底取决于经济结构和经济发展方式。高质\n\n量发展能够为实现高水平保护提供不可或缺的财政、科技、市场等支持，推进产业生态化和\n\n生态产业化，推动生态环境保护不断迈上新台阶。故选项中“高质量发展”和“高水平保护”\n\n的关系颠倒，表述错误。\n\n  本题为选非题，故正确答案为 D。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","生态环境"],"nature":"知识题","current":false,"links":[{"id":"k-cacaefdbcf2c57c5","label":"生态环境保护和经济发展辩证统一","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"生态环境保护和经济发展不是矛盾对立的关系，而是辩证统一的关系。","why":"二者的辩证统一要求在发展中保护、在保护中发展。","origin":"逐题标记"},{"id":"k-7a817d8e01023095","label":"经济结构和经济发展方式决定生态环境保护的成败","catalog_id":null,"type":"原理与机制","role":"直接考查","field":"question","quote":"生态环境保护的成败归根到底取决于经济结构和经济发展方式","why":"该判断明确了影响生态环境保护成效的根本因素。","origin":"逐题标记"},{"id":"k-9d7db306f7ef0a23","label":"高水平保护是实现生态优先、绿色低碳高质量发展的必要条件","catalog_id":null,"type":"原理与机制","role":"直接考查","field":"question","quote":"生态优先、绿色低碳的高质量发展只有依靠高水平保护才能实现","why":"题目要求识别高水平保护对绿色低碳发展的支撑作用。","origin":"逐题标记"},{"id":"k-2a1eb8773cf05edd","label":"高质量发展为高水平保护提供财政、科技和市场支持","catalog_id":null,"type":"原理与机制","role":"直接考查","field":"answer","quote":"量发展能够为实现高水平保护提供不可或缺的财政、科技、市场等支持","why":"财政、科技和市场支持的供给方向是从高质量发展到高水平保护。","origin":"逐题标记"}]},"政治理论必刷100题#77":{"stem":"人与自然和谐共生是中国式现代化的鲜明特点。中国是世界绿色发展的坚定行动派、\n\n重要贡献者。以下生态文明建设的相关说法，正确的是（    ）。\n\n    ①绿化祖国必须坚持扩绿兴绿护绿“三绿”并举，推动森林水库、油库、财库、碳库“四\n\n库”联动\n\n    ②中央生态环境保护督察是党中央推进生态文明建设的一项重大举措，从压实各级领导\n\n干部生态环境保护政治责任入手\n\n    ③绿色转型必须以人民为中心，协同推进民生福祉改善和气候治理，统筹保护环境、发\n\n展经济、创造就业、消除贫困等多重目标\n\n    ④中国构建了全球最大、发展最快的可再生能源体系，建成了全球最大、最完整的新能\n\n源产业链","options":["①③④","②③④","①②③","①②③④"],"answer":"B","analysis":"77.【答案】B\n\n  【解析】\n\n  本题考查理论与政策。\n\n  ①错误，2025 年 4 月 3 日，习近平总书记在参加首都义务植树活动时指出，绿化祖国\n\n必须坚持扩绿兴绿护绿“三绿”并举，推动森林水库、钱库、粮库、碳库“四库”联动。故\n\n“油库、财库”的说法错误，应是“钱库、粮库”。\n\n  ②正确，2025 年 3 月 31 日，中共中央政治局召开会议审议《生态环境保护督察工作条\n\n例》\n 《关于二十届中央第四轮巡视情况的综合报告》。习近平总书记主持会议。会议指出，中\n\n央生态环境保护督察是党中央推进生态文明建设的一项重大举措，从压实各级领导干部生态\n\n环境保护政治责任入手，严肃查处一批破坏生态环境的重大典型案件，推动解决一批人民群\n\n众反映强烈的突出环境问题，取得良好效果。\n\n  ③正确，2025 年 4 月 23 日，国家主席习近平向气候和公正转型领导人视频峰会发表致\n\n辞。他指出，绿色转型是应对气候变化的必由之路，也是经济社会发展的新引擎。绿色转型\n\n必须以人民为中心，协同推进民生福祉改善和气候治理，统筹保护环境、发展经济、创造就\n\n业、消除贫困等多重目标。\n\n  ④正确，2025 年 4 月 23 日，国家主席习近平向气候和公正转型领导人视频峰会发表致\n\n辞。他指出，自 5 年前我宣布碳达峰碳中和目标以来，中国构建了全球最大、发展最快的可\n\n再生能源体系，建成了全球最大、最完整的新能源产业链。中国还是全球“增绿”最快最多\n\n的国家，贡献了全球四分之一的新增绿色面积。\n\n  综上，②③④表述正确。\n\n  故正确答案为 B。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","生态环境"],"nature":"知识题","current":true,"links":[{"id":"k-491df3789a7323ad","label":"国土绿化坚持扩绿兴绿护绿并举和森林水库、钱库、粮库、碳库联动","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"扩绿兴绿护绿“三绿”并举，推动森林水库、钱库、粮库、碳库“四库”联动","why":"辨别该项须掌握森林“四库”的完整构成。","origin":"逐题标记"},{"id":"k-803336781894757c","label":"中央生态环境保护督察以压实领导干部生态环境保护政治责任为切入点","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"环境保护政治责任入手，严肃查处一批破坏生态环境的重大典型案件","why":"解析将领导干部的政治责任明确为中央督察的切入点。","origin":"逐题标记"},{"id":"k-0171d824b4e74f68","label":"以人民为中心的绿色转型协同推进民生福祉改善和气候治理","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"绿色转型必须以人民为中心，协同推进民生福祉改善和气候治理","why":"该要求以人民福祉为出发点统筹环境、经济、就业和减贫目标。","origin":"逐题标记"},{"id":"k-289b3c85df23fba4","label":"中国建成全球最大、发展最快的可再生能源体系和全球最大、最完整的新能源产业链","catalog_id":null,"type":"事实与事件","role":"直接考查","field":"answer","quote":"建成了全球最大、最完整的新能源产业链","why":"解析同时确认了中国可再生能源体系的规模和发展速度，以及新能源产业链的规模和完整性。","origin":"逐题标记"}]},"政治理论必刷100题#78":{"stem":"党的十八大以来，以习近平同志为核心的党中央把生态文明建设摆在全局工作的突\n\n出位置，全方位、全地域、全过程加强生态环境保护，为全面推进美丽中国建设，加快推进\n\n人与自然和谐共生的现代化筑牢坚实根基。下列关于生态文明建设的表述，说法错误的是\n\n（      ）。","options":["建设生态文明，必须建立系统完整的生态文明制度体系，用制度保护生态环境","构建市场为主导、企业为主体、社会组织和公众共同参与的环境治理体系","健全耕地草原森林河流湖泊休养生息制度，建立市场化、多元化生态补偿机制","必须完善生态文明制度体系，加快完善落实绿水青山就是金山银山理念的体制机制"],"answer":"B","analysis":"78.【答案】B\n\n  【解析】\n\n  本题考查理论与政策。\n\n  A 项正确，《中共中央关于全面深化改革若干重大问题的决定》在“十四、加快生态文\n\n明制度建设”中指出：“建设生态文明，必须建立系统完整的生态文明制度体系，实行最严\n\n格的源头保护制度、损害赔偿制度、责任追究制度，完善环境治理和生态修复制度，用制度\n\n保护生态环境。”\n\n  B 项错误，党的十九大报告在“九、加快生态文明体制改革，建设美丽中国”部分“（二）\n\n着力解决突出环境问题”中指出：“构建政府为主导、企业为主体、社会组织和公众共同参\n\n与的环境治理体系。积极参与全球环境治理，落实减排承诺。”故“市场为主导”说法错误，\n\n应是“政府为主导”。\n\n  C 项正确，党的十九大报告在“九、加快生态文明体制改革，建设美丽中国”部分“（三）\n\n加大生态系统保护力度”中指出：“完善天然林保护制度，扩大退耕还林还草。严格保护耕\n\n地，扩大轮作休耕试点，健全耕地草原森林河流湖泊休养生息制度，建立市场化、多元化生\n\n态补偿机制。”\n\n  D 项正确，\n       《中共中央关于进一步全面深化改革、推进中国式现代化的决定》在“十二、\n\n深化生态文明体制改革”中指出：“中国式现代化是人与自然和谐共生的现代化。必须完善\n\n生态文明制度体系，协同推进降碳、减污、扩绿、增长，积极应对气候变化，加快完善落实\n\n绿水青山就是金山银山理念的体制机制。”\n\n  本题为选非题，故正确答案为 B。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","生态环境","公共管理"],"nature":"知识题","current":false,"links":[{"id":"k-304b862858092a3f","label":"建立系统完整的生态文明制度体系以保护生态环境","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"必须建立系统完整的生态文明制度体系，用制度保护生态环境","why":"制度体系涵盖源头保护、损害赔偿、责任追究、治理和修复。","origin":"逐题标记"},{"id":"k-e24885300c2dde70","label":"环境治理体系由政府主导、企业为主体、社会组织和公众共同参与","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"构建政府为主导、企业为主体、社会组织和公众共同参","why":"识别该表述的关键是明确政府在环境治理体系中的主导地位。","origin":"逐题标记"},{"id":"k-0e51f6a1e7929fc9","label":"健全生态系统休养生息制度和市场化、多元化生态补偿机制","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"健全耕地草原森林河流湖泊休养生息制度，建立市场化、多元化生态补偿机制","why":"该表述明确了休养生息制度的适用对象和生态补偿机制的方向。","origin":"逐题标记"},{"id":"k-49ccabb4215ba52f","label":"完善落实绿水青山就是金山银山理念的体制机制","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"加快完善落实绿水青山就是金山银山理念的体制机制","why":"制度建设要求将这一生态文明理念落实为具体体制机制。","origin":"逐题标记"}]},"政治理论必刷100题#79":{"stem":"生态文明建设功在当代、利在千秋，是关系中华民族永续发展的根本大计。下列有\n\n关新时代生态文明建设的说法正确的有（      ）。\n\n    ①党的十八大将“美丽中国”纳入社会主义现代化强国建设“两步走”的目标\n\n    ②党的二十大提出，推动经济社会发展绿色化、低碳化是实现高质量发展的关键环节\n\n    ③习近平总书记在全国生态环境保护大会上首次提出“绿水青山就是金山银山”的重\n\n要论述\n\n    ④党的十八届三中全会首次提出建立国家公园体制，并将其列入全面深化改革的重点任\n\n务","options":["1 项","2 项","3 项","4 项"],"answer":"B","analysis":"79.【答案】B\n\n  【解析】\n\n  本题考查理论与政策。\n\n  ①错误，党的十八大明确了生态文明建设的总体要求，首次提出“建设美丽中国”，并\n\n将生态文明建设纳入中国特色社会主义事业“五位一体”总体布局。“坚持人与自然和谐共\n\n生”是党的十九大报告提出的新时代坚持和发展中国特色社会主义的基本方略之一，将“美\n\n丽中国”纳入社会主义现代化强国建设“两步走”的目标。\n\n  ②正确，党的二十大提出，推动经济社会发展绿色化、低碳化是实现高质量发展的关键\n\n环节。这表明，高质量发展和高水平保护是相辅相成、相得益彰的。高水平保护是高质量发\n\n展的重要支撑，生态优先、绿色低碳的高质量发展只有依靠高水平保护才能实现。\n\n  ③错误，2005 年 8 月 15 日，时任浙江省委书记的习近平在浙江省安吉县余村考察时，\n\n首次提出“绿水青山就是金山银山”的重要论述。之后，这一金句被广为传播，成为生态文\n\n明核心理念，在新时代引领绿色发展新航程。\n\n  ④正确，2013 年，党的十八届三中全会首次提出建立国家公园体制，并将其列入全面\n\n深化改革的重点任务，中国特色国家公园体制建设正式起步。2015 年起，我国陆续开展 10\n\n处国家公园体制试点。\n         《建立国家公园体制总体方案》\n                      《关于建立以国家公园为主体的自然保\n\n护地体系的指导意见》等重要文件，构建了国家公园制度体系的“四梁八柱”。\n\n  故②④说法正确，共 2 项。\n\n  故正确答案为 B。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","生态环境"],"nature":"知识题","current":false,"links":[{"id":"k-40e7607a47ef3684","label":"“五位一体”总体布局","catalog_id":"8cff63008c52a13e","type":"事实与事件","role":"解题依据","field":"answer","quote":"将生态文明建设纳入中国特色社会主义事业“五位一体”总体布局。","why":"这是党的十八大在生态文明建设总体布局方面的部署。","origin":"逐题标记"},{"id":"k-db622407f2126020","label":"党的十九大将美丽中国纳入社会主义现代化强国建设“两步走”目标","catalog_id":null,"type":"事实与事件","role":"直接考查","field":"answer","quote":"丽中国”纳入社会主义现代化强国建设“两步走”的目标。","why":"解析明确了将美丽中国纳入“两步走”目标的党代会。","origin":"逐题标记"},{"id":"k-aea9547c81db4312","label":"经济社会发展绿色化、低碳化是实现高质量发展的关键环节","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"党的二十大提出，推动经济社会发展绿色化、低碳化是实现高质量发展的关键环节","why":"题目同时核对党的二十大的论述及绿色低碳转型对高质量发展的作用。","origin":"逐题标记"},{"id":"k-78a91568d11054f7","label":"2005年在浙江安吉余村首次提出“绿水青山就是金山银山”","catalog_id":null,"type":"事实与事件","role":"直接考查","field":"answer","quote":"在浙江省安吉县余村考察时，","why":"2005年的余村考察是这一重要论述的首次提出场合。","origin":"逐题标记"},{"id":"k-58182f0cda54d353","label":"党的十八届三中全会首次提出建立国家公园体制","catalog_id":null,"type":"事实与事件","role":"直接考查","field":"answer","quote":"2013 年，党的十八届三中全会首次提出建立国家公园体制","why":"该全会将建立国家公园体制列入全面深化改革的重点任务。","origin":"逐题标记"}]},"政治理论必刷100题#80":{"stem":"习近平总书记指出，要深入贯彻新时代中国特色社会主义生态文明思想，牢固树立\n\n和践行绿水青山就是金山银山的理念。下列有关表述正确的有（        ）。\n\n    ①从解决突出生态环境问题入手，实现由系统治理到重点整治的重大转变\n\n    ②加快构建以国家公园为主体的自然保护地体系\n\n    ③蓝天保卫战要以京津冀及周边、长三角、汾渭平原等重点区域为主战场\n\n    ④生态问题全部以自然恢复为主、辅以必要的人工修复\n\n    ⑤净土保卫战重在强化污染风险管控","options":["②③⑤","②③④","①③④","①②③"],"answer":"A","analysis":"80.【答案】A\n\n  【解析】\n\n  本题考查理论与政策。\n\n  2025 年 7 月 31 日，《求是》杂志发表习近平总书记的重要文章《在全国生态环境保护\n\n大会上的讲话》（以下简称文章）。\n\n  ①错误，文章在“一、新时代生态文明建设取得举世瞩目的巨大成就”部分指出：“我\n\n们从解决突出生态环境问题入手，注重点面结合、标本兼治，实现由重点整治到系统治理的\n\n重大转变。面对资源环境约束趋紧、生态系统退化、环境污染严重等‘国土之殇、民生之痛’，\n\n我们以猛药祛疴、重典治乱的坚强决心和有力举措，坚决查处一批破坏生态环境的重大典型\n\n案件······”故“由系统治理到重点整治”表述有误，应为“由重点整治到系统治\n\n理”。\n\n  ②正确，文章在“一、新时代生态文明建设取得举世瞩目的巨大成就”部分指出：“作\n\n出长江经济带‘共抓大保护、不搞大开发’的战略决策，部署推进黄河流域生态保护和高质\n\n量发展，加快构建以国家公园为主体的自然保护地体系，把绿色发展要求落实到经济社会发\n\n展全过程······”\n\n  ③正确，文章在“三、以美丽中国建设全面推进人与自然和谐共生的现代化”部分指出：\n\n“蓝天保卫战是攻坚战的重中之重。要以京津冀及周边、长三角、汾渭平原等重点区域为主\n\n战场，优化调整产业结构、能源结构、交通运输结构，大力推进挥发性有机物、氮氧化物等\n\n多污染物协同减排，持续降低细颗粒物浓度。”\n\n  ④错误，文章在“二、新征程继续推进生态文明建设需要处理好几个重大关系”部分指\n\n出：“对于水土流失、荒漠化、石漠化等生态退化突出问题，要坚持以自然恢复为主、辅以\n\n必要的人工修复，宜林则林、宜草则草、宜沙则沙、宜荒则荒。对于生态系统受损严重、依\n\n靠自身难以恢复的区域，则要主动采取科学的人工修复措施，加快生态系统恢复进程。城市\n\n特别是超大特大城市和城市群，要积极探索自然恢复和人工修复深度融合的新路子，让城市\n\n更加美丽宜居。”故“全部以自然恢复为主、辅以必要的人工修复”表述有误，应为“水土\n\n流失、荒漠化、石漠化等生态退化突出问题，要坚持以自然恢复为主、辅以必要的人工修复”。\n\n  ⑤正确，文章在“三、以美丽中国建设全面推进人与自然和谐共生的现代化”部分指出：\n\n“净土保卫战重在强化污染风险管控。开展土壤污染源头防控行动，既要防止新增污染，又\n\n要逐步解决长期积累的土壤和地下水严重污染问题······”\n\n  故②③⑤表述正确。\n\n  故正确答案为 A。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","生态环境"],"nature":"知识题","current":false,"links":[{"id":"k-e694bc3481c4e5b9","label":"生态环境治理由重点整治转向系统治理","catalog_id":null,"type":"事实与事件","role":"直接考查","field":"answer","quote":"实现由重点整治到系统治理的","why":"解析给出了治理方式转变的方向。","origin":"逐题标记"},{"id":"k-992083d8d5e2b4cf","label":"构建以国家公园为主体的自然保护地体系","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"加快构建以国家公园为主体的自然保护地体系","why":"题目要求核对自然保护地体系的建设要求。","origin":"逐题标记"},{"id":"k-1f8d4b3e86cc722a","label":"蓝天、碧水、净土保卫战","catalog_id":"285d545a34d41ff8","type":"制度与规则","role":"直接考查","field":"answer","quote":"净土保卫战重在强化污染风险管控。","why":"题目同时核对净土保卫战的污染风险管控要求和蓝天保卫战的主战场，后者包括京津冀及周边、长三角和汾渭平原。","origin":"逐题标记"},{"id":"k-c7730ecb4f004583","label":"按生态退化程度和自行恢复能力选择修复方式","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"靠自身难以恢复的区域，则要主动采取科学的人工修复措施","why":"水土流失等生态退化突出问题以自然恢复为主并辅以必要人工修复，严重受损且难以自行恢复的区域应主动采取人工修复措施。","origin":"逐题标记"}]},"政治理论必刷100题#81":{"stem":"习近平总书记强调，深入推进党的自我革命，坚决打赢反腐败斗争攻坚战持久战。\n\n下列与党的自我革命相关的说法不正确的是（        ）。","options":["推进自我革命，必须固本培元、增强党性","纵深推进全面从严治党，以彻底的自我革命精神把反腐败斗争进行到底","推进党的自我革命必须以完善党内法规体系为根本保证","深入推进党的自我革命，必须把正风肃纪反腐结合起来一起抓"],"answer":"C","analysis":"81.【答案】C\n\n  【解析】\n\n  本题考查理论与政策。\n\n  A 项正确，2025 年 6 月 30 日，习近平总书记在中共中央政治局第二十一次集体学习时\n\n强调，推进自我革命，必须固本培元、增强党性······要加强理论武装，坚守共产党\n\n人精神追求；积极投身中国式现代化建设实践，在干事创业中磨砺奋斗人生，在为民造福中\n\n升华道德境界；积极参加党内政治生活，勇于自我省察，自觉接受党组织教育和各方面监督。\n\n  B 项正确，2024 年 10 月 28 日，习近平总书记主持召开中央政治局会议。会议强调，要\n\n清醒认识反腐败斗争形势，纵深推进全面从严治党，以彻底的自我革命精神把反腐败斗争进\n\n行到底，坚持一体推进不敢腐、不能腐、不想腐，深化标本兼治、系统施治，持续保持惩治\n\n腐败高压态势，不断完善权力配置和运行制约机制，着力铲除腐败滋生的土壤和条件，推动\n\n防范和治理腐败问题常态化、长效化。\n\n  C 项错误，2024 年 12 月 16 日出版的第 24 期《求是》杂志发表习近平总书记重要文章\n\n《深入推进党的自我革命》\n           ，文章中指出：“深入推进党的自我革命，在实践中需要把握好\n\n以下问题。第一，以坚持党中央集中统一领导为根本保证。推进党的自我革命是我们党强身\n\n健体的自觉行动，是为了把党建设得更加坚强有力，更好坚持和加强党的领导。推进党的自\n\n我革命，必须在党中央领导下，统一谋划、统一部署、统一推进，始终沿着正确方向前进。”\n\n故“以完善党内法规体系为根本保证”说法错误，应是“以坚持党中央集中统一领导为根本\n\n保证”。\n\n  D 项正确，2024 年 12 月 16 日出版的第 24 期《求是》杂志发表习近平总书记重要文章\n\n《深入推进党的自我革命》\n           ，文章中指出：“深入推进党的自我革命，在实践中需要把握好\n\n以下问题······第八，以正风肃纪反腐为重要抓手。必须把正风肃纪反腐结合起来一\n\n起抓，始终坚持严的基调、严的措施、严的氛围，以优良作风作引领，以严明纪律强保障，\n\n以反腐惩恶清障碍，推动党的自我革命环环相扣、层层递进，不断在革故鼎新、守正创新中\n\n实现自身跨越。”\n\n  本题为选非题，故正确答案为 C。","figs":[],"state":"已标记","notes":[],"domains":["政治理论"],"nature":"知识题","current":false,"links":[{"id":"k-5edc4405e43bc8f1","label":"坚持党中央集中统一领导是推进党的自我革命的根本保证","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"以坚持党中央集中统一领导为根本保证。","why":"根本保证的准确表述决定了选非判断。","origin":"逐题标记"},{"id":"k-843675050c632a63","label":"增强共产党人的党性","catalog_id":"956d0ec506441030","type":"制度与规则","role":"直接考查","field":"answer","quote":"推进自我革命，必须固本培元、增强党性","why":"题目核对固本培元、增强党性在推进自我革命中的要求。","origin":"逐题标记"},{"id":"k-a45163b1b685436c","label":"以彻底的自我革命精神把反腐败斗争进行到底","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"纵深推进全面从严治党，以彻底的自我革命精神把反腐败斗争进行到底","why":"题目核对纵深推进全面从严治党时对反腐败斗争的要求。","origin":"逐题标记"},{"id":"k-e165bb4de22a4508","label":"正风肃纪反腐是深入推进党的自我革命的重要抓手","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"以正风肃纪反腐为重要抓手。","why":"把正风肃纪反腐结合起来一起抓是题目核对的实践要求。","origin":"逐题标记"}]},"政治理论必刷100题#82":{"stem":"党的十八大以来，党的青年工作取得了重大成就、发生了深刻变革，党对共青团和\n\n青年工作的领导全面加强。下列新时代青年工作的相关表述，错误的是（         ）。","options":["共青团要坚持围绕中心、服务大局，主动对接国家重大战略和重大任务，组织动员广\n\n大青年立足本职岗位","要把加强对广大团员和青年的思想引领摆在首位，努力培养社会主义建设者和接班人","要加强对广大青年的理想信念教育，引导广大青年树立共产主义远大理想，坚定中国\n\n特色社会主义共同理想","共青团是促进青年健康成长的政治学校，政治性是共青团的第一属性"],"answer":"B","analysis":"82.【答案】B\n\n  【解析】\n\n  本题考查理论与政策。\n\n  2025 年 5 月 1 日出版的第 9 期《求是》杂志发表中共中央总书记、国家主席、中央军\n\n委主席习近平的重要文章《激励新时代青年在中国式现代化建设中挺膺担当》（以下简称文\n\n章）。\n\n  A 项正确，文章在“第三，要充分激发新时代青年在中国式现代化建设中挺膺担当”部\n\n分指出：共青团要坚持围绕中心、服务大局，主动对接国家重大战略和重大任务，组织动员\n\n广大青年立足本职岗位，积极投身中国式现代化建设，在科技创新、乡村振兴、绿色发展、\n\n社会服务、卫国戍边等各领域各方面工作中争当排头兵和生力军，展现青春的朝气锐气。\n\n  B 项错误，D 项正确，文章在“第二，要着力加强对广大青年的政治引领”部分指出：\n\n共青团是促进青年健康成长的政治学校，政治性是共青团的第一属性。要把加强对广大团员\n\n和青年的政治引领摆在首位，努力培养社会主义建设者和接班人，源源不断为党输送健康有\n\n活力的新鲜血液。故 B 项“思想引领摆在首位”说法错误，应为“政治引领摆在首位”。\n\n  C 项正确，文章在“第二，要着力加强对广大青年的政治引领”部分指出：要加强对广\n\n大青年的理想信念教育，引导广大青年树立共产主义远大理想，坚定中国特色社会主义共同\n\n理想，坚定听党话、跟党走的政治信念，在强国建设、民族复兴的历史潮流中确立正确的人\n\n生目标，为一生的奋斗奠定基石。\n\n  本题为选非题，故正确答案为 B。","figs":[],"state":"已标记","notes":[],"domains":["政治理论"],"nature":"知识题","current":false,"links":[{"id":"k-279f14414eaebdae","label":"共青团把对广大团员和青年的政治引领摆在首位","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"和青年的政治引领摆在首位","why":"首位要求的准确用语决定了选非判断。","origin":"逐题标记"},{"id":"k-4a2f90cb291e60e3","label":"共青团是促进青年健康成长的政治学校，政治性是第一属性","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"共青团是促进青年健康成长的政治学校，政治性是共青团的第一属性。","why":"题目核对共青团的组织定位和首要属性。","origin":"逐题标记"},{"id":"k-371dfaa7660604a8","label":"共青团围绕中心、服务大局并主动对接国家重大战略和重大任务","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"共青团要坚持围绕中心、服务大局，主动对接国家重大战略和重大任务","why":"题目核对共青团组织动员青年服务国家战略任务的职责。","origin":"逐题标记"},{"id":"k-daf4d949dbcd11ef","label":"青年理想信念教育引导青年树立共产主义远大理想、坚定中国特色社会主义共同理想","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"引导广大青年树立共产主义远大理想，坚定中国特色社会主义共同","why":"题目核对青年理想信念教育所指向的两重理想。","origin":"逐题标记"}]},"政治理论必刷100题#83":{"stem":"下列与健全落实中央八项规定精神、纠治“四风”长效机制相关的表述不正确的是\n\n（           ）。","options":["自我革命是我们党跳出治乱兴衰历史周期率的第一个答案","从抓作风入手推进全面从严治党是新时代党的自我革命一条重要经验","中央八项规定是党中央徙木立信之举，是新时代管党治党的标志性措施","推进自我革命，必须固本培元、增强党性。增强党性，重在坚定理想信念"],"answer":"A","analysis":"83.【答案】A\n\n  【解析】\n\n  本题考查理论与政策。\n\n  A 项错误，B 项正确，2025 年 6 月 30 日，习近平总书记在主持中共中央政治局第二十\n\n一次集体学习时强调，自我革命是我们党跳出治乱兴衰历史周期率的第二个答案，从抓作风\n\n入手推进全面从严治党是新时代党的自我革命一条重要经验。推进党的自我革命，要在提高\n\n认识、增强党性、规范权力运行、从严监督执纪、履行管党治党责任等方面进一步落实到位。\n\n故 A 项“第一个答案”表述有误，应为“第二个答案”。\n\n  C 项正确，2025 年 6 月 30 日，习近平总书记在主持中共中央政治局第二十一次集体学\n\n习时指出，中央八项规定是党中央徙木立信之举，是新时代管党治党的标志性措施。党的十\n\n八大以来，党中央以八项规定开局破题，坚持立铁规矩、强硬约束，坚持以上率下、从中央\n\n政治局带头做起，坚持问题导向、聚焦纠治“四风”开展集中教育和一系列专项整\n\n治······\n\n  D 项正确，2025 年 6 月 30 日，习近平总书记在主持中共中央政治局第二十一次集体学\n\n习时指出，推进自我革命，必须固本培元、增强党性。增强党性，重在坚定理想信念，铸牢\n\n对党忠诚，厚植为民情怀，纯正道德品质，保持清正廉洁。\n\n  本题为选非题，故正确答案为 A。","figs":[],"state":"已标记","notes":[],"domains":["政治理论"],"nature":"知识题","current":false,"links":[{"id":"k-b92feecb2f391090","label":"自我革命是党跳出治乱兴衰历史周期率的第二个答案","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"自我革命是我们党跳出治乱兴衰历史周期率的第二个答案","why":"题目要求准确识别自我革命在这一论述中的定位。","origin":"逐题标记"},{"id":"k-e0203352a43cb7d0","label":"从抓作风入手推进全面从严治党是新时代党的自我革命的重要经验","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"从抓作风入手推进全面从严治党是新时代党的自我革命一条重要经验","why":"题目核对作风建设在推进全面从严治党中的切入作用。","origin":"逐题标记"},{"id":"k-06664d6b16cb709f","label":"中央八项规定是新时代管党治党的标志性措施","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"中央八项规定是党中央徙木立信之举，是新时代管党治党的标志性措施。","why":"题目核对中央八项规定在新时代管党治党中的地位。","origin":"逐题标记"},{"id":"k-843675050c632a63","label":"增强共产党人的党性","catalog_id":"956d0ec506441030","type":"制度与规则","role":"直接考查","field":"answer","quote":"增强党性，重在坚定理想信念","why":"题目直接核对坚定理想信念在增强党性中的地位。","origin":"逐题标记"}]},"政治理论必刷100题#84":{"stem":"党风廉政建设，关键在领导干部。下面关于领导干部带头转变作风的表述，正确的\n\n有（           ）。\n\n     ①领导干部的作风直接关系党内风气和政治生态，关系民心向背，决定着党的群众基础\n\n     ②重点是抓好“关键少数”，管好党员领导干部特别是高级干部、“一把手”\n\n     ③领导干部要努力成为全社会的道德楷模，以实际行动带动全社会崇德向善、尊法守法\n\n     ④各级领导干部要带头转变作风，身体力行，以上率下，形成“羊群效应”\n\n     ⑤领导干部特别是高级干部担负着推进改革的重要职责，要应对风险挑战不退缩，奋力\n\n打开改革发展新天地","options":["2 项","3 项","4 项","5 项"],"answer":"C","analysis":"84.【答案】C\n\n  【解析】\n\n  本题考查理论与政策。\n\n  ①正确，2018 年 1 月 5 日，习近平总书记在新进中央委员会的委员、候补委员和省部\n\n级主要领导干部学习贯彻习近平新时代中国特色社会主义思想和党的十九大精神研讨班开\n\n班式上的讲话中提到，“领导干部的作风直接关系党内风气和政治生态，关系民心向背，决\n\n定着党的群众基础。”\n\n  ②正确，2023 年 1 月 9 日，习近平总书记在二十届中央纪委二次全会上的讲话中提到，\n\n“坚持对象上全覆盖，面向党的各级组织和全体党员，做到管全党、治全党，重点是抓好‘关\n\n键少数’，管好党员领导干部特别是高级干部、‘一把手’······”\n\n  ③正确，2016 年 12 月 9 日，习近平总书记在十八届中央政治局第三十七次集体学习时\n\n的讲话中提到，“领导干部要努力成为全社会的道德楷模，带头践行社会主义核心价值\n\n观······以实际行动带动全社会崇德向善、尊法守法。”\n\n  ④错误，2017 年 12 月，习近平总书记就新华社文章《形式主义、官僚主义新表现值得\n\n警惕》作出的指示中提到，“各级领导干部要带头转变作风，身体力行，以上率下，形成‘头\n\n雁效应’。”故“羊群效应”表述有误，应为“头雁效应”。\n\n  ⑤正确，2024 年 10 月 29 日，习近平总书记在省部级主要领导干部学习贯彻党的二十\n\n届三中全会精神专题研讨班开班式上的讲话中提到，“领导干部特别是高级干部担负着推进\n\n改革的重要职责。要增强政治责任感、历史使命感······应对风险挑战不退缩，奋力\n\n打开改革发展新天地。”\n\n  综上，①②③⑤表述正确，共 4 项。\n\n  故正确答案为 C。","figs":[],"state":"已标记","notes":[],"domains":["政治理论"],"nature":"知识题","current":false,"links":[{"id":"k-67cbe2addb688ac1","label":"领导干部作风关系党内政治生态和党的群众基础","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"领导干部的作风直接关系党内风气和政治生态，关系民心向背，决定着党的群众基础","why":"题目核对领导干部作风对党内风气、民心向背和群众基础的影响。","origin":"逐题标记"},{"id":"k-a40a903e235e6670","label":"全面从严治党重点抓好领导干部这一关键少数","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"重点是抓好“关键少数”，管好党员领导干部特别是高级干部、“一把手”","why":"题目要求识别管党治党的重点对象。","origin":"逐题标记"},{"id":"k-2363b62b516cec73","label":"领导干部以道德示范带动全社会崇德向善、尊法守法","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"领导干部要努力成为全社会的道德楷模，以实际行动带动全社会崇德向善、尊法守法","why":"题目核对领导干部承担的社会道德示范要求。","origin":"逐题标记"},{"id":"k-be03b113032c1281","label":"领导干部带头转变作风应发挥头雁效应","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"应为“头雁效应”。","why":"头雁效应指领导干部身体力行、以上率下形成的示范带动作用。","origin":"逐题标记"},{"id":"k-0279b622bbfc1cdd","label":"领导干部特别是高级干部担负推进改革的重要职责","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"领导干部特别是高级干部担负着推进改革的重要职责","why":"题目核对领导干部在应对风险挑战和推进改革中的责任。","origin":"逐题标记"}]},"政治理论必刷100题#85":{"stem":"中央八项规定既不是最高标准，更不是最终目的，只是我们改进作风的第一步，是\n\n我们作为共产党人应该做到的基本要求。以下有关党的建设的表述，不准确的是（      ）。","options":["各级领导干部要切实履行管党治党责任，作风正派、公道处事，以自身模范行动推动\n\n政治生态持续净化","要坚持党规党纪党务一起抓、正风肃纪反腐相贯通，在铲除腐败滋生的土壤和条件上\n\n常抓不懈","以“同查”严惩风腐交织问题，以“同治”铲除风腐共性根源","增强以案促改促治实效，推动完善权力配置运行的制约和监督机制，丰富防治新型腐\n\n败和隐性腐败有效办法"],"answer":"B","analysis":"85.【答案】B\n\n  【解析】\n\n  本题考查理论与政策。\n\n  A 项正确，2025 年 3 月 19 日至 20 日，习近平总书记在云南考察时的讲话指出：“党的\n\n领导是事业发展的根本保证。看一个地方党的领导和党的建设水平高不高，一个重要方面就\n\n是看政治生态好不好。各级领导干部要切实履行管党治党责任，作风正派、公道处事，以自\n\n身模范行动推动政治生态持续净化。”\n\n  B 项错误，2025 年 3 月 17 日至 18 日，习近平总书记在贵州考察时的讲话指出：“要坚\n\n持党性党风党纪一起抓、正风肃纪反腐相贯通，在铲除腐败滋生的土壤和条件上常抓不懈。”\n\n故“党规党纪党务”表述错误，应为“党性党风党纪”。\n\n  C、D 两项正确，2025 年 1 月 6 日，习近平总书记在二十届中央纪委四次全会上的讲话\n\n指出：“增强以案促改促治实效，推动完善权力配置运行的制约和监督机制，丰富防治新型\n\n腐败和隐性腐败有效办法。坚持正风肃纪反腐相贯通，以‘同查’严惩风腐交织问题，以‘同\n\n治’铲除风腐共性根源。”\n\n  本题为选非题，故正确答案为 B。","figs":[],"state":"已标记","notes":[],"domains":["政治理论"],"nature":"知识题","current":false,"links":[{"id":"k-259e0b87a97a8b62","label":"党性党风党纪一起抓","catalog_id":"73010ca4730714f9","type":"制度与规则","role":"直接考查","field":"answer","quote":"持党性党风党纪一起抓、正风肃纪反腐相贯通","why":"准确识别一起抓的三个方面即可定位用语错误。","origin":"逐题标记"},{"id":"k-22b35f1b6c6a78e3","label":"领导干部履行管党治党责任并以自身模范行动净化政治生态","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"各级领导干部要切实履行管党治党责任，作风正派、公道处事","why":"题目核对领导干部履责和推动政治生态持续净化的要求。","origin":"逐题标记"},{"id":"k-df86a6532824ef9d","label":"风腐同查严惩交织问题、同治铲除共性根源","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"以“同查”严惩风腐交织问题，以“同治”铲除风腐共性根源","why":"题目核对风腐同查与同治各自对应的治理目标。","origin":"逐题标记"},{"id":"k-1f5a2ec1f3c9f176","label":"以案促改促治要求完善权力运行监督并健全新型腐败和隐性腐败防治办法","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"增强以案促改促治实效，推动完善权力配置运行的制约和监督机制","why":"题目核对以案促改促治在权力监督和腐败防治方面的配套要求。","origin":"逐题标记"}]},"政治理论必刷100题#86":{"stem":"习近平总书记强调，“从严监督执纪是党的自我革命的利器，对违纪违法问题必须\n\n坚决处理。”下列关于从严监督执纪的表述，不正确的是（           ）。","options":["要坚持完善党和国家监督制度，形成全面覆盖、常态长效的监督合力","要把党内监督和人民监督结合起来，重视发挥司法监督“前哨”作用","要坚持严管和厚爱相结合，落实“三个区分开来”，激励干部敢于担当、积极作为","要坚持正风肃纪反腐相贯通，以“同查”严惩风腐交织问题，以“同治”铲除风腐共\n\n性根源"],"answer":"B","analysis":"86.【答案】B\n\n  【解析】\n\n  本题考查理论与政策。\n\n  A 项正确，2022 年 1 月 18 日，习近平总书记在十九届中央纪委六次全会上的讲话中提\n\n到：“坚持完善党和国家监督制度，形成全面覆盖、常态长效的监督合力。”\n\n  B 项错误，2025 年 6 月 30 日，习近平总书记在中共中央政治局第二十一次集体学习时\n\n的讲话中提到：“要把党内监督和人民监督结合起来，重视发挥群众监督、舆论监督‘前哨’\n\n作用，推动各类监督贯通协调。”故“发挥司法监督‘前哨’作用”说法错误，应是“发挥\n\n群众监督、舆论监督‘前哨’作用”。\n\n  C 项正确，2022 年 10 月 16 日，习近平总书记在中国共产党第二十次全国代表大会上的\n\n报告中提到：“坚持严管和厚爱相结合，加强对干部全方位管理和经常性监督，落实‘三个\n\n区分开来’，激励干部敢于担当、积极作为。”\n\n  D 项正确，2025 年 1 月 6 日，习近平总书记在二十届中央纪委四次全会上的讲话中提到：\n\n“坚持正风肃纪反腐相贯通，以‘同查’严惩风腐交织问题，以‘同治’铲除风腐共性根\n\n源。”\n\n  本题为选非题，故正确答案为 B。","figs":[],"state":"已标记","notes":[],"domains":["政治理论"],"nature":"知识题","current":false,"links":[{"id":"k-a460727ca8a3699e","label":"党内监督与人民监督相结合，发挥群众监督和舆论监督的前哨作用","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"要把党内监督和人民监督结合起来，重视发挥群众监督、舆论监督‘前哨’","why":"承担前哨作用的监督方式决定了选非判断。","origin":"逐题标记"},{"id":"k-cbc9e0669b3200e8","label":"完善党和国家监督制度，形成全面覆盖、常态长效的监督合力","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"坚持完善党和国家监督制度，形成全面覆盖、常态长效的监督合力。","why":"题目核对党和国家监督制度在覆盖范围与运行常态化方面的要求。","origin":"逐题标记"},{"id":"k-16f3b707864928dd","label":"严管厚爱相结合并落实三个区分开来以激励干部担当","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"坚持严管和厚爱相结合，落实“三个区分开来”，激励干部敢于担当、积极作为","why":"题目核对干部管理中结合严格监督与担当激励的要求。","origin":"逐题标记"},{"id":"k-df86a6532824ef9d","label":"风腐同查严惩交织问题、同治铲除共性根源","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"以‘同查’严惩风腐交织问题","why":"题目核对同查针对交织问题、同治针对共性根源的分工。","origin":"逐题标记"}]},"政治理论必刷100题#87":{"stem":"党的领导和党的建设是我军建设发展的关键，关系强军事业兴衰成败，关系党和国\n\n家长治久安，下列相关表述有误的一项是（       ）。","options":["军队党的建设必须紧紧围绕能打仗、打胜仗来展开","党的力量来自军队，军队强则组织强","选人用人是干部队伍建设的指挥棒，是政治生态的风向标","坚持改革创新，深层激发人才队伍动力活力"],"answer":"B","analysis":"87.【答案】B\n\n  【解析】\n\n  本题考查理论与政策。\n\n  2023 年 7 月，新华社发表名为《在党的旗帜下奋斗强军——以习近平同志为核心的党\n\n中央领导推进新时代人民军队党的领导和党的建设述评》的重要文章（以下简称文章）。\n\n  A 项正确，文章指出，军队党的建设必须紧紧围绕能打仗、打胜仗来展开，成为部队战\n\n斗力的增强剂和功放器。人民军队牢固树立战斗力这个唯一的根本的标准，现代化水平和实\n\n战能力显著提升。\n\n  B 项错误，文章指出，党的力量来自组织，组织强则军队强。人民军队各级党组织领导\n\n力、组织力、执行力不断增强，强军兴军的特有优势持续强固。\n\n  C 项正确，文章指出，选人用人是干部队伍建设的指挥棒，是政治生态的风向标。中央\n\n军委成立人才工作领导小组、干部考评委员会，全方位考察识别、大范围交流使用干部，接\n\n续深化干部工作大检查，匡正选人用人风气，纯洁高级干部队伍。\n\n  D 项正确，文章指出，坚持改革创新，深层激发人才队伍动力活力。人员结构布局深度\n\n优化。大幅压减全军团级以上机关现役员额，精简服务保障等机构和人员。\n\n  本题为选非题，故正确答案为 B。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","军事"],"nature":"知识题","current":false,"links":[{"id":"k-522c911507a1db27","label":"党的力量来自组织，组织强则军队强","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"党的力量来自组织，组织强则军队强。","why":"题目要求准确识别党的力量来源及组织建设对军队建设的作用方向。","origin":"逐题标记"},{"id":"k-b2e8968d79ac7287","label":"军队党的建设围绕能打仗、打胜仗展开","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"军队党的建设必须紧紧围绕能打仗、打胜仗来展开","why":"题目核对军队党的建设以战斗力为导向的要求。","origin":"逐题标记"},{"id":"k-9ebda3c13218d4b5","label":"选人用人对干部队伍建设具有导向作用并反映政治生态","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"选人用人是干部队伍建设的指挥棒，是政治生态的风向标。","why":"题目核对选人用人在干部队伍建设和政治生态中的作用。","origin":"逐题标记"},{"id":"k-f0fe2b99668b4de3","label":"以改革创新激发军队人才队伍的动力活力","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"坚持改革创新，深层激发人才队伍动力活力。","why":"题目核对军队人才队伍建设的改革要求。","origin":"逐题标记"}]},"政治理论必刷100题#88":{"stem":"随着我国日益走近世界舞台中央，周边对中国的战略支撑作用更加重要、更加突出。\n\n我国始终将周边置于外交全局首要位置。关于做好周边工作，下列说法正确的有（          ）。\n\n  ①要以建设和平、富裕、繁荣、美丽、友好“五大家园”为共同愿景\n\n  ②要以睦邻、安邻、富邻、亲诚惠容、命运与共的亚洲安全模式为战略支撑\n\n  ③构建周边命运共同体，要深化发展融合，构建高水平互联互通网络\n\n  ④周边是运筹外交全局的首要、推动构建人类命运共同体的关键","options":["1 项","2 项","3 项","4 项"],"answer":"B","analysis":"88.【答案】B\n\n  【解析】\n\n  本题考查理论与政策。\n\n  2025 年 4 月 8 日至 9 日，中央周边工作会议在北京举行。中共中央总书记、国家主席、\n\n中央军委主席习近平出席会议并发表重要讲话。\n\n  ①②错误，会议指出，要坚持以习近平新时代中国特色社会主义思想为指导，紧紧围绕\n\n党和国家中心任务，统筹国内国际两个大局、发展安全两件大事，高举人类命运共同体旗帜，\n\n以建设和平、安宁、繁荣、美丽、友好“五大家园”为共同愿景，以睦邻、安邻、富邻、亲\n\n诚惠容、命运与共为理念方针，以和平、合作、开放、包容的亚洲价值观为基本遵循，以高\n\n质量共建“一带一路”为主要平台，以安危与共、求同存异、对话协商的亚洲安全模式为战\n\n略支撑，携手周边国家共创美好未来。\n\n  ③正确，会议强调，构建周边命运共同体，要与周边国家巩固战略互信，支持地区国家\n\n走稳自身发展道路，妥善管控矛盾分歧；深化发展融合，构建高水平互联互通网络，加强产\n\n业链供应链合作；共同维护地区稳定，开展安全和执法合作，应对各类风险挑战；扩大交往\n\n交流，便利人员往来。\n\n  ④正确，会议指出，我国幅员辽阔、边界线长，周边是实现发展繁荣的重要基础、维护\n\n国家安全的重点、运筹外交全局的首要、推动构建人类命运共同体的关键。要以全球视野审\n\n视周边，增强做好周边工作的责任感使命感。\n\n  故③④说法正确，共 2 项。\n\n  故正确答案为 B。","figs":[],"state":"已标记","notes":[],"domains":["政治理论"],"nature":"知识题","current":true,"links":[{"id":"k-c6ba5d81a0865505","label":"周边工作以建设和平、安宁、繁荣、美丽、友好“五大家园”为共同愿景","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"以建设和平、安宁、繁荣、美丽、友好“五大家园”为共同愿景","why":"愿景的五项内容决定第一项陈述是否准确。","origin":"逐题标记"},{"id":"k-070e83cdfab10849","label":"周边工作以睦邻、安邻、富邻、亲诚惠容、命运与共为理念方针，以安危与共、求同存异、对话协商的亚洲安全模式为战略支撑","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"以安危与共、求同存异、对话协商的亚洲安全模式为战","why":"判定第二项须区分理念方针与战略支撑各自对应的内容。","origin":"逐题标记"},{"id":"k-7fb9af815df9bccb","label":"构建周边命运共同体要深化发展融合并构建高水平互联互通网络","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"深化发展融合，构建高水平互联互通网络","why":"这是题中检验的发展合作举措。","origin":"逐题标记"},{"id":"k-cab917ca20f64c11","label":"周边是运筹外交全局的首要和推动构建人类命运共同体的关键","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"周边是运筹外交全局的首要、推动构建人类命运共同体的关键","why":"两项定位共同构成题中对周边战略地位的判断。","origin":"逐题标记"}]},"政治理论必刷100题#89":{"stem":"2024 年 12 月 2 日，中共中央总书记、国家主席、中央军委主席习近平在北京出席\n\n第四次“一带一路”建设工作座谈会并发表重要讲话。关于共建“一带一路”，下列说法错\n\n误的是（      ）。","options":["要始终坚持共商共建共享的原则","要以互联互通为主线","要完善“硬联通”、“软联通”、“心联通”协调推进机制","要坚持稳中求进、以进促稳、先立后破工作总基调"],"answer":"D","analysis":"89.【答案】D\n\n  【解析】\n\n  本题考查政治常识。\n\n  A 项正确，习近平指出，自 2013 年提出共建“一带一路”倡议以来，在党中央坚强领\n\n导下，经过各方共同努力，共建“一带一路”始终秉持和平合作、开放包容、互学互鉴、互\n\n利共赢的丝路精神，始终坚持共商共建共享的原则，合作领域不断拓展、合作范围不断扩大、\n\n合作层次不断提升，国际感召力、影响力、凝聚力不断增强，取得了重大成就，为增进同共\n\n建国家友谊、促进共建国家经济社会发展作出了中国贡献。\n\n  B 项正确，D 项错误，习近平指出，共建“一带一路”已经进入高质量发展新阶段。要\n\n坚持稳中求进工作总基调，完整准确全面贯彻新发展理念，加快构建新发展格局，高举人类\n\n命运共同体旗帜，坚持共商共建共享、开放绿色廉洁、高标准惠民生可持续的指导原则，以\n\n高质量共建“一带一路”八项行动为指引，以互联互通为主线。故共建“一带一路”要坚持\n\n“稳中求进”工作总基调，选项中“稳中求进、以进促稳、先立后破”的表述有误。\n\n  C 项正确，习近平强调，要重点推进高质量共建“一带一路”机制建设，完善共建“一\n\n带一路”合作规划统筹管理机制，完善“硬联通”、“软联通”、“心联通”协调推进机制，\n\n完善产业链供应链务实合作机制，完善新兴领域国际交流合作机制，完善投融资多元化保障\n\n机制，完善风险防控内外协同机制，完善海外利益保障机制，完善高水平国际传播机制，完\n\n善廉洁丝绸之路合作机制，推进高质量共建“一带一路”行稳致远。\n\n  本题为选非题，故正确答案为 D。\n\n  【解析视频】","figs":[],"state":"已标记","notes":[],"domains":["政治理论","经济"],"nature":"知识题","current":true,"links":[{"id":"k-25feb76dd68b4557","label":"共建“一带一路”始终坚持共商共建共享原则","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"始终坚持共商共建共享的原则","why":"共商共建共享是题中核对的合作原则。","origin":"逐题标记"},{"id":"k-0433e42edfc26311","label":"高质量共建“一带一路”以互联互通为主线","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"以互联互通为主线","why":"主线的具体内容是判断该表述的依据。","origin":"逐题标记"},{"id":"k-2138844f54632c77","label":"“硬联通”、“软联通”、“心联通”","catalog_id":"5bfcba55f93da9ec","type":"制度与规则","role":"直接考查","field":"answer","quote":"完善“硬联通”、“软联通”、“心联通”协调推进机制","why":"题目核对高质量共建“一带一路”是否要求完善三者的协调推进机制。","origin":"逐题标记"},{"id":"k-f21d7fa71f536ad2","label":"稳中求进工作总基调","catalog_id":"81ecb322a280cd46","type":"制度与规则","role":"直接考查","field":"answer","quote":"坚持稳中求进工作总基调","why":"须核对座谈会对共建“一带一路”工作总基调的准确表述。","origin":"逐题标记"}]},"政治理论必刷100题#90":{"stem":"习近平总书记强调，只有开放的中国，才会成为现代化的中国。下列习近平总书记\n\n有关坚定不移推进高水平对外开放的重要论述，说法有误的是（          ）。","options":["中国已经形成比较健全的利用外资法规政策体系和工作体系","开放是人类文明进步的重要动力，是世界繁荣发展的必由之路","以联合国经济发展委员会为核心的多边贸易体制是国际贸易的基石","法治同开放相伴而行，对外开放向前推进一步，涉外法治建设就要跟进一步"],"answer":"C","analysis":"90.【答案】C\n\n  【解析】\n\n  本题考查理论与政策。\n\n  A 项正确，2025 年 3 月 28 日，习近平总书记在会见国际工商界代表时指出，中国已经\n\n形成比较健全的利用外资法规政策体系和工作体系。我们加强外商投资立法，推动贸易和投\n\n资自由化便利化，积极营造市场化、法治化、国际化一流营商环境，打造透明、稳定、可预\n\n期的政策环境，外资准入负面清单从最早 190 项缩减到现在的全国版 29 项和自贸试验区版\n\n27 项，制造业领域已实现“清零”。\n\n  B 项正确，2022 年 11 月 4 日，习近平总书记在第五届中国国际进口博览会开幕式上的\n\n致辞中指出，开放是人类文明进步的重要动力，是世界繁荣发展的必由之路。当前，世界百\n\n年未有之大变局加速演进，世界经济复苏动力不足。我们要以开放纾发展之困、以开放汇合\n\n作之力、以开放聚创新之势、以开放谋共享之福，推动经济全球化不断向前，增强各国发展\n\n动能，让发展成果更多更公平惠及各国人民。\n\n  C 项错误，2025 年 3 月 28 日，习近平总书记在会见国际工商界代表时指出，以世贸组\n\n织为核心的多边贸易体制是国际贸易的基石。当前，世界开放指数不断下滑，单边主义、保\n\n护主义加剧，多边主义、自由贸易受到严峻挑战。故“以联合国经济发展委员会为核心”表\n\n述有误，应为“以世贸组织为核心”。\n\n  D 项正确，2023 年 11 月 27 日，习近平总书记在二十届中共中央政治局第十次集体学习\n\n时指出，法治同开放相伴而行，对外开放向前推进一步，涉外法治建设就要跟进一步。要坚\n\n持在法治基础上推进高水平对外开放，在扩大开放中推进涉外法治建设，不断夯实高水平开\n\n放的法治根基。\n\n  本题为选非题，故正确答案为 C。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","经济","法律"],"nature":"知识题","current":false,"links":[{"id":"k-250dc0a204f29da1","label":"中国已形成比较健全的利用外资法规政策体系和工作体系","catalog_id":null,"type":"事实与事件","role":"直接考查","field":"question","quote":"中国已经形成比较健全的利用外资法规政策体系和工作体系","why":"该事实判断涉及法规政策和工作体系两方面。","origin":"逐题标记"},{"id":"k-9bc2b77e2c27c62f","label":"开放是人类文明进步的重要动力和世界繁荣发展的必由之路","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"开放是人类文明进步的重要动力，是世界繁荣发展的必由之路","why":"题目核对开放对文明进步和世界繁荣发展的作用。","origin":"逐题标记"},{"id":"k-489d2240ea12e4b2","label":"以世界贸易组织为核心的多边贸易体制是国际贸易的基石","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"应为“以世贸组织为核心”","why":"准确识别多边贸易体制的核心组织决定错误项的判定。","origin":"逐题标记"},{"id":"k-bcbf6952157cb0ea","label":"涉外法治建设应随高水平对外开放同步推进","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"对外开放向前推进一步，涉外法治建设就要跟进一步","why":"题目检验对外开放与涉外法治建设的推进关系。","origin":"逐题标记"}]},"政治理论必刷100题#91":{"stem":"改革开放使中国快速进入世界市场、大踏步赶上时代，重要一条就是积极利用外资。\n\n未来，中国将切实解决外资企业在华发展中遇到的问题，下列具体举措表述正确的有\n\n（     ）。\n\n    ①我们将着力破解市场准入中“大门开、小门不开”的具体问题\n\n    ②我们将保证外资企业依法公平获得生产要素，加快构建全国统一大市场\n\n    ③中国商务部每月召开两次外资企业圆桌会议，听取企业诉求，帮助排忧解难\n\n    ④我们将扩大一些方面开放试点，还将加快文化、教育等领域的开放","options":["①②③","②③④","①②④","①③④"],"answer":"C","analysis":"91.【答案】C\n\n  【解析】\n\n  本题考查理论与政策。\n\n  2025 年 3 月 28 日上午，国家主席习近平在北京人民大会堂会见国际工商界代表并发表\n\n重要讲话。\n\n  ①④正确，习近平总书记在讲话中指出：“一是关于进一步扩大开放。降低市场准入门\n\n槛是我们接下来扩大开放的重点。我专门强调过，落实开放举措宜早不宜迟、宜快不宜慢。\n\n今年，我们将扩大一些方面开放试点，还将加快文化、教育等领域的开放。同时，我们将着\n\n力破解市场准入中‘大门开、小门不开’的具体问题，让外资企业在我们已经开放的领域\n\n‘既准入又准营’。”\n\n  ②正确，习近平总书记在讲话中指出：“二是关于维护市场公平竞争。我们一贯认为，\n\n对于在中国的外资企业，理应保障其国民待遇，做到法律适用上一致、地位待遇上平等。我\n\n们将保证外资企业依法公平获得生产要素，加快构建全国统一大市场，着力整治一些领域的\n\n‘内卷式’竞争，保障外资企业在华生产的产品依法平等参与政府采购······”\n\n  ③错误，习近平总书记在讲话中指出：“三是关于加强服务保障。我多次要求，要加强\n\n同外商沟通交流，为来华贸易投资尽可能提供便利，依法保护外资企业合法权益。中国商务\n\n部每月召开一次外资企业圆桌会议，听取企业诉求，帮助排忧解难······”\n\n  综上，①②④表述正确。\n\n  故正确答案为 C。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","经济"],"nature":"知识题","current":true,"links":[{"id":"k-0807661aee57e16d","label":"破解市场准入中的“大门开、小门不开”问题，保障外资企业在已开放领域既准入又准营","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"‘既准入又准营’","why":"题目核对扩大开放是否要求解决准入后的实际经营障碍。","origin":"逐题标记"},{"id":"k-1a52a78a369b0586","label":"建设全国统一大市场要保障外资企业依法公平获得生产要素","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"保证外资企业依法公平获得生产要素，加快构建全国统一大市场","why":"公平获得生产要素是题中核对的外资国民待遇举措。","origin":"逐题标记"},{"id":"k-0091bb208762e6fe","label":"商务部每月召开一次外资企业圆桌会议","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"部每月召开一次外资企业圆桌会议","why":"实际召开频次决定题中服务保障举措的表述是否准确。","origin":"逐题标记"},{"id":"k-43f645ff244d3f3f","label":"扩大部分领域的开放试点并加快文化、教育等领域开放","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"我们将扩大一些方面开放试点，还将加快文化、教育等领域的开放","why":"扩大试点和加快文化、教育开放是题中核对的两项安排。","origin":"逐题标记"}]},"政治理论必刷100题#92":{"stem":"“法治兴则国兴，法治强则国强。”全面依法治国是国家治理的一场深刻革命，关\n\n系党执政兴国，关系人民幸福安康，关系党和国家长治久安。推进法治中国建设，应进一步\n\n把握好“科学立法、严格执法、公正司法、全民守法”四个环节的关系。关于四个环节的关\n\n系，下列说法正确的是：","options":["科学立法是前提，严格执法是关键，公正司法是防线，全民守法是基础","严格执法是核心，科学立法是保障，全民守法是目标，公正司法是手段","公正司法是首要，全民守法是根本，科学立法是补充，严格执法是辅助","全民守法是重点，科学立法是基础，严格执法是补充，公正司法是保障"],"answer":"A","analysis":"92.【答案】A\n\n  【解析】\n\n  本题考查理论与政策。\n\n  A 项正确，全面推进科学立法、严格执法、公正司法、全民守法，是全面依法治国的重\n\n要环节。①“科学立法”是前提，科学立法为严格执法、公正司法和全民守法提供了明确的\n\n法律依据和行为准则。②“严格执法”是关键，严格执法维护了法律的权威和尊严，保障了\n\n公民的合法权益，为公正司法和全民守法创造了良好的法治环境。③“公正司法”是保障和\n\n防线，公正司法能够维护社会公平正义，增强人民群众对法治的信任和尊重，为全民守法提\n\n供有力的司法保障。④“全民守法”是基础，只有全民守法，才能形成全社会尊法学法守法\n\n用法的良好氛围，为科学立法、严格执法和公正司法提供坚实的群众基础。\n\n  B 项错误，本项将“严格执法”置于核心地位，过度强调执法，忽视立法的基础性作用。\n\n法治的核心应是“良法善治”，而非单一环节。立法应是“前提”而非“保障”，逻辑倒置。\n\n“公正司法是手段”说法亦错误，司法不仅是手段，更是终极救济途径，此说法表述片面。\n\n  C 项错误，公正司法虽重要，但立法和执法是司法发挥作用的前提，不能本末倒置。科\n\n学立法是法治起点，绝非“补充”。严格执法是法律实施的主要方式，“辅助”表述错误。\n\n  D 项错误，全民守法是长期目标，但法治建设需先完善立法、执法、司法环节。执法是\n\n法律实施的关键环节，不可降级为“补充”。\n\n  故正确答案为 A。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","法律"],"nature":"知识题","current":false,"links":[{"id":"k-c11c264a332ce91a","label":"全面依法治国以科学立法为前提、严格执法为关键、公正司法为防线、全民守法为基础","catalog_id":null,"type":"原理与机制","role":"直接考查","field":"question","quote":"科学立法是前提，严格执法是关键，公正司法是防线，全民守法是基础","why":"四个环节与各自功能的对应关系决定整组选项的判定。","origin":"逐题标记"}]},"政治理论必刷100题#93":{"stem":"全面依法治国是国家治理的一场深刻革命，关系党执政兴国，关系人民幸福安康，\n\n关系党和国家长治久安。下列有关说法错误的是（        ）。","options":["坚持依法执政首先要坚持党章确定的中国共产党领导地位不动摇","加强重点领域、新兴领域、涉外领域立法，统筹推进国内法治和涉外法治","扎实推进依法行政，法治政府建设是全面依法治国的重点任务和主体工程","公正司法是维护社会公平正义的最后一道防线，深化司法体制综合配套改革"],"answer":"A","analysis":"93.【答案】A\n\n  【解析】\n\n  本题考查政治常识。\n\n  A 项错误，B 项正确，党的二十大报告在“七、坚持全面依法治国，推进法治中国建设”\n\n部分指出：“（一）完善以宪法为核心的中国特色社会主义法律体系。坚持依法治国首先要\n\n坚持依宪治国，坚持依法执政首先要坚持依宪执政，坚持宪法确定的中国共产党领导地位不\n\n动摇······加强重点领域、新兴领域、涉外领域立法，统筹推进国内法治和涉外法治，\n\n以良法促进发展、保障善治······”\n\n  C 项正确，党的二十大报告在“七、坚持全面依法治国，推进法治中国建设”部分指出：\n\n“（二）扎实推进依法行政。法治政府建设是全面依法治国的重点任务和主体工程。转变政\n\n府职能，优化政府职责体系和组织结构······”\n\n  D 项正确，党的二十大报告在“七、坚持全面依法治国，推进法治中国建设”部分指出：\n\n“（三）严格公正司法。公正司法是维护社会公平正义的最后一道防线。深化司法体制综合\n\n配套改革，全面准确落实司法责任制，加快建设公正高效权威的社会主义司法制\n\n度······”\n\n  本题为选非题，故正确答案为 A。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","法律"],"nature":"知识题","current":false,"links":[{"id":"k-785051fea527ef0c","label":"坚持依法执政首先要坚持依宪执政，坚持宪法确定的中国共产党领导地位","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"坚持依法执政首先要坚持依宪执政，坚持宪法确定的中国共产党领导地位","why":"须识别依法执政的首要要求及该论述所依据的规范。","origin":"逐题标记"},{"id":"k-0e316f9318843f53","label":"加强重点领域、新兴领域、涉外领域立法，统筹推进国内法治和涉外法治","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"加强重点领域、新兴领域、涉外领域立法，统筹推进国内法治和涉外法治","why":"题目核对立法着力领域及国内法治与涉外法治的统筹要求。","origin":"逐题标记"},{"id":"k-c2383a4ccfc99a5b","label":"法治政府建设","catalog_id":"dc297c735547bdb5","type":"制度与规则","role":"直接考查","field":"question","quote":"法治政府建设是全面依法治国的重点任务和主体工程","why":"法治政府建设在全面依法治国中的定位是该项的实质内容。","origin":"逐题标记"},{"id":"k-fc9736bec72386b6","label":"公正司法是维护社会公平正义的最后一道防线，要深化司法体制综合配套改革","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"公正司法是维护社会公平正义的最后一道防线，深化司法体制综合配套改革","why":"题中同时核对公正司法的功能定位和司法体制改革要求。","origin":"逐题标记"}]},"政治理论必刷100题#94":{"stem":"法治是治国理政的基本方式，全面依法治国是坚持和发展中国特色社会主义的本质\n\n要求和重要保障。下列关于习近平法治思想，说法不正确的是：","options":["建设以才为先的高素质法治队伍至关重要","党的政策是国家法律的先导和指引，要通过法律保障党的政策有效实施","严密的法治监督体系以规范和约束公权力为重点","法治政府建设是全面依法治国的重点任务和主体工程"],"answer":"A","analysis":"94.【答案】A\n\n  【解析】\n\n  本题考查理论与政策。\n\n  A 项错误，2014 年 10 月 23 日，习近平总书记在党的十八届四中全会第二次全体会议上\n\n的讲话中指出：“全面推进依法治国，建设一支德才兼备的高素质法治队伍至关重要。”故\n\n“以才为先”表述错误，应为“德才兼备”。\n\n  B 项正确，党的政策是国家法律的先导和指引，是立法的依据和执法司法的重要指导，\n\n要通过法律保障党的政策有效实施。党的政策成为国家法律后，实施法律就是贯彻党的意志，\n\n依法办事就是执行党的政策，不能把二者割裂开来，更不能将二者对立起来。\n\n  C 项正确，严密的法治监督体系，是指以规范和约束公权力为重点建立的有效的法治化\n\n权利监督网络。它以有权必有责、用权受监督、违法必追究，坚决纠正有法不依、执法不严、\n\n违法不究行为等为主要任务，是宪法法律有效实施的重要保障。\n\n  D 项正确，\n       《法治政府建设实施纲要（2021－2025 年）》指出，法治政府建设是全面依法\n\n治国的重点任务和主体工程，是推进国家治理体系和治理能力现代化的重要支撑。\n\n  本题为选非题，故正确答案为 A。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","法律"],"nature":"知识题","current":false,"links":[{"id":"k-bc278a5767c63b77","label":"全面推进依法治国要建设德才兼备的高素质法治队伍","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"建设一支德才兼备的高素质法治队伍至关重要","why":"须掌握法治队伍建设对德与才的准确要求。","origin":"逐题标记"},{"id":"k-1bb034046e908ee5","label":"党的政策是国家法律的先导和指引，法律保障党的政策有效实施","catalog_id":null,"type":"原理与机制","role":"直接考查","field":"question","quote":"党的政策是国家法律的先导和指引，要通过法律保障党的政策有效实施","why":"题目同时检验政策对法律的指引作用和法律对政策实施的保障作用。","origin":"逐题标记"},{"id":"k-58d5cf44b69b7f4f","label":"严密的法治监督体系以规范和约束公权力为重点","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"严密的法治监督体系以规范和约束公权力为重点","why":"公权力的规范和约束是题目核对的监督重点。","origin":"逐题标记"},{"id":"k-c2383a4ccfc99a5b","label":"法治政府建设","catalog_id":"dc297c735547bdb5","type":"制度与规则","role":"直接考查","field":"question","quote":"法治政府建设是全面依法治国的重点任务和主体工程","why":"题目核对法治政府建设在全面依法治国中的定位。","origin":"逐题标记"}]},"政治理论必刷100题#95":{"stem":"习近平指出，全面依法治国是国家治理的一场深刻革命，关系党执政兴国，关系人\n\n民幸福安康，关系党和国家长治久安。下列关于全面依法治国说法正确的是（                            ）。\n\n    ①完善以宪法为核心的中国特色社会主义法律体系\n\n    ②法治社会建设是全面依法治国的重点任务和主体工程\n\n    ③全面准确落实司法责任制，加快建设公正高效权威的社会主义司法制度\n\n    ④建设覆盖城乡的现代公共法律服务体系，深入开展法治宣传教育，增强全民法治观念","options":["①②③","①③④","①②④","①②③④"],"answer":"B","analysis":"95.【答案】B\n\n  【解析】\n\n  本题考查政治常识。\n\n  ①正确，党的二十大报告指出，完善以宪法为核心的中国特色社会主义法律体系。坚持\n\n依法治国首先要坚持依宪治国，坚持依法执政首先要坚持依宪执政，坚持宪法确定的中国共\n\n产党领导地位不动摇，坚持宪法确定的人民民主专政的国体和人民代表大会制度的政体不动\n\n摇。加强宪法实施和监督，健全保证宪法全面实施的制度体系，更好发挥宪法在治国理政中\n\n的重要作用，维护宪法权威。\n\n  ②错误，党的二十大报告指出，扎实推进依法行政。法治政府建设是全面依法治国的重\n\n点任务和主体工程。转变政府职能，优化政府职责体系和组织结构，推进机构、职能、权限、\n\n程序、责任法定化，提高行政效率和公信力。\n\n  ③正确，党的二十大报告指出，严格公正司法。公正司法是维护社会公平正义的最后一\n\n道防线。深化司法体制综合配套改革，全面准确落实司法责任制，加快建设公正高效权威的\n\n社会主义司法制度，努力让人民群众在每一个司法案件中感受到公平正义。\n\n  ④正确，党的二十大报告指出，加快建设法治社会。法治社会是构筑法治国家的基础。\n\n弘扬社会主义法治精神，传承中华优秀传统法律文化，引导全体人民做社会主义法治的忠实\n\n崇尚者、自觉遵守者、坚定捍卫者。建设覆盖城乡的现代公共法律服务体系，深入开展法治\n\n宣传教育，增强全民法治观念。推进多层次多领域依法治理，提升社会治理法治化水平。发\n\n挥领导干部示范带头作用，努力使尊法学法守法用法在全社会蔚然成风。\n\n  综上所述，①③④说法正确。\n\n  故正确答案为 B。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","法律"],"nature":"知识题","current":false,"links":[{"id":"k-bfc18066bbb72edd","label":"完善以宪法为核心的中国特色社会主义法律体系","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"完善以宪法为核心的中国特色社会主义法律体系","why":"宪法的核心地位是判定该项的依据。","origin":"逐题标记"},{"id":"k-c2383a4ccfc99a5b","label":"法治政府建设","catalog_id":"dc297c735547bdb5","type":"制度与规则","role":"直接考查","field":"answer","quote":"法治政府建设是全面依法治国的重","why":"须确认全面依法治国的重点任务和主体工程对应法治政府建设。","origin":"逐题标记"},{"id":"k-b24ada92ba0cb009","label":"全面准确落实司法责任制并建设公正高效权威的社会主义司法制度","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"全面准确落实司法责任制，加快建设公正高效权威的","why":"题目核对严格公正司法在责任落实和制度建设两方面的要求。","origin":"逐题标记"},{"id":"k-62f51a6bb3034262","label":"法治社会建设要健全覆盖城乡的现代公共法律服务体系并增强全民法治观念","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"建设覆盖城乡的现代公共法律服务体系，深入开展法治宣传教育，增强全民法治观念","why":"城乡公共法律服务和法治宣传教育是题中并列核对的建设举措。","origin":"逐题标记"}]},"政治理论必刷100题#96":{"stem":"党的十八大强调，依法治国是党领导人民治理国家的基本方略，法治是治国理政的\n\n基本方式。下列相关表述正确的是（                   ）。\n\n    ①坚持抓住领导干部这个“关键少数”，各级领导干部要带头尊崇法治、敬畏法律\n\n    ②坚持党对全面依法治国的领导，党的领导是推进全面依法治国的根本保证\n\n    ③全面依法治国是一个系统工程，法治政府建设是重点任务和主体工程\n\n    ④2020 年中央全面依法治国工作会议将习近平法治思想明确为全面依法治国的指导思\n\n想","options":["①②③","②③④","①③④","①②③④"],"answer":"D","analysis":"96.【答案】D\n\n  【解析】\n\n  本题考查理论与政策。\n\n  ①正确，2020 年 11 月 16 日至 17 日，习近平在中央全面依法治国工作会议中强调，要\n\n坚持抓住领导干部这个“关键少数”。各级领导干部要坚决贯彻落实党中央关于全面依法治\n\n国的重大决策部署，带头尊崇法治、敬畏法律，了解法律、掌握法律，不断提高运用法治思\n\n维和法治方式深化改革、推动发展、化解矛盾、维护稳定、应对风险的能力，做尊法学法守\n\n法用法的模范。\n\n  ②正确，2020 年 11 月 16 日至 17 日，习近平在中央全面依法治国工作会议中强调，要\n\n坚持党对全面依法治国的领导。党的领导是推进全面依法治国的根本保证。\n\n  ③正确，2020 年 11 月 16 日至 17 日，习近平在中央全面依法治国工作会议中强调，全\n\n面依法治国是一个系统工程，要整体谋划，更加注重系统性、整体性、协同性。法治政府建\n\n设是重点任务和主体工程，要率先突破，用法治给行政权力定规矩、划界限，规范行政决策\n\n程序，加快转变政府职能。\n\n  ④正确，2020 年 11 月 16 日至 17 日，中央全面依法治国工作会议上，将习近平法治思\n\n想明确为全面依法治国的指导思想。\n\n  故①②③④表述正确。\n\n  故正确答案为 D。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","法律"],"nature":"知识题","current":false,"links":[{"id":"k-9938f2750c608d1a","label":"全面依法治国要抓住领导干部这个关键少数","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"各级领导干部要带头尊崇法治、敬畏法律","why":"题目考查领导干部在尊法守法方面的带头要求。","origin":"逐题标记"},{"id":"k-35c89c2d30550b10","label":"党的领导是推进全面依法治国的根本保证","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"党的领导是推进全面依法治国的根本保证。","why":"题目要求识别党的领导在全面依法治国中的地位。","origin":"逐题标记"},{"id":"k-c2383a4ccfc99a5b","label":"法治政府建设","catalog_id":"dc297c735547bdb5","type":"观点与论证","role":"直接考查","field":"question","quote":"法治政府建设是重点任务和主体工程","why":"第三项考查法治政府建设在全面依法治国系统工程中的定位。","origin":"逐题标记"},{"id":"k-3296c53b786698c1","label":"2020年中央全面依法治国工作会议明确习近平法治思想为全面依法治国的指导思想","catalog_id":null,"type":"事实与事件","role":"直接考查","field":"answer","quote":"想明确为全面依法治国的指导思想。","why":"第四项考查确立这一指导思想的会议及其年份。","origin":"逐题标记"}]},"政治理论必刷100题#97":{"stem":"党的十八大以来，习近平总书记多次引经据典、援古证今，赋予典故鲜活的时代内\n\n涵，深刻阐释中国共产党初心如磐、历久弥坚的精神密码。下列关于习近平总书记引用的名\n\n句与其对应的领域说法错误的是（               ）。","options":["草木植成，国之富也——生态文明建设","研理于经正是非，征事于史明成败——文化建设","新松恨不高千尺，恶竹应须斩万竿——社会建设","强不执弱，富不侮贫——外交建设"],"answer":"C","analysis":"97.【答案】C\n\n  【解析】\n\n  本题考查理论与政策。\n\n  A 项正确，“草木植成，国之富也”出自春秋时期齐国政治家、军事家管仲的《管子·立\n\n政》，意思为草木繁殖成长，国家就会富足。2021 年 4 月 30 日，十九届中央政治局就新形\n\n势下加强我国生态文明建设进行第二十九次集体学习，习近平总书记引用《管子》中的“草\n\n木植成，国之富也”，阐述了人与自然和谐共生的关系，进一步明确了生态文明建设在党和\n\n国家事业发展全局中的重要地位。\n\n  B 项正确，“研理于经正是非，征事于史明成败”出自清代学者、文学家、官员纪昀的\n\n《四库全书总目提要·子部总序》，意思为做学问的人，研究儒家经典中的道理，可以验证\n\n天下的是非；征引史籍中的事实，可以明了古今的成败。2022 年 5 月 27 日，中央政治局就\n\n深化中华文明探源工程进行第三十九次集体学习。习近平总书记在主持学习时强调，中华文\n\n明源远流长、博大精深，是中华民族独特的精神标识，是当代中国文化的根基，是维系全世\n\n界华人的精神纽带，也是中国文化创新的宝藏。他引用古语“学者研理于经，可以正天下之\n\n是非；征事于史，可以明古今之成败”，强调要推动中华优秀传统文化创造性转化、创新性\n\n发展，为民族复兴立根铸魂。\n\n  C 项错误，“新松恨不高千尺，恶竹应须斩万竿”出自唐代诗人杜甫的《将赴成都草堂\n\n途中有作，先寄严郑公五首（其四）》\n                ，意思为新栽的松树恨不能快速地长成千尺高树，到处\n\n乱生侵蔓的恶竹应该斩掉它一万杆。2016 年，在第十八届中央纪律检查委员会第六次全体\n\n会议上，习近平总书记引用杜甫的“新松恨不高千尺，恶竹应须斩万竿”诗句，表明了党中\n\n央对党风廉政建设和反腐败斗争的高度重视和坚定决心。他要求持之以恒纠正“四风”，要\n\n咬住“常”“长”二字，经常抓、深入抓、持久抓。除恶务尽，决不允许出现反弹、回潮。\n\n故“社会建设”说法错误，应为“党的建设”。\n\n  D 项正确，“强不执弱，富不侮贫”出自战国时期思想家墨翟的《墨子·兼爱》，意思\n\n是强大者就不会控制弱小者，富足者不会欺侮贫困者。2015 年 11 月 7 日，习近平总书记在\n\n新加坡国立大学的演讲中指出，中国自古倡导“强不执弱，富不侮贫”，深知“国虽大，好\n\n战必亡”的道理。一些人渲染“中国威胁论”，这或者是对中国历史文化和现实政策不了解，\n\n或者是出于一种误解和偏见，或者是有着某种不可告人的目的。中国坚持走和平发展道路，\n\n坚持独立自主的和平外交政策，不是权宜之计，而是我们的战略选择和郑重承诺。\n\n  本题为选非题，故正确答案为 C。","figs":[],"state":"已标记","notes":[],"domains":["政治理论","文化"],"nature":"知识题","current":false,"links":[{"id":"k-32ea6dcd334a310e","label":"“草木植成，国之富也”用于阐释生态文明建设","catalog_id":null,"type":"事实与事件","role":"直接考查","field":"question","quote":"草木植成，国之富也——生态文明建设","why":"这句古语用于阐述人与自然和谐共生及生态文明建设的地位。","origin":"逐题标记"},{"id":"k-d49bb628e40e2ce0","label":"“研理于经正是非，征事于史明成败”用于阐释文化建设","catalog_id":null,"type":"事实与事件","role":"直接考查","field":"question","quote":"研理于经正是非，征事于史明成败——文化建设","why":"这句古语用于说明推动中华优秀传统文化创造性转化和创新性发展的要求。","origin":"逐题标记"},{"id":"k-806d1654cb064f43","label":"“新松恨不高千尺，恶竹应须斩万竿”用于阐释党风廉政建设和反腐败斗争","catalog_id":null,"type":"事实与事件","role":"直接考查","field":"answer","quote":"对党风廉政建设和反腐败斗争的高度重视和坚定决心","why":"杜甫诗句的实际引用语境决定其所属领域为党的建设。","origin":"逐题标记"},{"id":"k-f85699c05c6e0fa0","label":"“强不执弱，富不侮贫”用于阐释中国的和平外交立场","catalog_id":null,"type":"事实与事件","role":"直接考查","field":"question","quote":"强不执弱，富不侮贫——外交建设","why":"这句古语在外交演讲中用于阐明中国坚持走和平发展道路的立场。","origin":"逐题标记"}]},"政治理论必刷100题#98":{"stem":"习 近 平 总书 记 关 于 中 国式 现 代 化 的 重 要论 述 深 刻 回 答了 中 国 式 现 代 化“ 是 什\n\n么”“干什么”“怎样干”等重大理论和实践问题，为丰富和发展马克思主义现代化理论作\n\n出了原创性贡献。下列相关说法正确的有（      ）。\n\n  ①创造性提出中国式现代化是中国共产党领导的社会主义现代化，深刻回答了中国式现\n\n代化的根本政治保证问题\n\n  ②创造性提出中国式现代化的中国特色、本质要求和重大原则，深刻回答了推进中国式\n\n现代化的最高顶层设计问题\n\n  ③创造性提出要统筹兼顾、系统谋划、整体推进中国式现代化，深刻回答了推进中国式\n\n现代化的方法论问题\n\n  ④创造性提出中国式现代化创造了人类文明新形态，深刻回答了中国式现代化对人类文\n\n明发展的重大贡献问题\n\n  ⑤创造性提出推进中国式现代化必须进行伟大斗争，深刻回答了推进中国式现代化的策\n\n略和手段问题","options":["2 项","3 项","4 项","5 项"],"answer":"D","analysis":"98.【答案】D\n\n  【解析】\n\n  本题考查理论与政策。\n\n  2025 年 1 月 1 日，\n                《求是》杂志发表中共中央党史和文献研究院的文章《新时代推进中\n\n国式现代化的根本遵循和行动指南》，文章在“一、习近平总书记关于中国式现代化的重要\n\n论述谱写了现代化理论创新的新篇章”部分指出了习近平总书记关于中国式现代化的重要\n\n论述为丰富和发展马克思主义现代化理论作出的原创性贡献，包括“创造性提出中国式现代\n\n化是中国共产党领导的社会主义现代化，深刻回答了中国式现代化的根本政治保证问\n\n题”“创造性提出中国式现代化的中国特色、本质要求和重大原则，深刻回答了推进中国式\n\n现代化的最高顶层设计问题”“创造性提出要统筹兼顾、系统谋划、整体推进中国式现代化，\n\n深刻回答了推进中国式现代化的方法论问题”“创造性提出中国式现代化创造了人类文明\n\n新形态，深刻回答了中国式现代化对人类文明发展的重大贡献问题”“创造性提出推进中国\n\n式现代化必须进行伟大斗争，深刻回答了推进中国式现代化的策略和手段问题”。\n\n  故①②③④⑤说法正确，共 5 项。\n\n  故正确答案为 D。","figs":[],"state":"已标记","notes":[],"domains":["政治理论"],"nature":"知识题","current":false,"links":[{"id":"k-a80d48336e086c3b","label":"中国共产党的领导是中国式现代化的根本政治保证","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"中国式现代化是中国共产党领导的社会主义现代化","why":"第一项考查对中国式现代化的性质界定如何回答根本政治保证问题。","origin":"逐题标记"},{"id":"k-ba2d59fbd6dbe36b","label":"中国式现代化的中国特色、本质要求和重大原则构成其最高顶层设计","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"中国式现代化的中国特色、本质要求和重大原则","why":"第二项考查这三方面要求共同回答的顶层设计问题。","origin":"逐题标记"},{"id":"k-c1d4398a18111b0a","label":"中国式现代化的方法论要求是统筹兼顾、系统谋划、整体推进","catalog_id":null,"type":"方法与技能","role":"直接考查","field":"question","quote":"统筹兼顾、系统谋划、整体推进中国式现代化","why":"第三项考查整体推进中国式现代化的方法论要求。","origin":"逐题标记"},{"id":"k-f5acca26d0a145eb","label":"中国式现代化对人类文明发展的重大贡献是创造人类文明新形态","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"中国式现代化创造了人类文明新形态","why":"第四项考查人类文明新形态与中国式现代化文明贡献之间的对应。","origin":"逐题标记"},{"id":"k-39587375de80a804","label":"进行伟大斗争是推进中国式现代化的策略和手段","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"推进中国式现代化必须进行伟大斗争","why":"第五项考查进行伟大斗争在推进中国式现代化中的策略定位。","origin":"逐题标记"}]},"政治理论必刷100题#99":{"stem":"国防安全、粮食安全、生态安全、能源安全、产业安全，这“五大安全”是总体国\n\n家安全观的重要领域。下列相关表述不正确的是（        ）。","options":["粮食安全是国家安全的重要基础，是治国理政的头等大事","产业安全是国家安全的重要支撑，是社会向前发展进步的必要动力","生态安全是人类生存发展的基本条件，保护生态环境就是保护生产力","国防安全是国家安全体系的重要组成部分，是维护国家其他安全领域的坚实保障"],"answer":"B","analysis":"99.【答案】B\n\n  【解析】\n\n  本题考查理论与政策。\n\n  A 项正确，粮食安全事关国运民生，维系经济发展和社会稳定，是国家安全的重要基础。\n\n有序的粮食生产、稳定的粮食供给、充足的粮食储备、全面的粮食营养与种类结构等都是粮\n\n食安全的具体体现。\n\n  B 项错误，产业安全是国家经济安全的重要组成部分，是衡量国家发展水平和质量的重\n\n要指标。能源安全是国家安全的重要支撑，是社会向前发展进步的必要动力。\n\n  C 项正确，生态安全是人类生存发展的基本条件，指的是一国具有较为稳定的、完整的、\n\n不受或少受威胁的、能够支撑国家生存发展的生态系统。保护生态环境就是保护生产力，改\n\n善生态环境就是发展生产力。绿水青山就是金山银山，维护生态安全能够为经济安全、社会\n\n安全、国土安全、资源安全筑牢坚实屏障。\n\n  D 项正确，国防安全是国家安全体系的重要组成部分，是维护国家其他安全领域的坚实\n\n保障。从具体内容上看，国防安全涉及国防体制、国防政策、国防科技、国防经济、国防教\n\n育等诸多方面。\n\n  本题为选非题，故正确答案为 B。","figs":[],"state":"已标记","notes":[],"domains":["政治理论"],"nature":"知识题","current":false,"links":[{"id":"k-2be07ba9514f512b","label":"粮食安全是国家安全的重要基础","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"粮食安全事关国运民生，维系经济发展和社会稳定，是国家安全的重要基础。","why":"粮食安全对国计民生和经济社会稳定的作用支撑其基础地位。","origin":"逐题标记"},{"id":"k-ea46679950d6c6b3","label":"产业安全是国家经济安全的重要组成部分","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"产业安全是国家经济安全的重要组成部分","why":"产业安全的实际定位用于辨认题中错置的功能。","origin":"逐题标记"},{"id":"k-b6e50d0d362ea434","label":"能源安全是国家安全的重要支撑和社会发展的必要动力","catalog_id":null,"type":"观点与论证","role":"解题依据","field":"answer","quote":"能源安全是国家安全的重要支撑，是社会向前发展进步的必要动力。","why":"识别这一功能实际归属能源安全，是判断产业安全表述有误的依据。","origin":"逐题标记"},{"id":"k-3b2159f43155efb0","label":"生态安全是人类生存发展的基本条件","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"生态安全是人类生存发展的基本条件，保护生态环境就是保护生产力","why":"题目考查生态系统对人类生存发展的基础作用及生态保护与生产力的关系。","origin":"逐题标记"},{"id":"k-30a39e3f139fa9fc","label":"国防安全为国家其他安全领域提供坚实保障","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"question","quote":"国防安全是国家安全体系的重要组成部分，是维护国家其他安全领域的坚实保障","why":"题目考查国防安全在国家安全体系中的组成地位和保障作用。","origin":"逐题标记"}]},"政治理论必刷100题#100":{"stem":"改革开放以来，我国取得一切成绩和进步的根本原因，归结起来就是：开辟了中国\n\n特色社会主义道路，形成了中国特色社会主义理论体系，确立了中国特色社会主义制度，发\n\n展了中国特色社会主义文化。下列与之有关的说法，有误的是（       ）。","options":["中国特色社会主义道路是实现途径","中国特色社会主义理论体系是伟大旗帜","中国特色社会主义制度是根本保障","中国特色社会主义文化是精神力量"],"answer":"B","analysis":"100.【答案】B\n\n  【解析】\n\n  本题考查理论与政策。\n\n  党的十八大报告指出，中国特色社会主义道路是实现途径，中国特色社会主义理论体系\n\n是行动指南，中国特色社会主义制度是根本保障，三者统一于中国特色社会主义伟大实践。\n\n  A 项正确，中国特色社会主义道路是在中国共产党领导下，全国各族人民在长期实践中\n\n形成的，是实现社会主义现代化和中华民族伟大复兴的必由之路。这条道路具有鲜明的中国\n\n特色，它既坚持了社会主义的基本原则，又根据中国的国情和时代特点进行了创新和发展。\n\n  B 项错误，中国特色社会主义理论体系为中国特色社会主义道路的探索、中国特色社会\n\n主义制度的完善、中国特色社会主义文化的发展提供理论指导，其定位是行动指南。\n\n  C 项正确，中国特色社会主义制度是中国特色社会主义理论体系的实践成果，是中国共\n\n产党和中国人民在长期实践探索中形成的，它包括了一整套相互衔接、相互支撑的制度体系，\n\n是中国特色社会主义事业的根本保障。\n\n  D 项正确，习近平总书记在十九大报告中提出，中国特色社会主义文化是激励全党全国\n\n各族人民奋勇前进的强大精神力量，要坚持中国特色社会主义文化发展道路。\n\n  本题为选非题，故正确答案为 B。","figs":[],"state":"已标记","notes":[],"domains":["政治理论"],"nature":"知识题","current":false,"links":[{"id":"k-7c5e36ff9cccd58e","label":"中国特色社会主义理论体系是行动指南","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"其定位是行动指南。","why":"理论体系的功能定位是识别错误表述的依据。","origin":"逐题标记"},{"id":"k-d28d3f03804913b4","label":"中国特色社会主义道路是实现途径","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"中国特色社会主义道路是实现途径","why":"该定位用于判断题中对道路作用的表述。","origin":"逐题标记"},{"id":"k-c70b2e63a0914ce8","label":"中国特色社会主义制度是根本保障","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"中国特色社会主义制度是根本保障","why":"该定位用于判断题中对制度作用的表述。","origin":"逐题标记"},{"id":"k-df6bd77ec1873bd1","label":"中国特色社会主义文化是精神力量","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"各族人民奋勇前进的强大精神力量","why":"该定位用于判断题中对文化作用的表述。","origin":"逐题标记"}]}}};
